from functools import wraps

def bare(f):
    def wrapper(*a, **k): return f(*a, **k)
    return wrapper

@bare
def docme(): "doc"
docme.__name__, docme.__doc__        # ('wrapper', None) —— 元信息丢了

def proper(f):
    @wraps(f)
    def wrapper(*a, **k): return f(*a, **k)
    return wrapper

@proper
def docme2(): "doc"
docme2.__name__, docme2.__doc__      # ('docme2', 'doc')
docme2.__wrapped__.__name__          # 'docme2' —— __wrapped__ 指向原函数

