    """存储层异常基类。"""


def load() -> list[Bookmark]:
    try:
        raw = json.loads(STORE_PATH.read_text(encoding="utf-8"))
        return [Bookmark(**item) for item in raw]
    except FileNotFoundError:
        return []                          # 首次使用，空库
