package telemetry

import (
    "context"
    "time"

    "go.opentelemetry.io/otel"
    "go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracehttp"
    "go.opentelemetry.io/otel/exporters/prometheus"
    "go.opentelemetry.io/otel/propagation"
    "go.opentelemetry.io/otel/sdk/metric"
    "go.opentelemetry.io/otel/sdk/resource"
    "go.opentelemetry.io/otel/sdk/trace"
    semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
)

func InitProvider(serviceName, otlpEndpoint string) (func(), error) {
    // 设置资源属性
    res, err := resource.New(context.Background(),
        resource.WithAttributes(
            semconv.ServiceNameKey.String(serviceName),
            semconv.ServiceVersionKey.String("1.0.0"),
            semconv.ServiceInstanceIDKey.String("instance-1"),
        ),
    )
    if err != nil {
        return nil, err
    }

    // OTLP HTTP导出器（jaeger 导出器已自 otel-go 移除，改用 OTLP 协议上报，Jaeger 原生支持）
    traceExporter, err := otlptracehttp.New(context.Background(), otlptracehttp.WithEndpointURL(otlpEndpoint))
    if err != nil {
        return nil, err
    }

    // Prometheus导出器
    prometheusExporter, err := prometheus.New()
    if err != nil {
        return nil, err
    }

    // 创建TracerProvider
    tracerProvider := trace.NewTracerProvider(
        trace.WithBatcher(traceExporter),
        trace.WithResource(res),
        trace.WithSampler(trace.AlwaysSample()),
    )

    // 创建MeterProvider
    meterProvider := metric.NewMeterProvider(
        metric.WithResource(res),
        metric.WithReader(prometheusExporter),
    )

    // 设置全局Provider
    otel.SetTracerProvider(tracerProvider)
    otel.SetMeterProvider(meterProvider)
    otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(
        propagation.TraceContext{},
        propagation.Baggage{},
    ))

    // 返回清理函数
    return func() {
        ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
        defer cancel()

        if err := tracerProvider.Shutdown(ctx); err != nil {
            // 处理错误
        }

        if err := meterProvider.Shutdown(ctx); err != nil {
            // 处理错误
        }
    }, nil
}

