    // 业务指标
    orderCount       *prometheus.CounterVec
    orderAmount      *prometheus.HistogramVec
    userActivity     *prometheus.GaugeVec
    conversionRate   *prometheus.GaugeVec

    // 实时统计
    realtimeStats    *RealtimeBusinessStats
