// 关联查询
func FindUsersWithPostCount(db *gorm.DB) ([]User, error) {
    var users []User
    result := db.Model(&User{}).
        Select("users.*, COUNT(posts.id) as post_count").
        Joins("LEFT JOIN posts ON users.id = posts.user_id").
