            return
        }

        c.Next()
    }
}

package pool

import (
    "fmt"
    "sync"
)

type Task interface {
    Execute() error
}

type Worker struct {
    id       int
    taskChan <-chan Task
    wg       *sync.WaitGroup
}

func NewWorker(id int, taskChan <-chan Task, wg *sync.WaitGroup) *Worker {
    return &Worker{
        id:       id,
        taskChan: taskChan,
        wg:       wg,
    }
}

func (w *Worker) Start() {
    go func() {
        defer w.wg.Done()
        for task := range w.taskChan {
            if err := task.Execute(); err != nil {
                // 处理错误
                fmt.Printf("Worker %d task failed: %v\n", w.id, err)
            }
        }
    }()
}

type WorkerPool struct {
    workerCount int
    taskQueue   chan Task
    wg          sync.WaitGroup
}

func NewWorkerPool(workerCount int) *WorkerPool {
    taskQueue := make(chan Task, 100)

    pool := &WorkerPool{
        workerCount: workerCount,
        taskQueue:   taskQueue,
    }

    pool.wg.Add(workerCount)
    for i := 0; i < workerCount; i++ {
        worker := NewWorker(i, taskQueue, &pool.wg)
        worker.Start()
    }

    return pool
}

func (p *WorkerPool) Submit(task Task) {
    p.taskQueue <- task
}

func (p *WorkerPool) Shutdown() {
    close(p.taskQueue)
    p.wg.Wait()
}

package fanout

import (
    "sync"
    "time"
)

func FanOut(data []int, workers int) []int {
    input := make(chan int, len(data))
    results := make(chan int, len(data))

    // 发送数据到channel
    go func() {
        for _, d := range data {
            input <- d
        }
        close(input)
    }()

    // 创建worker goroutines
    var wg sync.WaitGroup
    for i := 0; i < workers; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for d := range input {
                result := process(d) // 处理函数
                results <- result
            }
        }()
    }

    // 收集结果
    go func() {
        wg.Wait()
        close(results)
    }()

    var output []int
    for result := range results {
        output = append(output, result)
    }

    return output
}

func process(data int) int {
    time.Sleep(100 * time.Millisecond) // 模拟处理时间
    return data * 2
}

package context

import (
    "context"
    "fmt"
    "time"
)

func TimeoutOperation() error {
    ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
    defer cancel()

    ch := make(chan string, 1)

    go func() {
        time.Sleep(3 * time.Second) // 模拟长时间操作
        ch <- "completed"
    }()

    select {
    case result := <-ch:
        fmt.Println("Operation completed:", result)
        return nil
    case <-ctx.Done():
        return ctx.Err() // context.DeadlineExceeded
    }
}

package main

import (
    "fmt"
    "log"
    "net/http"
    _ "net/http/pprof" // 注册 pprof HTTP 处理器到默认 mux
    "os"
    "runtime"
    pprof "runtime/pprof"
    "time"
)

func cpuIntensiveTask() {
    for i := 0; i < 1000000; i++ {
        _ = fibonacci(i)
    }
}

func fibonacci(n int) int {
    if n <= 1 {
        return n
    }
    return fibonacci(n-1) + fibonacci(n-2)
}

func main() {
    // 启用pprof
    go func() {
        log.Println(http.ListenAndServe("localhost:6060", nil))
    }()

    // 执行性能测试
    start := time.Now()
    cpuIntensiveTask()
    duration := time.Since(start)

    fmt.Printf("Task completed in %v\n", duration)

    // 创建内存profile
    f, _ := os.Create("mem.prof")
    runtime.GC()
    pprof.WriteHeapProfile(f)
    f.Close()
}

package memory

import (
    "sync"
)

// 对象池避免重复分配
type BufferPool struct {
    pool sync.Pool
}

func NewBufferPool() *BufferPool {
    return &BufferPool{
        pool: sync.Pool{
            New: func() interface{} {
                return make([]byte, 1024)
            },
        },
    }
}

func (p *BufferPool) Get() []byte {
    return p.pool.Get().([]byte)
}

func (p *BufferPool) Put(buf []byte) {
    if cap(buf) > 1024*10 { // 避免保留过大的缓冲区
        return
    }
    p.pool.Put(buf[:0])
}

// 预分配切片避免重复扩容
func PreallocateSlice(size int) []int {
    return make([]int, 0, size)
}

package concurrency

import (
    "sync"
    "time"
)

// Worker pool优化goroutine创建开销
type WorkItem struct {
    ID  int
    Data interface{}
}

type Result struct {
    ItemID int
    Result interface{}
    Error  error
}

func ProcessItemsConcurrently(items []WorkItem, workerCount int) []Result {
    input := make(chan WorkItem, len(items))
    output := make(chan Result, len(items))

    // 发送数据
    go func() {
        for _, item := range items {
            input <- item
        }
        close(input)
    }()

    var wg sync.WaitGroup
    wg.Add(workerCount)

    // 创建worker pool
    for i := 0; i < workerCount; i++ {
        go func(workerID int) {
            defer wg.Done()
            for item := range input {
                result := processItem(item, workerID)
                output <- result
            }
        }(i)
    }

    go func() {
        wg.Wait()
        close(output)
    }()

    // 收集结果
    results := make([]Result, 0, len(items))
    for result := range output {
        results = append(results, result)
    }

    return results
}

func processItem(item WorkItem, workerID int) Result {
    // 模拟处理
    time.Sleep(10 * time.Millisecond)
    return Result{
        ItemID: item.ID,
        Result: item.Data,
        Error:  nil,
    }
}

// internal/config/config.go
package config

import (
    "strings"

    "github.com/spf13/viper"
)

type Config struct {
    Server   ServerConfig   `mapstructure:"server"`
    Database DatabaseConfig `mapstructure:"database"`
    JWT      JWTConfig      `mapstructure:"jwt"`
    Logger   LoggerConfig   `mapstructure:"logger"`
}

type ServerConfig struct {
    Host         string `mapstructure:"host"`
    Port         int    `mapstructure:"port"`
    Mode         string `mapstructure:"mode"`
    ReadTimeout  int    `mapstructure:"read_timeout"`
    WriteTimeout int    `mapstructure:"write_timeout"`
}

type DatabaseConfig struct {
    Host     string `mapstructure:"host"`
    Port     int    `mapstructure:"port"`
    User     string `mapstructure:"user"`
    Password string `mapstructure:"password"`
    DBName   string `mapstructure:"dbname"`
    SSLMode  string `mapstructure:"sslmode"`
}

type JWTConfig struct {
    SecretKey string `mapstructure:"secret_key"`
    ExpiresIn int   `mapstructure:"expires_in"`
}

type LoggerConfig struct {
    Level  string `mapstructure:"level"`
    Format string `mapstructure:"format"`
}

func LoadConfig(configPath string) (*Config, error) {
    viper.SetConfigFile(configPath)
    viper.AutomaticEnv()
    // 关键：让 DB_HOST、SERVER_PORT 等环境变量能覆盖
    // database.host、server.port 等配置项（点号映射为下划线）
    viper.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))

    if err := viper.ReadInConfig(); err != nil {
        return nil, err
    }

    var config Config
    if err := viper.Unmarshal(&config); err != nil {
        return nil, err
    }

    return &config, nil
}

