package main

import (
    "context"
    "errors"
    "log"
    "net/http"
    "os/signal"
    "strconv"
    "syscall"
    "time"
    "your-project/internal/config"
    "your-project/internal/handlers"
    "your-project/internal/middleware"
    "your-project/internal/models"
    "your-project/internal/services"
    "github.com/gin-gonic/gin"
    "go.uber.org/zap"
)

func main() {
    // Load configuration
    cfg, err := config.LoadConfig("configs/config.yaml")
    if err != nil {
        log.Fatalf("Failed to load config: %v", err)
    }

    // Initialize database
    if err := models.InitDatabase(cfg); err != nil {
        log.Fatalf("Failed to initialize database: %v", err)
    }

    // Initialize logger
    logger, err := zap.NewProduction()
    if err != nil {
        log.Fatalf("Failed to initialize logger: %v", err)
    }
    defer logger.Sync()

    // Initialize services
    authService := services.NewAuthService(cfg)
    userService := services.NewUserService(models.GetDB())

    // Initialize handlers
    authHandler := handlers.NewAuthHandler(authService, userService)
    userHandler := handlers.NewUserHandler(userService)

    // Setup Gin router
    if cfg.Server.Mode == "production" {
        gin.SetMode(gin.ReleaseMode)
    }

    router := gin.New()

    // Middleware
    router.Use(middleware.CORSMiddleware())
    router.Use(middleware.LoggingMiddleware(logger))
    router.Use(gin.Recovery())

    // Public routes
    public := router.Group("/api/v1")
    {
        auth := public.Group("/auth")
        {
            auth.POST("/login", authHandler.Login)
        }
    }

    // Protected routes
    protected := router.Group("/api/v1")
    protected.Use(middleware.AuthMiddleware(authService))
    {
        auth := protected.Group("/auth")
        {
            auth.GET("/me", authHandler.GetMe)
        }

        users := protected.Group("/users")
        {
            users.POST("", userHandler.CreateUser)
            users.GET("", userHandler.ListUsers)
            users.GET("/:id", userHandler.GetUser)
            users.PUT("/:id", userHandler.UpdateUser)
            users.DELETE("/:id", userHandler.DeleteUser)
        }
    }

    // Health check
    router.GET("/health", func(c *gin.Context) {
        c.JSON(http.StatusOK, gin.H{"status": "healthy"})
    })

    // Start server：用 http.Server + signal.NotifyContext + Shutdown 实现优雅关停，
    // 收到 SIGINT/SIGTERM 后先停止接收新请求，等待在途请求完成（最长 10 秒）再退出。
    addr := cfg.Server.Host + ":" + strconv.Itoa(cfg.Server.Port)
    srv := &http.Server{
        Addr:         addr,
        Handler:      router,
        ReadTimeout:  time.Duration(cfg.Server.ReadTimeout) * time.Second,
        WriteTimeout: time.Duration(cfg.Server.WriteTimeout) * time.Second,
    }

    ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
    defer stop()

    go func() {
        log.Printf("Server starting on %s", addr)
        if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
            log.Fatalf("Failed to start server: %v", err)
        }
    }()

    <-ctx.Done() // 等待 Ctrl+C / SIGTERM
    log.Println("Shutting down server...")

    shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
    defer cancel()
    if err := srv.Shutdown(shutdownCtx); err != nil {
        log.Fatalf("Server forced to shutdown: %v", err)
    }
    log.Println("Server exited gracefully")
}

