package events

import (
	"context"
	"encoding/json"
	"log"

	"github.com/go-redis/redis/v8"
)

type EventSubscriber struct {
	redis   *redis.Client
	handlers map[string]EventHandler
}

func NewEventSubscriber(redisAddr string) *EventSubscriber {
	return &EventSubscriber{
		redis: redis.NewClient(&redis.Options{
			Addr: redisAddr,
		}),
		handlers: make(map[string]EventHandler),
	}
}

func (s *EventSubscriber) Subscribe(eventType string, handler EventHandler) {
	s.handlers[eventType] = handler
}

func (s *EventSubscriber) Start(ctx context.Context) error {
	pubsub := s.redis.Subscribe(ctx, "events")
	defer pubsub.Close()

	ch := pubsub.Channel()
	for {
		select {
		case <-ctx.Done():
			return nil
		case msg := <-ch:
			var event Event
			if err := json.Unmarshal([]byte(msg.Payload), &event); err != nil {
				log.Printf("Failed to unmarshal event: %v", err)
				continue
			}

			handler, ok := s.handlers[event.Type]
			if !ok {
				log.Printf("No handler for event type: %s", event.Type)
				continue
			}

			if err := handler.Handle(&event); err != nil {
				log.Printf("Failed to handle event: %v", err)
			}
		}
	}
}

// tracing/tracing.go
// 修复说明：go.opentelemetry.io/otel/exporters/jaeger 已在 v1.17.0 冻结并弃用；
// Jaeger 自 v1.35 起原生接收 OTLP 协议，官方推荐路径即 otlptracehttp。
// 对应 docker-compose 需设置 COLLECTOR_OTLP_ENABLED=true，导出端点为 4318 端口。
package tracing

import (
	"context"
	"log"
	"time"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracehttp"
	"go.opentelemetry.io/otel/sdk/resource"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	semconv "go.opentelemetry.io/otel/semconv/v1.43.0"
	"go.opentelemetry.io/otel/trace"
)

func InitTracer(ctx context.Context, serviceName, otlpEndpoint string) (func(), error) {
	// 创建 OTLP/HTTP 导出器（例如 otlpEndpoint = "jaeger:4318"，无需 scheme）
	exp, err := otlptracehttp.New(ctx,
		otlptracehttp.WithEndpoint(otlpEndpoint),
		otlptracehttp.WithInsecure(),
	)
	if err != nil {
		return nil, err
	}

	// 创建资源
	res, err := resource.New(ctx,
		resource.WithAttributes(
			semconv.ServiceName(serviceName),
			semconv.DeploymentEnvironmentNameKey.String("production"),
		),
	)
	if err != nil {
		return nil, err
	}

	// 创建追踪器提供者
	tp := sdktrace.NewTracerProvider(
		sdktrace.WithBatcher(exp),
		sdktrace.WithResource(res),
	)

	// 注册全局追踪器
	otel.SetTracerProvider(tp)

	// 返回清理函数
	return func() {
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := tp.Shutdown(shutdownCtx); err != nil {
			log.Printf("Failed to shutdown tracer provider: %v", err)
		}
	}, nil
}

func StartSpan(ctx context.Context, tracer trace.Tracer, name string) (context.Context, trace.Span) {
	return tracer.Start(ctx, name)
}

// middleware/tracing.go
package middleware

import (
	"net/http"
	"time"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/gin-gonic/gin"
)

func TracingMiddleware(serviceName string) gin.HandlerFunc {
	return func(c *gin.Context) {
		// 创建追踪上下文
		tracer := otel.Tracer(serviceName)
		ctx, span := tracer.Start(c.Request.Context(), c.Request.URL.Path)
		defer span.End()

		// 设置属性
		span.SetAttributes(
			attribute.String("http.method", c.Request.Method),
			attribute.String("http.url", c.Request.URL.String()),
			attribute.String("http.host", c.Request.Host),
			attribute.String("http.scheme", c.Request.URL.Scheme),
		)

		// 更新上下文
		c.Request = c.Request.WithContext(ctx)

		// 继续处理请求
		c.Next()

		// 设置状态码属性
		span.SetAttributes(
			attribute.Int("http.status_code", c.Writer.Status()),
		)
	}
}

