package monitoring

import (
	"strconv"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"
)

var (
	// HTTP请求指标
	httpRequestsTotal = promauto.NewCounterVec(
		prometheus.CounterOpts{
			Name: "http_requests_total",
			Help: "Total number of HTTP requests",
		},
		[]string{"method", "endpoint", "status"},
	)

	httpRequestDuration = promauto.NewHistogramVec(
		prometheus.HistogramOpts{
			Name:    "http_request_duration_seconds",
			Help:    "Duration of HTTP requests",
			Buckets: prometheus.DefBuckets,
		},
		[]string{"method", "endpoint"},
	)

	// 业务指标
	userRegistrationsTotal = promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "user_registrations_total",
			Help: "Total number of user registrations",
		},
	)

	ordersTotal = promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "orders_total",
			Help: "Total number of orders created",
		},
	)

	// 数据库指标
	dbConnectionsActive = promauto.NewGauge(
		prometheus.GaugeOpts{
			Name: "db_connections_active",
			Help: "Number of active database connections",
		},
	)

	// Redis指标
	redisCommandsTotal = promauto.NewCounterVec(
		prometheus.CounterOpts{
			Name: "redis_commands_total",
			Help: "Total number of Redis commands",
		},
		[]string{"command"},
	)
)

func RecordHTTPRequest(method, endpoint string, status int, duration time.Duration) {
	httpRequestsTotal.WithLabelValues(method, endpoint, strconv.Itoa(status)).Inc()
	httpRequestDuration.WithLabelValues(method, endpoint).Observe(duration.Seconds())
}

func RecordUserRegistration() {
	userRegistrationsTotal.Inc()
}

func RecordOrder() {
	ordersTotal.Inc()
}

func UpdateDBConnections(count int) {
	dbConnectionsActive.Set(float64(count))
}

func RecordRedisCommand(command string) {
	redisCommandsTotal.WithLabelValues(command).Inc()
}

// logging/logger.go
package logging

import (
	"log/slog"
	"os"
	"time"

	"github.com/lmittmann/tint"
)

type Logger struct {
	*slog.Logger
}

type LogFields map[string]interface{}

func NewLogger(serviceName string) *Logger {
	handler := tint.NewHandler(os.Stdout, &tint.Options{
		Level:      slog.LevelDebug,
		TimeFormat: time.RFC3339,
		AddSource:  true,
	})

	logger := slog.New(handler)
	logger = logger.With("service", serviceName)

	return &Logger{Logger: logger}
}

func (l *Logger) WithFields(fields LogFields) *Logger {
	var args []interface{}
	for key, value := range fields {
		args = append(args, key, value)
	}
	return &Logger{Logger: l.Logger.With(args...)}
}

func (l *Logger) Info(msg string, fields LogFields) {
	if len(fields) > 0 {
		l.Logger.Info(msg, l.slogFields(fields)...)
	} else {
		l.Logger.Info(msg)
	}
}

func (l *Logger) Error(msg string, fields LogFields) {
	if len(fields) > 0 {
		l.Logger.Error(msg, l.slogFields(fields)...)
	} else {
		l.Logger.Error(msg)
	}
}

func (l *Logger) Debug(msg string, fields LogFields) {
	if len(fields) > 0 {
		l.Logger.Debug(msg, l.slogFields(fields)...)
	} else {
		l.Logger.Debug(msg)
	}
}

func (l *Logger) slogFields(fields LogFields) []interface{} {
	var args []interface{}
	for key, value := range fields {
		args = append(args, key, value)
	}
	return args
}

