// websocket/hub.go
package websocket

import (
	"time"

	"github.com/gorilla/websocket"
)

// Hub 依赖以接口形式声明，避免 websocket 包反向依赖 services 包
type UserService interface {
	UpdateUserStatus(id string, status string) error
}

type MessageService interface {
	SavePrivateMessage(senderID, receiverID, content string) error
	SaveGroupMessage(senderID, groupID, content string) error
	MarkMessageAsRead(messageID string) error
}

type GroupService interface{}

// Hub 的所有状态只在 Run 所在的单一 goroutine 内读写（gorilla 官方 chat 示例模式），
// 因此不需要互斥锁；外部包通过 Submit/Publish/PublishStatus 等导出方法投递事件，
// 而不是直接向未导出的 channel 字段发送（跨包访问未导出字段无法编译）。
type Hub struct {
	// 注册的客户端
	clients map[*Client]bool

	// 用户ID到客户端的映射
	userClients map[string][]*Client

	// 群组ID到客户端的映射
	groupClients map[string][]*Client

	// 广播消息
	broadcast chan []byte

	// 注册/注销客户端
	register   chan *Client
	unregister chan *Client

	// 用户状态更新
	userStatus chan UserStatusUpdate

	// 消息发送队列
	messageQueue chan Message

	// 依赖服务
	userService    UserService
	messageService MessageService
	groupService   GroupService
}

type UserStatusUpdate struct {
	UserID string `json:"user_id"`
	Status string `json:"status"`
}

type Message struct {
	Type    string      `json:"type"`
	Content interface{} `json:"content"`
	From    string      `json:"from"`
	To      string      `json:"to"`
	GroupID string      `json:"group_id,omitempty"`
}

func NewHub(userService UserService, messageService MessageService, groupService GroupService) *Hub {
	return &Hub{
		clients:       make(map[*Client]bool),
		userClients:   make(map[string][]*Client),
		groupClients:  make(map[string][]*Client),
		broadcast:     make(chan []byte, 256),
		register:      make(chan *Client, 256),
		unregister:    make(chan *Client, 256),
		userStatus:    make(chan UserStatusUpdate, 256),
		messageQueue:  make(chan Message, 256),
		userService:   userService,
		messageService: messageService,
		groupService:  groupService,
	}
}

func (h *Hub) Run() {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case client := <-h.register:
			h.handleClientRegister(client)

		case client := <-h.unregister:
			h.handleClientUnregister(client)

		case message := <-h.broadcast:
			h.handleBroadcast(message)

		case status := <-h.userStatus:
			h.handleUserStatusUpdate(status)

		case msg := <-h.messageQueue:
			h.handleMessage(msg)

		case <-ticker.C:
			h.cleanupInactiveClients()
		}
	}
}

func (h *Hub) handleClientRegister(client *Client) {
	// 注册客户端
	h.clients[client] = true

	// 添加到用户客户端映射
	if userID := client.userID; userID != "" {
		h.userClients[userID] = append(h.userClients[userID], client)
	}

	// 发送欢迎消息
	welcome := Message{
		Type:    "system",
		Content: "Welcome to chat server",
		From:    "server",
		To:      client.userID,
	}
	client.send <- welcome.Encode()

	// 广播用户上线通知
	h.broadcastUserStatus(client.userID, "online")
}

// handleClientUnregister 幂等：仅当客户端仍在集合中才处理并 close(send)，
// 从根本上杜绝 handleBroadcast 慢客户端踢出路径与注销路径的 double-close panic。
func (h *Hub) handleClientUnregister(client *Client) {
	if _, ok := h.clients[client]; !ok {
		return
	}

	// 从客户端映射中删除
	delete(h.clients, client)

	// 从用户客户端映射中删除
	if userID := client.userID; userID != "" {
		clients := h.userClients[userID]
		for i, c := range clients {
			if c == client {
				h.userClients[userID] = append(clients[:i], clients[i+1:]...)
				break
			}
		}

		// 如果用户没有其他连接，标记为离线
		if len(h.userClients[userID]) == 0 {
			h.broadcastUserStatus(userID, "offline")
		}
	}

	// 从群组客户端映射中删除
	for groupID, clients := range h.groupClients {
		for i, c := range clients {
			if c == client {
				h.groupClients[groupID] = append(clients[:i], clients[i+1:]...)
				break
			}
		}
	}

	// 关闭发送通道（close 的唯一所有权在 handleClientUnregister）
	close(client.send)
}

func (h *Hub) handleBroadcast(message []byte) {
	for client := range h.clients {
		select {
		case client.send <- message:
		default:
			// 慢客户端：踢出（handleClientUnregister 幂等，不会二次 close）
			h.handleClientUnregister(client)
		}
	}
}

func (h *Hub) handleUserStatusUpdate(status UserStatusUpdate) {
	h.broadcastUserStatus(status.UserID, status.Status)
}

func (h *Hub) handleMessage(msg Message) {
	switch msg.Type {
	case "private":
		h.handlePrivateMessage(msg)
	case "group":
		h.handleGroupMessage(msg)
	case "typing":
		h.handleTypingIndicator(msg)
	case "read":
		h.handleReadReceipt(msg)
	}
}

func (h *Hub) handlePrivateMessage(msg Message) {
	// 发送给接收者
	if clients, ok := h.userClients[msg.To]; ok {
		for _, client := range clients {
			select {
			case client.send <- msg.Encode():
			default:
				h.handleClientUnregister(client)
			}
		}
	}

	// 保存消息到数据库
	h.messageService.SavePrivateMessage(msg.From, msg.To, msg.Content.(string))
}

func (h *Hub) handleGroupMessage(msg Message) {
	// 发送给群组成员
	if clients, ok := h.groupClients[msg.GroupID]; ok {
		for _, client := range clients {
			// 不发送给消息发送者
			if client.userID != msg.From {
				select {
				case client.send <- msg.Encode():
				default:
					h.handleClientUnregister(client)
				}
			}
		}
	}

	// 保存消息到数据库
	h.messageService.SaveGroupMessage(msg.From, msg.GroupID, msg.Content.(string))
}

func (h *Hub) handleTypingIndicator(msg Message) {
	// 发送给特定的用户或群组
	if msg.GroupID != "" {
		// 群组打字状态
		if clients, ok := h.groupClients[msg.GroupID]; ok {
			for _, client := range clients {
				if client.userID != msg.From {
					select {
					case client.send <- msg.Encode():
					default:
						h.handleClientUnregister(client)
					}
				}
			}
		}
	} else {
		// 私聊打字状态
		if clients, ok := h.userClients[msg.To]; ok {
			for _, client := range clients {
				select {
				case client.send <- msg.Encode():
				default:
					h.handleClientUnregister(client)
				}
			}
		}
	}
}

func (h *Hub) handleReadReceipt(msg Message) {
	// 更新消息状态
	h.messageService.MarkMessageAsRead(msg.Content.(string))

	// 通知消息发送者
	if clients, ok := h.userClients[msg.From]; ok {
		for _, client := range clients {
			select {
			case client.send <- msg.Encode():
			default:
				h.handleClientUnregister(client)
			}
		}
	}
}

func (h *Hub) broadcastUserStatus(userID, status string) {
	// 更新用户状态
	h.userService.UpdateUserStatus(userID, status)

	// 广播状态更新（payload 只编码一次）
	statusMsg := Message{
		Type:    "user_status",
		Content: UserStatusUpdate{UserID: userID, Status: status},
		From:    "system",
	}
	payload := statusMsg.Encode()

	// 广播给所有用户（或者只广播给好友/群组成员）
	for client := range h.clients {
		select {
		case client.send <- payload:
		default:
			h.handleClientUnregister(client)
		}
	}
}

func (h *Hub) cleanupInactiveClients() {
	// 清理必须直接调用 handleClientUnregister：
	// 向自身的 unregister 通道发送会造成"自己等自己消费"的自死锁，
	// 而且 handleClientUnregister 内部已做幂等检查，直接调用即可
	for client := range h.clients {
		if time.Since(client.LastActivity()) > 5*time.Minute {
			h.handleClientUnregister(client)
		}
	}
}

// OnlineUsers 返回当前在线用户ID（供 /ws/online-users 路由调用）
func (h *Hub) OnlineUsers() []string {
	userIDs := make([]string, 0, len(h.userClients))
	for userID := range h.userClients {
		userIDs = append(userIDs, userID)
	}
	return userIDs
}

// Submit 供外部包（handlers 等）向 Hub 投递消息，非阻塞。
func (h *Hub) Submit(msg Message) {
	select {
	case h.messageQueue <- msg:
	default: // 队列满时按业务策略处理（丢弃/落库/告警）
	}
}

// PublishStatus 供外部包（Redis 订阅者）投递用户状态更新。
func (h *Hub) PublishStatus(status UserStatusUpdate) {
	select {
	case h.userStatus <- status:
	default:
	}
}

// Publish 供外部包广播原始字节。
func (h *Hub) Publish(payload []byte) {
	select {
	case h.broadcast <- payload:
	default:
	}
}

// ServeClient 注册客户端并启动读写泵（升级成功后由路由层调用）。
func (h *Hub) ServeClient(conn *websocket.Conn, userID string) {
	client := NewClient(h, conn, userID)

	// 注册客户端
	h.register <- client

	// 启动读写goroutine
	go client.WritePump()
	go client.ReadPump()
}

// websocket/client.go
package websocket

import (
	"encoding/json"
	"log"
	"net/http"
	"sync/atomic"
	"time"

	"github.com/gorilla/websocket"
)

// gorilla/websocket 没有包级 Upgrade 函数，只有 Upgrader 类型；
// 路由层通过 websocket.Upgrader.Upgrade(w, r, nil) 完成 HTTP -> WebSocket 协议升级。
var Upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true // 生产环境中应该验证origin
	},
}

const (
	writeWait  = 10 * time.Second
	pongWait   = 60 * time.Second
	pingPeriod = (pongWait * 9) / 10 // 必须小于 pongWait
)

type Client struct {
	hub          *Hub
	conn         *websocket.Conn
	send         chan []byte
	userID       string
	lastActivity atomic.Int64 // UnixNano；ReadPump 写、Hub 清理 goroutine 读，原子操作避免数据竞争
}

func NewClient(hub *Hub, conn *websocket.Conn, userID string) *Client {
	c := &Client{
		hub:    hub,
		conn:   conn,
		send:   make(chan []byte, 256),
		userID: userID,
	}
	c.lastActivity.Store(time.Now().UnixNano())
	return c
}

// LastActivity 供 Hub 清理逻辑无锁读取。
func (c *Client) LastActivity() time.Time {
	return time.Unix(0, c.lastActivity.Load())
}

func (c *Client) ReadPump() {
	defer func() {
		c.hub.unregister <- c
		c.conn.Close()
	}()

	// 读超时 + pong 保活：客户端必须周期性 pong，否则连接被回收
	c.conn.SetReadDeadline(time.Now().Add(pongWait))
	c.conn.SetPongHandler(func(string) error {
		return c.conn.SetReadDeadline(time.Now().Add(pongWait))
	})

	for {
		_, message, err := c.conn.ReadMessage()
		if err != nil {
			if websocket.IsUnexpectedCloseError(err, websocket.CloseGoingAway, websocket.CloseAbnormalClosure) {
				log.Printf("error: %v", err)
			}
			break
		}

		c.lastActivity.Store(time.Now().UnixNano())

		var msg Message
		if err := json.Unmarshal(message, &msg); err != nil {
			log.Printf("error unmarshaling message: %v", err)
			continue
		}

		// 设置发送者
		msg.From = c.userID

		// 处理消息
		c.hub.Submit(msg)
	}
}

func (c *Client) WritePump() {
	ticker := time.NewTicker(pingPeriod)
	defer func() {
		ticker.Stop()
		c.conn.Close()
	}()

	for {
		select {
		case message, ok := <-c.send:
			c.conn.SetWriteDeadline(time.Now().Add(writeWait))
			if !ok {
				// Hub 已 close(send)：发送关闭帧后退出
				c.conn.WriteMessage(websocket.CloseMessage, []byte{})
				return
			}

			if err := c.conn.WriteMessage(websocket.TextMessage, message); err != nil {
				log.Printf("error writing message: %v", err)
				return
			}

		case <-ticker.C:
			c.conn.SetWriteDeadline(time.Now().Add(writeWait))
			if err := c.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		}
	}
}

func (m *Message) Encode() []byte {
	data, _ := json.Marshal(m)
	return data
}

