package handlers

import (
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/your-username/chat-app/models"
	"github.com/your-username/chat-app/services"
	"github.com/your-username/chat-app/websocket"
)

type GroupHandler struct {
	groupService   *services.GroupService
	messageService *services.MessageService
	hub            *websocket.Hub
}

func NewGroupHandler(groupService *services.GroupService, messageService *services.MessageService, hub *websocket.Hub) *GroupHandler {
	return &GroupHandler{
		groupService:   groupService,
		messageService: messageService,
		hub:            hub,
	}
}

func (h *GroupHandler) CreateGroup(c *gin.Context) {
	userID := c.MustGet("user_id").(string)

	var req struct {
		Name        string `json:"name" binding:"required"`
		Description string `json:"description"`
		IsPrivate   bool   `json:"is_private"`
		MaxMembers  int    `json:"max_members"`
	}

	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	group := &models.Group{
		Name:        req.Name,
		Description: req.Description,
		OwnerID:     userID,
		IsPrivate:   req.IsPrivate,
		MaxMembers:  req.MaxMembers,
		CreatedAt:   time.Now(),
	}

	if err := h.groupService.CreateGroup(group); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to create group"})
		return
	}

	// 添加创建者为群主
	member := &models.GroupMember{
		GroupID:  group.ID,
		UserID:   userID,
		Role:     models.GroupRoleOwner,
		IsAdmin:  true,
		JoinedAt: time.Now(),
	}

	if err := h.groupService.AddGroupMember(member); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to add group member"})
		return
	}

	c.JSON(http.StatusCreated, gin.H{"group": group})
}

func (h *GroupHandler) GetGroups(c *gin.Context) {
	userID := c.MustGet("user_id").(string)

	groups, err := h.groupService.GetUserGroups(userID)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to get groups"})
		return
	}

	c.JSON(http.StatusOK, gin.H{"groups": groups})
}

func (h *GroupHandler) GetGroupInfo(c *gin.Context) {
	userID := c.MustGet("user_id").(string)
	groupID := c.Param("group_id")

	// 检查用户是否在群组中
	isMember, err := h.groupService.IsGroupMember(userID, groupID)
	if err != nil || !isMember {
		c.JSON(http.StatusForbidden, gin.H{"error": "Not a member of this group"})
		return
	}

	group, err := h.groupService.GetGroupByID(groupID)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "Group not found"})
		return
	}

	c.JSON(http.StatusOK, gin.H{"group": group})
}

func (h *GroupHandler) AddGroupMember(c *gin.Context) {
	userID := c.MustGet("user_id").(string)
	groupID := c.Param("group_id")

	var req struct {
		UserID string `json:"user_id" binding:"required"`
		Role   string `json:"role"`
	}

	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	// 检查用户是否有权限添加成员
	isAdmin, err := h.groupService.IsGroupAdmin(userID, groupID)
	if err != nil || !isAdmin {
		c.JSON(http.StatusForbidden, gin.H{"error": "Not authorized to add members"})
		return
	}

	member := &models.GroupMember{
		GroupID:  groupID,
		UserID:   req.UserID,
		Role:     req.Role,
		JoinedAt: time.Now(),
	}

	if err := h.groupService.AddGroupMember(member); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to add group member"})
		return
	}

	// 通知群组成员
	h.hub.Submit(websocket.Message{
		Type:    "group_member_added",
		Content: map[string]interface{}{
			"group_id": groupID,
			"user_id":  req.UserID,
			"role":     req.Role,
		},
		From:    userID,
		GroupID: groupID,
	})

	c.JSON(http.StatusOK, gin.H{"message": "Member added successfully"})
}

func (h *GroupHandler) RemoveGroupMember(c *gin.Context) {
	userID := c.MustGet("user_id").(string)
	groupID := c.Param("group_id")
	targetUserID := c.Param("user_id")

	// 检查权限
	isAdmin, err := h.groupService.IsGroupAdmin(userID, groupID)
	if err != nil || (!isAdmin && userID != targetUserID) {
		c.JSON(http.StatusForbidden, gin.H{"error": "Not authorized to remove this member"})
		return
	}

	if err := h.groupService.RemoveGroupMember(groupID, targetUserID); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to remove group member"})
		return
	}

	// 通知群组成员
	h.hub.Submit(websocket.Message{
		Type:    "group_member_removed",
		Content: map[string]interface{}{
			"group_id": groupID,
			"user_id":  targetUserID,
		},
		From:    userID,
		GroupID: groupID,
	})

	c.JSON(http.StatusOK, gin.H{"message": "Member removed successfully"})
}

func (h *GroupHandler) LeaveGroup(c *gin.Context) {
	userID := c.MustGet("user_id").(string)
	groupID := c.Param("group_id")

	// 检查用户是否在群组中
	isMember, err := h.groupService.IsGroupMember(userID, groupID)
	if err != nil || !isMember {
		c.JSON(http.StatusForbidden, gin.H{"error": "Not a member of this group"})
		return
	}

	// 群主不能直接离开群组
	group, err := h.groupService.GetGroupByID(groupID)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "Group not found"})
		return
	}

	if group.OwnerID == userID {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Group owner cannot leave group directly"})
		return
	}

	if err := h.groupService.RemoveGroupMember(groupID, userID); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to leave group"})
		return
	}

	// 通知群组成员
	h.hub.Submit(websocket.Message{
		Type:    "group_member_left",
		Content: map[string]interface{}{
			"group_id": groupID,
			"user_id":  userID,
		},
		From:    userID,
		GroupID: groupID,
	})

	c.JSON(http.StatusOK, gin.H{"message": "Left group successfully"})
}

// routes/websocket.go
package routes

import (
	"net/http"

	"github.com/gin-gonic/gin"
	"github.com/your-username/chat-app/websocket"
)

// AuthService 只抽象路由所需的验签能力（由 JWT 中间件同源的实现提供）
type AuthService interface {
	ValidateToken(tokenString string) (userID string, err error)
}

func SetupWebSocketRoutes(r *gin.Engine, hub *websocket.Hub, authService AuthService) {
	// WebSocket连接端点
	r.GET("/ws", func(c *gin.Context) {
		// 从查询参数中获取token
		token := c.Query("token")
		if token == "" {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "Token is required"})
			return
		}

		// 验证token
		userID, err := authService.ValidateToken(token)
		if err != nil {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "Invalid token"})
			return
		}

		// 升级HTTP连接为WebSocket连接：
		// gorilla/websocket 没有包级 Upgrade 函数，
		// 必须使用 websocket.Upgrader.Upgrade(w, r, nil)
		conn, err := websocket.Upgrader.Upgrade(c.Writer, c.Request, nil)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to upgrade connection"})
			return
		}

		// 注册客户端并启动读写goroutine
		hub.ServeClient(conn, userID)
	})

	// 获取在线用户列表
	r.GET("/ws/online-users", func(c *gin.Context) {
		onlineUsers := hub.OnlineUsers()
		c.JSON(http.StatusOK, gin.H{"online_users": onlineUsers})
	})
}

// middleware/auth.go
package middleware

import (
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/golang-jwt/jwt/v5"
)

func AuthMiddleware(jwtSecret string) gin.HandlerFunc {
	return func(c *gin.Context) {
		authHeader := c.GetHeader("Authorization")
		if authHeader == "" {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "Authorization header is required"})
			c.Abort()
			return
		}

		// 解析Bearer token
		tokenString := strings.TrimPrefix(authHeader, "Bearer ")
		if tokenString == authHeader {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "Bearer token is required"})
			c.Abort()
			return
		}

		// 验证token
		token, err := jwt.Parse(tokenString, func(token *jwt.Token) (interface{}, error) {
			return []byte(jwtSecret), nil
		})

		if err != nil {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "Invalid token"})
			c.Abort()
			return
		}

		if !token.Valid {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "Invalid token"})
			c.Abort()
			return
		}

		// 获取claims
		claims, ok := token.Claims.(jwt.MapClaims)
		if !ok {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "Invalid token claims"})
			c.Abort()
			return
		}

		// 设置用户ID到上下文
		userID, ok := claims["user_id"].(string)
		if !ok {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "Invalid user ID in token"})
			c.Abort()
			return
		}

		c.Set("user_id", userID)
		c.Next()
	}
}

func CORSMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		origin := c.GetHeader("Origin")

		// Access-Control-Allow-Origin: * 与 Allow-Credentials: true 是非法组合，
		// 浏览器会直接拒绝响应；携带凭据时必须回显具体 Origin
		if origin != "" {
			c.Header("Access-Control-Allow-Origin", origin)
			c.Header("Vary", "Origin") // 防止 CDN/代理缓存了错误的 CORS 头
		}
		c.Header("Access-Control-Allow-Credentials", "true")
		c.Header("Access-Control-Allow-Headers", "Content-Type, Content-Length, Accept-Encoding, X-CSRF-Token, Authorization, accept, origin, Cache-Control, X-Requested-With")
		c.Header("Access-Control-Allow-Methods", "POST, OPTIONS, GET, PUT, DELETE")

		if c.Request.Method == "OPTIONS" {
			c.AbortWithStatus(204)
			return
		}

		c.Next()
	}
}

