		prometheus.HistogramOpts{
			Name:    "chat_http_request_duration_seconds",
			Help:    "Duration of HTTP requests",
			Buckets: prometheus.DefBuckets,
		},
		[]string{"method", "endpoint"},
	)

	// WebSocket连接指标
	websocketConnections = promauto.NewGauge(
		prometheus.GaugeOpts{
			Name: "chat_websocket_connections_total",
			Help: "Total number of active WebSocket connections",
		},
	)

	websocketMessagesTotal = promauto.NewCounterVec(
		prometheus.CounterOpts{
			Name: "chat_websocket_messages_total",
			Help: "Total number of WebSocket messages",
		},
		[]string{"type"},
	)

	// 业务指标
	usersTotal = promauto.NewGauge(
		prometheus.GaugeOpts{
			Name: "chat_users_total",
			Help: "Total number of users",
		},
	)

	messagesTotal = promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "chat_messages_total",
			Help: "Total number of messages sent",
		},
	)

	groupsTotal = promauto.NewGauge(
		prometheus.GaugeOpts{
			Name: "chat_groups_total",
			Help: "Total number of groups",
		},
	)
)

func RecordHTTPRequest(method, endpoint string, status int, duration time.Duration) {
	httpRequestsTotal.WithLabelValues(method, endpoint, strconv.Itoa(status)).Inc()
	httpRequestDuration.WithLabelValues(method, endpoint).Observe(duration.Seconds())
}

func RecordWebSocketConnection(connect bool) {
	if connect {
		websocketConnections.Inc()
	} else {
		websocketConnections.Dec()
	}
}

func RecordWebSocketMessage(messageType string) {
	websocketMessagesTotal.WithLabelValues(messageType).Inc()
}

func UpdateUsersCount(count int) {
	usersTotal.Set(float64(count))
}

func RecordMessage() {
	messagesTotal.Inc()
}

func UpdateGroupsCount(count int) {
	groupsTotal.Set(float64(count))
}

// logging/logger.go
package logging

import (
	"log/slog"
	"os"
	"time"

	"github.com/lmittmann/tint"
)

type Logger struct {
	*slog.Logger
}

type LogFields map[string]interface{}

func NewLogger(serviceName string) *Logger {
	handler := tint.NewHandler(os.Stdout, &tint.Options{
		Level:      slog.LevelDebug,
		TimeFormat: time.RFC3339,
		AddSource:  true,
	})

	logger := slog.New(handler)
	logger = logger.With("service", serviceName)

	return &Logger{Logger: logger}
}

func (l *Logger) WithFields(fields LogFields) *Logger {
	var args []interface{}
	for key, value := range fields {
		args = append(args, key, value)
	}
	return &Logger{Logger: l.Logger.With(args...)}
}

func (l *Logger) Info(msg string, fields LogFields) {
	if len(fields) > 0 {
		l.Logger.Info(msg, l.slogFields(fields)...)
	} else {
		l.Logger.Info(msg)
	}
}

func (l *Logger) Error(msg string, fields LogFields) {
	if len(fields) > 0 {
		l.Logger.Error(msg, l.slogFields(fields)...)
	} else {
		l.Logger.Error(msg)
	}
}

func (l *Logger) Debug(msg string, fields LogFields) {
	if len(fields) > 0 {
		l.Logger.Debug(msg, l.slogFields(fields)...)
	} else {
		l.Logger.Debug(msg)
	}
}

func (l *Logger) slogFields(fields LogFields) []interface{} {
	var args []interface{}
	for key, value := range fields {
		args = append(args, key, value)
	}
	return args
}

// handlers/upload.go
package handlers

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/your-username/chat-app/websocket"
)

func (h *MessageHandler) UploadFile(c *gin.Context) {
	userID := c.MustGet("user_id").(string)
	receiverID := c.Param("receiver_id")

	file, header, err := c.Request.FormFile("file")
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Failed to get file"})
		return
	}
	defer file.Close()

	// 生成文件名
	ext := filepath.Ext(header.Filename)
	filename := fmt.Sprintf("%d_%s%s", time.Now().Unix(), userID, ext)

	// 创建上传目录
	uploadDir := "uploads"
	if err := os.MkdirAll(uploadDir, 0755); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to create upload directory"})
		return
	}

	// 保存文件
	filePath := filepath.Join(uploadDir, filename)
	out, err := os.Create(filePath)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to create file"})
		return
	}
	defer out.Close()

	if _, err := io.Copy(out, file); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to save file"})
		return
	}

	// 生成文件URL
	fileURL := fmt.Sprintf("/uploads/%s", filename)

	// 发送文件消息
	message := websocket.Message{
		Type:    "private",
		Content: map[string]interface{}{
			"type":     "file",
			"filename": header.Filename,
			"size":     header.Size,
			"url":      fileURL,
		},
		From: userID,
		To:   receiverID,
	}

	h.hub.Submit(message)

	c.JSON(http.StatusOK, gin.H{
		"message":   "File uploaded successfully",
		"file_url":  fileURL,
		"file_name": header.Filename,
	})
}

// crypto/encryption.go
package crypto

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"io"
)

type Encryption struct {
	key []byte
}

func NewEncryption(key string) *Encryption {
	return &Encryption{
		key: []byte(key),
	}
}

func (e *Encryption) Encrypt(plaintext string) (string, error) {
	block, err := aes.NewCipher(e.key)
	if err != nil {
		return "", err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", err
	}

	nonce := make([]byte, gcm.NonceSize())
	if _, err = io.ReadFull(rand.Reader, nonce); err != nil {
		return "", err
	}

	ciphertext := gcm.Seal(nonce, nonce, []byte(plaintext), nil)
	return base64.URLEncoding.EncodeToString(ciphertext), nil
}

func (e *Encryption) Decrypt(encrypted string) (string, error) {
	data, err := base64.URLEncoding.DecodeString(encrypted)
	if err != nil {
		return "", err
	}

	block, err := aes.NewCipher(e.key)
	if err != nil {
		return "", err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", err
	}

	nonceSize := gcm.NonceSize()
	if len(data) < nonceSize {
		return "", fmt.Errorf("ciphertext too short")
	}

	// 密文参数已占用 ciphertext 名，这里改用 encrypted/encryptedData
	nonce, encryptedData := data[:nonceSize], data[nonceSize:]
	plaintext, err := gcm.Open(nil, nonce, encryptedData, nil)
	if err != nil {
		return "", err
	}

	return string(plaintext), nil
}

// notifications/push.go
// 修复说明：原片段使用的 appleboy/go-fcm 旧代码（fcm.NewClient(serverKey)、
// response.Failure）基于 FCM legacy HTTP API——该 API 已于 2024-06 关停；
// appleboy/go-fcm 自 v1.2.x 起也已改为封装官方 Firebase Admin SDK。
// 生产代码应直接使用 firebase.google.com/go/v4（FCM v1 API）+ 服务账号凭据。
package notifications

import (
	"context"
	"fmt"
	"log"

	firebase "firebase.google.com/go/v4"
	"firebase.google.com/go/v4/messaging"
	"google.golang.org/api/option"
)

type PushNotificationService struct {
	client *messaging.Client
}

// NewPushNotificationService 传入 FCM v1 服务账号 JSON 的路径
func NewPushNotificationService(ctx context.Context, credentialsFile string) (*PushNotificationService, error) {
	app, err := firebase.NewApp(ctx, nil, option.WithCredentialsFile(credentialsFile))
	if err != nil {
		return nil, fmt.Errorf("初始化 Firebase App 失败: %w", err)
	}

	client, err := app.Messaging(ctx)
	if err != nil {
		return nil, fmt.Errorf("获取 Messaging 客户端失败: %w", err)
	}

	return &PushNotificationService{client: client}, nil
}

func (s *PushNotificationService) SendPushNotification(ctx context.Context, token, title, body string, data map[string]string) error {
	message := &messaging.Message{
		Token: token,
		Notification: &messaging.Notification{
			Title: title,
			Body:  body,
		},
		Data: data,
	}

	// FCM v1 API 单次发送返回消息 ID；legacy API 的 response.Failure 计数不再存在
	resp, err := s.client.Send(ctx, message)
	if err != nil {
		return err
	}

	log.Printf("推送发送成功: %s", resp)
	return nil
}

// SendMulticast 批量发送（最多 500 tokens/次）
func (s *PushNotificationService) SendMulticast(ctx context.Context, tokens []string, title, body string) error {
	resp, err := s.client.SendEachForMulticast(ctx, &messaging.MulticastMessage{
		Tokens: tokens,
		Notification: &messaging.Notification{
			Title: title,
			Body:  body,
		},
	})
	if err != nil {
		return err
	}
	if resp.FailureCount > 0 {
		return fmt.Errorf("发送失败 %d/%d 条", resp.FailureCount, len(tokens))
	}
	return nil
}

