import (
    "fmt"
    "sync"
    "sync/atomic"
    "time"
)

func main() {
    // 互斥锁示例
    mutexExample()

    // 读写锁示例
    rwMutexExample()

    // 等待组示例
    waitGroupExample()

    // 原子操作示例
    atomicExample()

    // 条件变量示例
    condExample()

    // 单次执行示例
    onceExample()

    // 池示例
    poolExample()
}

func mutexExample() {
    fmt.Println("\n=== 互斥锁示例 ===")

    var counter int
    var mutex sync.Mutex

    var wg sync.WaitGroup
    wg.Add(100)

    for i := 0; i < 100; i++ {
        go func() {
            defer wg.Done()

            mutex.Lock()
            counter++
            mutex.Unlock()
        }()
    }

    wg.Wait()
    fmt.Printf("最终计数器值: %d\n", counter)
}

func rwMutexExample() {
    fmt.Println("\n=== 读写锁示例 ===")

    var data map[string]string = make(map[string]string)
    var rwMutex sync.RWMutex

    var wg sync.WaitGroup

    // 写入者
    wg.Add(1)
    go func() {
        defer wg.Done()

        for i := 0; i < 5; i++ {
            rwMutex.Lock()
            data[fmt.Sprintf("key%d", i)] = fmt.Sprintf("value%d", i)
            rwMutex.Unlock()
            time.Sleep(100 * time.Millisecond)
        }
    }()

    // 读取者
    for i := 0; i < 10; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()

            rwMutex.RLock()
            fmt.Printf("读取者 %d 读取数据: %v\n", id, data)
            rwMutex.RUnlock()
        }(i)
    }

    wg.Wait()
}

func waitGroupExample() {
    fmt.Println("\n=== 等待组示例 ===")

    var wg sync.WaitGroup

    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()

            fmt.Printf("协程 %d 开始工作\n", id)
            time.Sleep(time.Duration(id) * 100 * time.Millisecond)
            fmt.Printf("协程 %d 完成工作\n", id)
        }(i)
    }

    fmt.Println("等待所有协程完成...")
    wg.Wait()
    fmt.Println("所有协程已完成")
}

func atomicExample() {
    fmt.Println("\n=== 原子操作示例 ===")

    var counter int64

    var wg sync.WaitGroup
    wg.Add(1000)

    for i := 0; i < 1000; i++ {
        go func() {
            defer wg.Done()
            atomic.AddInt64(&counter, 1)
        }()
    }

    wg.Wait()
    fmt.Printf("原子计数器值: %d\n", counter)

    // 比较并交换
    var value int64 = 100
    swapped := atomic.CompareAndSwapInt64(&value, 100, 200)
    fmt.Printf("交换成功: %t, 新值: %d\n", swapped, value)

    // 加载和存储
    atomic.StoreInt64(&value, 300)
    loaded := atomic.LoadInt64(&value)
    fmt.Printf("存储和加载值: %d\n", loaded)
}

func condExample() {
    fmt.Println("\n=== 条件变量示例 ===")

    var mutex sync.Mutex
    cond := sync.NewCond(&mutex)

    var ready bool

    // 等待者
    go func() {
        mutex.Lock()
        for !ready {
            cond.Wait()
        }
        fmt.Println("条件满足，继续执行")
        mutex.Unlock()
    }()

    // 通知者
    time.Sleep(1 * time.Second)
    mutex.Lock()
    ready = true
    cond.Signal()
    mutex.Unlock()

    time.Sleep(100 * time.Millisecond)
}

func onceExample() {
    fmt.Println("\n=== 单次执行示例 ===")

    var once sync.Once
    var counter int

    increment := func() {
        counter++
        fmt.Printf("函数执行，计数器: %d\n", counter)
    }

    for i := 0; i < 5; i++ {
        go once.Do(increment)
    }

    time.Sleep(100 * time.Millisecond)
    fmt.Printf("最终计数器: %d\n", counter)
}

func poolExample() {
    fmt.Println("\n=== 池示例 ===")

    var pool = sync.Pool{
        New: func() interface{} {
            return make([]byte, 1024)
        },
    }

    // 获取对象
    buf := pool.Get().([]byte)
    fmt.Printf("获取缓冲区，容量: %d\n", cap(buf))

    // 使用对象
    buf = append(buf, []byte("Hello, Pool!")...)

    // 放回对象
    pool.Put(buf)

    // 再次获取
    buf2 := pool.Get().([]byte)
    fmt.Printf("再次获取缓冲区，内容: %s\n", string(buf2))

    // 清理并放回
    buf2 = buf2[:0]
    pool.Put(buf2)
}

