)

// 待测试的函数
func Add(a, b int) int {
    return a + b
}

func Multiply(a, b int) int {
    return a * b
}

// 单元测试
func TestAdd(t *testing.T) {
    tests := []struct {
        name     string
        a, b     int
        expected int
    }{
        {"正数相加", 2, 3, 5},
        {"负数相加", -1, -1, -2},
        {"零相加", 0, 0, 0},
        {"正负相加", 5, -3, 2},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            result := Add(tt.a, tt.b)
            if result != tt.expected {
                t.Errorf("Add(%d, %d) = %d; 期望 %d", tt.a, tt.b, result, tt.expected)
            }
        })
    }
}

// 基准测试
func BenchmarkAdd(b *testing.B) {
    for i := 0; i < b.N; i++ {
        Add(i, i+1)
    }
}

func BenchmarkMultiply(b *testing.B) {
    for i := 0; i < b.N; i++ {
        Multiply(i, i+1)
    }
}

// 示例测试
func ExampleAdd() {
    result := Add(2, 3)
    fmt.Println(result)
    // Output: 5
}

// 并发测试
func TestConcurrentAdd(t *testing.T) {
    const goroutines = 100
    done := make(chan bool, goroutines)

    for i := 0; i < goroutines; i++ {
        go func() {
            defer func() { done <- true }()

            result := Add(i, i+1)
            expected := 2*i + 1
            if result != expected {
                t.Errorf("Add(%d, %d) = %d; 期望 %d", i, i+1, result, expected)
            }
        }()
    }

    for i := 0; i < goroutines; i++ {
        <-done
    }
}

package main

import (
    "fmt"
    "sort"
)

type Person struct {
    Name string
    Age  int
}

type ByAge []Person
type ByName []Person

func (a ByAge) Len() int           { return len(a) }
func (a ByAge) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a ByAge) Less(i, j int) bool { return a[i].Age < a[j].Age }

func (a ByName) Len() int           { return len(a) }
func (a ByName) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a ByName) Less(i, j int) bool { return a[i].Name < a[j].Name }

func main() {
    // 基本类型排序
    numbers := []int{5, 2, 8, 1, 9, 3}
    sort.Ints(numbers)
    fmt.Println("排序后的整数:", numbers)

    strings := []string{"banana", "apple", "orange", "grape"}
    sort.Strings(strings)
    fmt.Println("排序后的字符串:", strings)

    // 逆序排序
    sort.Sort(sort.Reverse(sort.IntSlice(numbers)))
    fmt.Println("逆序排序:", numbers)

    // 重新正序排序
    sort.Ints(numbers)

    // 搜索
    index := sort.SearchInts(numbers, 8)
    fmt.Println("搜索8的位置:", index)

    // 检查是否已排序
    isSorted := sort.IntsAreSorted(numbers)
    fmt.Println("是否已排序:", isSorted)

    // 自定义类型排序
    people := []Person{
        {"Alice", 25},
        {"Bob", 30},
        {"Charlie", 20},
    }

    // 按年龄排序
    sort.Sort(ByAge(people))
    fmt.Println("按年龄排序:", people)

    // 按姓名排序
    sort.Sort(ByName(people))
    fmt.Println("按姓名排序:", people)

    // 使用sort.Slice
    sort.Slice(people, func(i, j int) bool {
        return people[i].Age < people[j].Age
    })
    fmt.Println("使用sort.Slice按年龄排序:", people)

    // 稳定排序
    data := []struct {
        Name string
        Rank int
    }{
        {"Alice", 2},
        {"Bob", 1},
        {"Charlie", 2},
        {"David", 1},
    }

    // 先按rank排序
    sort.Slice(data, func(i, j int) bool {
        return data[i].Rank < data[j].Rank
    })
    fmt.Println("按rank排序:", data)

    // 稳定排序保持相同rank的原始顺序
    sort.SliceStable(data, func(i, j int) bool {
        return data[i].Rank < data[j].Rank
    })
    fmt.Println("稳定排序:", data)
}

package main

import (
    "fmt"
    "slices"
)

func main() {
    nums := []int{5, 2, 8, 1, 9, 3}

    slices.Sort(nums) // 替代 sort.Ints（泛型，任意 ordered 类型）
    fmt.Println("Sort:", nums) // [1 2 3 5 8 9]

    fmt.Println(slices.IsSorted(nums)) // true，替代 sort.IntsAreSorted

    // 二分查找（要求已排序），替代 sort.SearchInts
    i, ok := slices.BinarySearch(nums, 8)
    fmt.Println(i, ok) // 4 true

    // 此前需手写循环的操作
    fmt.Println(slices.Contains(nums, 9), slices.Index(nums, 9)) // true 5
    fmt.Println(slices.Max(nums), slices.Min(nums))              // 9 1

    // 切片不能用 == 比较，slices.Equal 可以
    a, b := []int{1, 2, 3}, []int{1, 2, 3}
    fmt.Println(slices.Equal(a, b)) // true

    // 插入/删除（替代 copy + append 拼接）
    s := []string{"a", "b", "c"}
    s = slices.Insert(s, 1, "x") // 在索引 1 处插入
    fmt.Println(s)               // [a x b c]
    s = slices.Delete(s, 1, 2)   // 删除 [1,2) 区间
    fmt.Println(s)               // [a b c]
    s = slices.DeleteFunc(s, func(v string) bool { return v == "c" })
    fmt.Println(s) // [a b]

    slices.Reverse(s)
    clone := slices.Clone(s) // 独立副本，避免共享底层数组
    fmt.Println(s, clone)    // [b a] [b a]
}

package main

import (
    "fmt"
    "maps"
    "slices"
)

func main() {
    ages := map[string]int{"alice": 30, "bob": 25, "carol": 35}

    // 键列表排序输出（map 遍历顺序随机，需要有序时先排序）
    keys := slices.Sorted(maps.Keys(ages)) // maps.Keys 返回迭代器
    fmt.Println(keys) // [alice bob carol]

    // 克隆：浅拷贝，值类型为引用类型时注意共享
    m2 := maps.Clone(ages)
    m2["dave"] = 40
    fmt.Println(ages, m2) // dave 只存在于 m2

    // 相等比较（键值对完全一致）
    fmt.Println(maps.Equal(ages, map[string]int{"alice": 30, "bob": 25, "carol": 35})) // true

    // 按条件删除
    maps.DeleteFunc(m2, func(k string, v int) bool { return v > 30 })
    fmt.Println(m2) // carol(35) 被删除
}

