)

type User struct {
    Name    string   `json:"name"`
    Age     int      `json:"age"`
    Email   string   `json:"email,omitempty"`
    Hobbies []string `json:"hobbies"`
}

var cfg = jsoniter.ConfigCompatibleWithStandardLibrary

func main() {
    // 编码
    user := User{
        Name:    "Alice",
