package main

import (
    "bytes"
    "fmt"

    "github.com/google/uuid"
)

func main() {
    // 生成UUID v4
    id := uuid.New()
    fmt.Printf("UUID v4: %s\n", id.String())

    // 解析UUID
    parsed, err := uuid.Parse("123e4567-e89b-12d3-a456-426614174000")
    if err != nil {
        panic(err)
    }
    fmt.Printf("解析的UUID: %s\n", parsed.String())

    // 生成UUID v1
    v1, err := uuid.NewUUID()
    if err != nil {
        panic(err)
    }
    fmt.Printf("UUID v1: %s\n", v1.String())

    // 生成UUID v3 (基于MD5哈希)
    namespace := uuid.MustParse("6ba7b810-9dad-11d1-80b4-00c04fd430c8")
    v3 := uuid.NewMD5(namespace, []byte("example.com"))
    fmt.Printf("UUID v3: %s\n", v3.String())

    // 生成UUID v5 (基于SHA-1哈希)
    v5 := uuid.NewSHA1(namespace, []byte("example.com"))
    fmt.Printf("UUID v5: %s\n", v5.String())

    // 检查UUID版本
    fmt.Printf("UUID版本: %d\n", id.Version())

    // 检查UUID变体
    fmt.Printf("UUID变体: %d\n", id.Variant())

    // 零值UUID
    nilUUID := uuid.Nil
    fmt.Printf("零值UUID: %s\n", nilUUID.String())

    // UUID比较
    id1 := uuid.New()
    id2 := uuid.New()
    fmt.Printf("UUID相等: %t\n", id1 == id2)
    // UUID 类型没有 Compare 方法，按字节序比较
    fmt.Printf("UUID比较: %d\n", bytes.Compare(id1[:], id2[:]))

    // 从字符串创建UUID
    fromString, err := uuid.Parse("123e4567-e89b-12d3-a456-426614174000")
    if err != nil {
        panic(err)
    }
    fmt.Printf("从字符串创建: %s\n", fromString.String())

    // 从字节数组创建UUID
    var rawBytes [16]byte
    copy(rawBytes[:], []byte("1234567890123456"))
    fromBytes, err := uuid.FromBytes(rawBytes[:])
    if err != nil {
        panic(err)
    }
    fmt.Printf("从字节数组创建: %s\n", fromBytes.String())
}

package main

import (
    "fmt"

    "golang.org/x/crypto/bcrypt"
)

// 密码哈希函数（包级函数）
func hashPassword(password string) (string, error) {
    bytes, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
    return string(bytes), err
}

func checkPasswordHash(password, hash string) bool {
    err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(password))
    return err == nil
}

func main() {
    password := "mySecurePassword123"

    // 生成哈希
    hashedPassword, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
    if err != nil {
        panic(err)
    }

    fmt.Printf("哈希密码: %s\n", hashedPassword)

    // 验证密码
    err = bcrypt.CompareHashAndPassword(hashedPassword, []byte(password))
    if err == nil {
        fmt.Println("密码验证成功")
    }

    // 验证错误密码
    err = bcrypt.CompareHashAndPassword(hashedPassword, []byte("wrongPassword"))
    if err != nil {
        fmt.Println("密码验证失败:", err)
    }

    // 使用不同的cost
    hashedPasswordHighCost, err := bcrypt.GenerateFromPassword([]byte(password), 12)
    if err != nil {
        panic(err)
    }

    fmt.Printf("高cost哈希: %s\n", hashedPasswordHighCost)

    // 验证高cost哈希
    err = bcrypt.CompareHashAndPassword(hashedPasswordHighCost, []byte(password))
    if err == nil {
        fmt.Println("高cost密码验证成功")
    }

    // 检查哈希是否有效
    cost, err := bcrypt.Cost(hashedPassword)
    if err != nil {
        panic(err)
    }
    fmt.Printf("哈希cost: %d\n", cost)

    // 使用函数（定义在包级）
    hash, err := hashPassword("anotherPassword")
    if err != nil {
        panic(err)
    }

    isValid := checkPasswordHash("anotherPassword", hash)
    fmt.Printf("密码验证: %t\n", isValid)
}

package main

import (
    "encoding/json"
    "fmt"
    "net/http"
)

type User struct {
    Name  string `json:"name"`
    Email string `json:"email"`
}

func userHandler(w http.ResponseWriter, r *http.Request) {
    id := r.PathValue("id") // 捕获 {id} 通配符

    user := User{Name: "用户" + id, Email: "user" + id + "@example.com"}
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(user) // 结构体直接序列化为 JSON
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
    fmt.Fprintln(w, "ok") // Fprintln 直接写响应体
}

func newMux() *http.ServeMux {
    mux := http.NewServeMux()
    // "METHOD /path/{wildcard}" 模式语法
    mux.HandleFunc("GET /users/{id}", userHandler) // 方法不匹配自动返回 405
    mux.HandleFunc("GET /health", healthHandler)
    return mux
}

func main() {
    if err := http.ListenAndServe(":8080", newMux()); err != nil {
        panic(err)
    }
}

func logging(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()
        next.ServeHTTP(w, r) // 调用链中的下一个 Handler
        log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))
    })
}

func recoverPanic(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        defer func() {
            if err := recover(); err != nil {
                http.Error(w, "internal error", http.StatusInternalServerError)
            }
        }()
        next.ServeHTTP(w, r)
    })
}

// 链式包裹：请求依次经过 recover → logging → 业务 Handler
mux := recoverPanic(logging(newMux()))

func fetchUser(baseURL, id string) (*User, error) {
    // 3 秒超时，超时或取消时请求中断
    ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
    defer cancel()

    req, err := http.NewRequestWithContext(ctx, http.MethodGet,
        baseURL+"/users/"+id, nil)
    if err != nil {
        return nil, fmt.Errorf("构造请求: %w", err)
    }
    req.Header.Set("Accept", "application/json")

    resp, err := http.DefaultClient.Do(req)
    if err != nil {
        return nil, fmt.Errorf("请求失败: %w", err)
    }
    defer resp.Body.Close() // 必须！否则连接无法复用直至泄漏

    if resp.StatusCode != http.StatusOK {
        return nil, fmt.Errorf("意外状态码: %d %s", resp.StatusCode, resp.Status)
    }

    body, err := io.ReadAll(resp.Body)
    if err != nil {
        return nil, fmt.Errorf("读取响应体: %w", err)
    }

    var u User
    if err := json.Unmarshal(body, &u); err != nil {
        return nil, fmt.Errorf("解析 JSON: %w", err)
    }
    return &u, nil
}

