	b, _ := json.Marshal(u)
	fmt.Println(string(b))
	// {"name":"alice","age":"18"}（email/profile 省略，password/Internal 不出现）

	// 解码：大小写不敏感匹配
	var v User
	json.Unmarshal([]byte(`{"NAME":"bob","AGE":"20"}`), &v)
	fmt.Println(v.Name, v.Age) // bob 20

	// UseNumber：保留大整数精度
	dec := json.NewDecoder(strings.NewReader(`{"id":12345678901234567890}`))
	dec.UseNumber()
	var m map[string]any
	dec.Decode(&m)
	fmt.Println(m["id"], fmt.Sprintf("%T", m["id"])) // 12345678901234567890 json.Number
}

type Duration struct{ Seconds int }

func (d Duration) MarshalJSON() ([]byte, error) {
	return []byte(fmt.Sprintf(`"%ds"`, d.Seconds)), nil // 输出 "30s"
}

func (d *Duration) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	var n int
	if _, err := fmt.Sscanf(s, "%ds", &n); err != nil {
		return err
	}
	d.Seconds = n
	return nil
}

// Context 接口四个方法
type Context interface {
    Deadline() (deadline time.Time, ok bool)
    Done() <-chan struct{}   // 取消时关闭的信号 channel
    Err() error              // 取消原因：Canceled / DeadlineExceeded
    Value(key any) any       // 请求级数据
}

// 树的构造（每个返回值都带 cancel，调用方负责调用）
ctx, cancel := context.WithCancel(parent)                    // 手动取消
ctx, cancel := context.WithTimeout(parent, 5*time.Second)    // 相对截止
ctx, cancel := context.WithDeadline(parent, someTime)        // 绝对截止
ctx2 := context.WithValue(parent, key, val)                  // 携带数据

// 消费端统一模式：select 监听 Done
select {
case <-ctx.Done():
    return ctx.Err() // context.Canceled 或 context.DeadlineExceeded
case v := <-ch:
    return v
}

package main

import (
	"context"
	"fmt"
	"time"
)

type userIDKey struct{} // 私有 key 类型，防跨包键冲突

func slowWork(ctx context.Context) error {
	select {
	case <-time.After(3 * time.Second): // 模拟慢操作
		return nil
	case <-ctx.Done():
		return ctx.Err() // 让出：把取消原因向上传
	}
}

func main() {
	// 1. WithTimeout：超时自动取消
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()
	if err := slowWork(ctx); err != nil {
		fmt.Println(err) // context deadline exceeded
	}

	// 2. 手动取消：所有派生 ctx 同时收到信号
	root, rootCancel := context.WithCancel(context.Background())
	defer rootCancel()
	childA, _ := context.WithCancel(root)
	childB, _ := context.WithCancel(root)
	go func() {
		time.Sleep(10 * time.Millisecond)
		rootCancel()
	}()
	<-childA.Done()
	<-childB.Done() // 父取消 → 子树全部完成
	fmt.Println("两个子 ctx 都已取消")

	// 3. WithValue：请求级数据沿树传递
	rctx := context.WithValue(context.Background(), userIDKey{}, 42)
	fmt.Println(rctx.Value(userIDKey{})) // 42
}

