type error interface { Error() string }

// 三种构造
errors.New("boom")                      // 匿名错误（动态消息，不宜做 sentinel 比较）
fmt.Errorf("read %s: %w", path, err)    // %w 包装：保留原错误形成链
myErr{...}                              // 自定义类型（可携带结构化字段）

// 三个判读工具（1.13+）
