package main

import (
	"context"
	"fmt"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

type User struct {
	ID    bson.ObjectID `bson:"_id,omitempty"`
	Name  string        `bson:"name"`
	Email string        `bson:"email"`
	Age   int           `bson:"age"`
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	client, err := mongo.Connect(options.Client().ApplyURI("mongodb://localhost:27017"))
	if err != nil {
		panic(err)
	}
	defer client.Disconnect(context.Background())

	if err := client.Ping(ctx, nil); err != nil { // 确认连通性
		panic(err)
	}

	col := client.Database("app").Collection("users")

	// 插入
	res, err := col.InsertOne(ctx, User{Name: "Ada", Email: "ada@example.com", Age: 30})
	if err != nil {
		panic(err)
	}
	fmt.Println("inserted:", res.InsertedID)

	// 查询多条（带过滤 + 排序）
	cursor, err := col.Find(ctx, bson.M{"age": bson.M{"$gte": 18}},
		options.Find().SetSort(bson.D{{Key: "name", Value: 1}}).SetLimit(10))
	if err != nil {
		panic(err)
	}
	var users []User
	if err := cursor.All(ctx, &users); err != nil {
		panic(err)
	}
	for _, u := range users {
		fmt.Println(u.Name, u.Email)
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/redis/go-redis/v9"
)

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	rdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})
	defer rdb.Close()

	if err := rdb.Ping(ctx).Err(); err != nil { // 确认可达
		panic(err)
	}

	// 字符串：带过期时间的写入
	if err := rdb.Set(ctx, "session:u1", "token-abc", 30*time.Minute).Err(); err != nil {
		panic(err)
	}

	// 读取：区分"键不存在"与真实错误
	token, err := rdb.Get(ctx, "session:u1").Result()
	switch {
	case errors.Is(err, redis.Nil):
		fmt.Println("会话已过期")
	case err != nil:
		panic(err)
	default:
		fmt.Println("token:", token)
	}

	// 管道：一次往返执行多条命令
	var hits *redis.IntCmd
	_, err = rdb.Pipelined(ctx, func(pipe redis.Pipeliner) error {
		hits = pipe.Incr(ctx, "metrics:hits")
		pipe.Expire(ctx, "metrics:hits", time.Hour)
		return nil
	})
	if err != nil {
		panic(err)
	}
	fmt.Println("hits:", hits.Val())
}

