// 返回多个值
func divide(a, b float64) (float64, error) {
    if b == 0 {
        return 0, errors.New("division by zero")
    }
    return a / b, nil
}

// 提前返回
func process(data []int) error {
    if len(data) == 0 {
        return errors.New("empty data")
    }

    // 处理数据
    for _, item := range data {
        if item < 0 {
            return errors.New("negative value found")
        }
    }

    return nil
}

