// defer在错误处理中的应用
func transactionExample() error {
    tx, err := db.Begin()
    if err != nil {
        return err
    }
    defer func() {
        if err != nil {
            tx.Rollback()
        } else {
            tx.Commit()
        }
    }()

    // 执行事务操作
    if err = tx.Exec("INSERT INTO..."); err != nil {
        return err
    }

    return nil
}

