// 关闭通道的select
func example5() {
    ch := make(chan int)
    close(ch)

    select {
    case value, ok := <-ch:
        if ok {
            println("Received:", value)
        } else {
            println("Channel closed")
        }
    default:
        println("No data available")
    }
}

