// range的陷阱和注意事项
func rangePitfallsExample() {
    // 陷阱1: range返回的是副本
    type Person struct {
        Name string
        Age  int
    }

    people := []Person{
        {"Alice", 25},
        {"Bob", 30},
    }

    // 这样修改不会影响原slice
    for _, person := range people {
        person.Age = 100 // 修改的是副本
    }

    // 正确的修改方式
    for i := range people {
        people[i].Age = 100 // 修改原元素
    }

    // 陷阱2: 在循环中使用闭包
    funcs := []func(){}

    for i := 0; i < 3; i++ {
        // 错误: 所有闭包都引用同一个i
        funcs = append(funcs, func() {
            println(i)
        })
    }

    // 正确方式: 创建局部变量
    for i := 0; i < 3; i++ {
        i := i // 创建新的局部变量
        funcs = append(funcs, func() {
            println(i)
        })
    }
}

