// goto用于资源清理
func resourceCleanupExample() {
    file, err := os.Open("file.txt")
    if err != nil {
        goto DONE
    }

    defer func() {
        if file != nil {
            file.Close()
        }
    }()

    // 处理文件
    _, err = file.WriteString("Hello")
    if err != nil {
        goto DONE
    }

    println("File processed successfully")

DONE:
    println("Operation completed")
}

