}

// fallthrough与条件
func fallthroughWithCondition() {
    score := 85

    switch {
    case score >= 90:
        println("A")
    case score >= 80:
        println("B")
        fallthrough
    case score >= 70:
        println("C")
    default:
        println("F")
    }
    // 如果score是85，输出: B, C
}

// fallthrough的限制
func fallthroughLimitations() {
    switch day {
    case "Monday":
        println("Monday")
        fallthrough
    case "Tuesday":
        println("Tuesday")
        // fallthrough不能是最后一个case
        // fallthrough // 编译错误
    }

    // fallthrough可以跳入下一个带条件的case（不评估其条件，直接执行case体）
    switch x := 3; {
    case x > 5:
        println("Greater than 5")
    case x > 0:
        println("Positive")
        fallthrough
    case x > 1:
        println("At least 2")
    }
    // 如果x是3，输出: Positive, At least 2
    // fallthrough唯一的限制：不能出现在switch的最后一个case中
}

