        return nil, &ConflictError{
            Resource: "user",
            Field:    "email",
            Value:    req.Email,
        }
    }

    // 创建用户
    user := &User{
        Name:      req.Name,
        Email:     req.Email,
        CreatedAt: time.Now(),
    }

    if err := s.repo.Create(ctx, user); err != nil {
        return nil, fmt.Errorf("failed to create user in database: %w", err)
    }

    // 发送欢迎邮件
