// ❌ 无限制创建goroutine
func ProcessUsers(users []User) {
    for _, user := range users {
        go func(u User) {
            // 处理用户
            ProcessUser(u)
        }(user)
    }
}

// ✅ 使用worker pool模式
func ProcessUsers(users []User) error {
    const workerCount = 10
    jobs := make(chan User, len(users))
    results := make(chan error, len(users))

    // 启动worker
    var wg sync.WaitGroup
    for i := 0; i < workerCount; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for user := range jobs {
                if err := ProcessUser(user); err != nil {
                    results <- err
                } else {
                    results <- nil
                }
            }
        }()
    }

    // 发送任务
    go func() {
        defer close(jobs)
        for _, user := range users {
            jobs <- user
        }
    }()

    // 等待完成
    go func() {
        wg.Wait()
        close(results)
    }()

    // 收集结果
    var errors []error
    for err := range results {
        if err != nil {
            errors = append(errors, err)
        }
    }

    if len(errors) > 0 {
        return fmt.Errorf("processing completed with %d errors: %v", len(errors), errors)
    }

    return nil
}

type Server struct {
    httpServer *http.Server
    tasks      []func(context.Context) error
}

func NewServer() *Server {
    return &Server{
        tasks: make([]func(context.Context) error, 0),
    }
}

func (s *Server) AddTask(task func(context.Context) error) {
    s.tasks = append(s.tasks, task)
}

func (s *Server) Start() error {
    // 启动HTTP服务器
    go func() {
        if err := s.httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
            log.Printf("HTTP server error: %v", err)
        }
    }()

    // 启动后台任务
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    for _, task := range s.tasks {
        go func(t func(context.Context) error) {
            if err := t(ctx); err != nil {
                log.Printf("Task error: %v", err)
            }
        }(task)
    }

    return nil
}

func (s *Server) Shutdown(ctx context.Context) error {
    // 创建一个超时context
    shutdownCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
    defer cancel()

    // 关闭HTTP服务器
    if err := s.httpServer.Shutdown(shutdownCtx); err != nil {
        return fmt.Errorf("failed to shutdown HTTP server: %w", err)
    }

    // 取消所有后台任务
    cancel()

    return nil
}

// 使用信号处理优雅关闭
func main() {
    server := NewServer()

    // 添加任务
    server.AddTask(func(ctx context.Context) error {
        ticker := time.NewTicker(1 * time.Minute)
        defer ticker.Stop()

        for {
            select {
            case <-ctx.Done():
                return ctx.Err()
            case <-ticker.C:
                if err := doPeriodicTask(); err != nil {
                    log.Printf("Periodic task error: %v", err)
                }
            }
        }
    })

    if err := server.Start(); err != nil {
        log.Fatal(err)
    }

    // 等待信号
    sigChan := make(chan os.Signal, 1)
    signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
    <-sigChan

    // 优雅关闭
    ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
    defer cancel()

    if err := server.Shutdown(ctx); err != nil {
        log.Printf("Shutdown error: %v", err)
        os.Exit(1)
    }

    log.Println("Server shutdown gracefully")
}

func fanIn(channels ...<-chan string) <-chan string {
    output := make(chan string)

    var wg sync.WaitGroup
    for _, ch := range channels {
        wg.Add(1)
        go func(ch <-chan string) {
            defer wg.Done()
            for value := range ch {
                output <- value
            }
        }(ch)
    }

    go func() {
        wg.Wait()
        close(output)
    }()

    return output
}

// 使用示例
func main() {
    ch1 := make(chan string)
    ch2 := make(chan string)
    ch3 := make(chan string)

    // 启动生产者
    go func() {
        defer close(ch1)
        for i := 0; i < 5; i++ {
            ch1 <- fmt.Sprintf("ch1-%d", i)
            time.Sleep(100 * time.Millisecond)
        }
    }()

    go func() {
        defer close(ch2)
        for i := 0; i < 5; i++ {
            ch2 <- fmt.Sprintf("ch2-%d", i)
            time.Sleep(150 * time.Millisecond)
        }
    }()

    go func() {
