        for i := 0; i < 5; i++ {
            ch3 <- fmt.Sprintf("ch3-%d", i)
            time.Sleep(200 * time.Millisecond)
        }
    }()

    // 扇入
    output := fanIn(ch1, ch2, ch3)

    for value := range output {
        fmt.Println(value)
    }
}

func fanOut(input <-chan int, workerCount int) []<-chan int {
    outputs := make([]<-chan int, workerCount)

    for i := 0; i < workerCount; i++ {
        output := make(chan int)
        outputs[i] = output

        go func(ch chan<- int) {
            defer close(ch)
            for value := range input {
                // 处理数据
                result := process(value)
                ch <- result
            }
        }(output)
    }

    return outputs
}

func process(value int) int {
    // 模拟耗时操作
    time.Sleep(time.Duration(rand.Intn(100)) * time.Millisecond)
    return value * value
}

type RateLimiter struct {
    rate       time.Duration
    burst      int
    tokens     chan struct{}
    lastUpdate time.Time
    mutex      sync.Mutex
}

func NewRateLimiter(rate time.Duration, burst int) *RateLimiter {
    rl := &RateLimiter{
        rate:   rate,
        burst:  burst,
        tokens: make(chan struct{}, burst),
    }

    // 初始填充令牌
    for i := 0; i < burst; i++ {
        rl.tokens <- struct{}{}
    }

    return rl
}

func (rl *RateLimiter) Allow() bool {
    select {
    case <-rl.tokens:
        return true
    default:
        rl.refill()
        select {
        case <-rl.tokens:
            return true
        default:
            return false
        }
    }
}

func (rl *RateLimiter) refill() {
    rl.mutex.Lock()
    defer rl.mutex.Unlock()

    now := time.Now()
    elapsed := now.Sub(rl.lastUpdate)
    if elapsed < rl.rate {
        return
    }

    tokensToAdd := int(elapsed / rl.rate)
    if tokensToAdd <= 0 {
        return
    }

    for i := 0; i < tokensToAdd && len(rl.tokens) < cap(rl.tokens); i++ {
        select {
        case rl.tokens <- struct{}{}:
        default:
            break
        }
    }

    rl.lastUpdate = now
}

// 使用示例
func main() {
    limiter := NewRateLimiter(100*time.Millisecond, 5)

    for i := 0; i < 20; i++ {
        if limiter.Allow() {
            fmt.Printf("Request %d allowed\n", i)
        } else {
            fmt.Printf("Request %d rate limited\n", i)
        }
        time.Sleep(50 * time.Millisecond)
    }
}

