// ❌ 可能导致内存泄漏
func (s *Service) WatchChanges() {
    ticker := time.NewTicker(time.Second)
    defer ticker.Stop()

    for {
        select {
        case <-ticker.C:
            changes := s.getChanges()
            // 如果changes很大且处理很慢，会累积内存
            processChanges(changes)
        case <-s.ctx.Done():
            return
        }
    }
}

// ✅ 使用对象池避免内存泄漏
func (s *Service) WatchChanges() {
    ticker := time.NewTicker(time.Second)
    defer ticker.Stop()

    // 使用对象池
    changePool := &sync.Pool{
        New: func() interface{} {
            return make([]Change, 0, 100)
        },
    }

    for {
        select {
        case <-ticker.C:
            // 从池中获取切片
            changes := changePool.Get().([]Change)
            changes = changes[:0] // 重置长度但保留容量

            changes = s.getChanges()
            processChanges(changes)

            // 归还到池中
            changePool.Put(changes)

        case <-s.ctx.Done():
            return
        }
    }
}

// ❌ 字符串拼接性能差
func BuildQuery(params map[string]string) string {
    var query string
    for key, value := range params {
        query += key + "=" + value + "&"
    }
    return query
}

// ✅ 使用strings.Builder
func BuildQuery(params map[string]string) string {
    var builder strings.Builder
    builder.Grow(len(params) * 20) // 预分配容量

    first := true
    for key, value := range params {
        if !first {
            builder.WriteByte('&')
        }
        builder.WriteString(key)
        builder.WriteByte('=')
        builder.WriteString(value)
        first = false
    }

    return builder.String()
}

// ✅ 对于大量拼接，使用更高效的方式
func BuildLargeQuery(params map[string]string) string {
    parts := make([]string, 0, len(params)*2)
    for key, value := range params {
        parts = append(parts, key, value)
    }
    return strings.Join(parts, "=") + "&"
}

