// ✅ 复用切片
func (p *Processor) ProcessData(data []int) []int {
    // 复用已有的切片
    p.result = p.result[:0] // 重置长度但保留容量

    if cap(p.result) < len(data) {
        p.result = make([]int, 0, len(data))
    }

    for _, item := range data {
        if isValid(item) {
            p.result = append(p.result, process(item))
        }
    }

    return p.result
}

