// ✅ 分片锁减少竞争
type ShardedMap struct {
    shards []map[string]interface{}
    mutexes []sync.RWMutex
    shardCount int
}

func NewShardedMap(shardCount int) *ShardedMap {
    sm := &ShardedMap{
        shards: make([]map[string]interface{}, shardCount),
        mutexes: make([]sync.RWMutex, shardCount),
        shardCount: shardCount,
    }

    for i := 0; i < shardCount; i++ {
        sm.shards[i] = make(map[string]interface{})
    }

    return sm
}

func (sm *ShardedMap) getShard(key string) (map[string]interface{}, *sync.RWMutex) {
    hash := fnv32(key)
    index := hash % uint32(sm.shardCount)
    return sm.shards[index], &sm.mutexes[index]
}

func (sm *ShardedMap) Set(key string, value interface{}) {
    shard, mutex := sm.getShard(key)
    mutex.Lock()
    defer mutex.Unlock()
    shard[key] = value
}

func (sm *ShardedMap) Get(key string) (interface{}, bool) {
    shard, mutex := sm.getShard(key)
    mutex.RLock()
    defer mutex.RUnlock()
    value, exists := shard[key]
    return value, exists
}

func fnv32(s string) uint32 {
    h := fnv32OffsetBasis
    for i := 0; i < len(s); i++ {
        h ^= uint32(s[i])
        h *= fnv32Prime
    }
    return h
}

const (
    fnv32OffsetBasis = 2166136261
    fnv32Prime       = 16777619
)

// 使用channel实现无锁队列
type Queue struct {
    input  chan interface{}
    output chan interface{}
}

func NewQueue() *Queue {
    q := &Queue{
        input:  make(chan interface{}),
        output: make(chan interface{}),
    }

    go q.worker()
    return q
}

func (q *Queue) worker() {
    var items []interface{}

    for {
        var output chan interface{}
        var item interface{}

        if len(items) > 0 {
            output = q.output
            item = items[0]
        }

        select {
        case newItem := <-q.input:
            items = append(items, newItem)
        case output <- item:
            items = items[1:]
        }
    }
}

func (q *Queue) Enqueue(item interface{}) {
    q.input <- item
}

func (q *Queue) Dequeue() interface{} {
    return <-q.output
}

