// ❌ N+1查询问题
func (r *UserRepository) GetUsersWithPosts(userIDs []int) ([]UserWithPosts, error) {
    var results []UserWithPosts

    for _, id := range userIDs {
        user, err := r.FindByID(id)
        if err != nil {
            return nil, err
        }

        posts, err := r.FindPostsByUserID(id)
        if err != nil {
            return nil, err
        }

        results = append(results, UserWithPosts{
            User:  *user,
            Posts: posts,
        })
    }

    return results, nil
}

// ✅ 批量查询优化
func (r *UserRepository) GetUsersWithPosts(userIDs []int) ([]UserWithPosts, error) {
    // 批量查询用户
    users, err := r.FindByIDs(userIDs)
    if err != nil {
        return nil, err
    }

    // 批量查询文章
    posts, err := r.FindPostsByUserIDs(userIDs)
    if err != nil {
        return nil, err
    }

    // 按用户ID分组文章
    postsByUser := make(map[int][]Post)
    for _, post := range posts {
        postsByUser[post.UserID] = append(postsByUser[post.UserID], post)
    }

    // 组装结果
    var results []UserWithPosts
    for _, user := range users {
        userPosts := postsByUser[user.ID]
        results = append(results, UserWithPosts{
            User:  user,
            Posts: userPosts,
        })
    }

    return results, nil
}

// ❌ 创建大量临时对象
func ProcessData(data []byte) []byte {
    var result []byte

    for _, b := range data {
        // 每次循环都创建新的切片
        temp := make([]byte, 1)
        temp[0] = transform(b)
        result = append(result, temp...)
    }

    return result
}

// ✅ 复用对象，减少GC压力
func ProcessData(data []byte) []byte {
    // 预分配足够大的切片
    result := make([]byte, 0, len(data))

    for _, b := range data {
        result = append(result, transform(b))
    }

    return result
}

// ✅ 使用对象池
var bufferPool = sync.Pool{
    New: func() interface{} {
        return make([]byte, 0, 1024)
    },
}

func ProcessDataWithPool(data []byte) []byte {
    buffer := bufferPool.Get().([]byte)
    defer bufferPool.Put(buffer[:0]) // 归还时重置长度

    buffer = buffer[:0] // 重置长度但保留容量

    for _, b := range data {
        buffer = append(buffer, transform(b))
    }

    // 复制结果，因为buffer会被归还到池中
    result := make([]byte, len(buffer))
    copy(result, buffer)

    return result
}

// ❌ 导致内存逃逸
func ProcessLargeData() {
    data := make([]int, 1000000)

    // 匿名函数捕获data，导致data逃逸到堆
    go func() {
        for i := range data {
            data[i] *= 2
        }
    }()

    time.Sleep(time.Second)
}

// ✅ 避免内存逃逸
func ProcessLargeData() {
    data := make([]int, 1000000)

    // 传递指针而不是捕获整个数组
    go func(d []int) {
        for i := range d {
            d[i] *= 2
        }
    }(data)

    time.Sleep(time.Second)
}

// ✅ 使用值类型避免逃逸
type Point struct {
    X, Y int
}

func (p Point) Distance(other Point) int {
    // 值类型不会逃逸
    dx := p.X - other.X
    dy := p.Y - other.Y
    return dx*dx + dy*dy
}

// ❌ 指针类型可能导致逃逸
func (p *Point) Distance(other *Point) int {
    // 指针类型更容易逃逸
    dx := p.X - other.X
    dy := p.Y - other.Y
    return dx*dx + dy*dy
}

type MemoryMappedFile struct {
    data []byte
    file *os.File
}

func NewMemoryMappedFile(filename string) (*MemoryMappedFile, error) {
    file, err := os.Open(filename)
    if err != nil {
        return nil, err
    }

    stat, err := file.Stat()
    if err != nil {
        file.Close()
        return nil, err
    }

    data, err := syscall.Mmap(int(file.Fd()), 0, int(stat.Size()),
        syscall.PROT_READ, syscall.MAP_SHARED)
    if err != nil {
        file.Close()
        return nil, err
    }

    return &MemoryMappedFile{
        data: data,
        file: file,
    }, nil
}

func (m *MemoryMappedFile) Data() []byte {
    return m.data
}

func (m *MemoryMappedFile) Close() error {
    err1 := syscall.Munmap(m.data)
    err2 := m.file.Close()

    if err1 != nil {
        return err1
    }
    return err2
}

// 使用示例
func ProcessLargeFile(filename string) error {
    mmf, err := NewMemoryMappedFile(filename)
    if err != nil {
        return err
    }
    defer mmf.Close()

    data := mmf.Data()

    // 处理数据，无需将整个文件加载到内存
    for i := 0; i < len(data); i += 1024 {
        end := i + 1024
        if end > len(data) {
            end = len(data)
        }

        chunk := data[i:end]
        ProcessChunk(chunk)
    }

    return nil
}

func PrintMemStats() {
    var m runtime.MemStats
    runtime.ReadMemStats(&m)

    log.Printf("内存统计信息:")
    log.Printf("  分配的字节数: %d KB", m.Alloc/1024)
    log.Printf("  总分配的字节数: %d KB", m.TotalAlloc/1024)
    log.Printf("  系统内存字节数: %d KB", m.Sys/1024)
    log.Printf("  GC运行次数: %d", m.NumGC)
    log.Printf("  下一次GC目标字节数: %d KB", m.NextGC/1024)
    log.Printf("  堆对象数量: %d", m.HeapObjects)
}

// 内存监控器
type MemoryMonitor struct {
    interval time.Duration
    stopChan chan struct{}
}

func NewMemoryMonitor(interval time.Duration) *MemoryMonitor {
    return &MemoryMonitor{
        interval: interval,
        stopChan: make(chan struct{}),
    }
}

func (m *MemoryMonitor) Start() {
    ticker := time.NewTicker(m.interval)
    defer ticker.Stop()

    for {
        select {
        case <-ticker.C:
            PrintMemStats()
        case <-m.stopChan:
            return
        }
    }
}

func (m *MemoryMonitor) Stop() {
    close(m.stopChan)
}

// 使用示例
func main() {
    monitor := NewMemoryMonitor(10 * time.Second)
    go monitor.Start()
    defer monitor.Stop()

    // 应用程序逻辑
    // ...
}

