        require.NoError(t, err)
        assert.Equal(t, user.Name, retrievedUser.Name)
        assert.Equal(t, user.Email, retrievedUser.Email)
    })

    t.Run("Duplicate Email", func(t *testing.T) {
        req := &CreateUserRequest{
