import (
	"errors"
	"fmt"
)

type MyErr struct{ msg string }

func (e *MyErr) Error() string { return e.msg }

// 经典陷阱：返回具体指针类型的 nil，装进 error 后不再是 nil
func mightFail(fail bool) error {
	var perr *MyErr       // 惯用的包内具体错误类型
	if fail {
		perr = &MyErr{msg: "boom"}
	}
	return perr           // ❌ 即使 perr==nil，返回的 error 也不等于 nil
}

func mightFailOK(fail bool) error {
	if fail {
		var perr *MyErr
		perr = &MyErr{msg: "boom"}
		return perr           // ✅ 只在有错误时才返回具体类型
	}
	return nil                // ✅ 显式返回字面量 nil
}

func main() {
	// 1. nil 接口陷阱（核心）
	if err := mightFail(false); err != nil {
		fmt.Println("误判为失败！动态类型:", fmt.Sprintf("%T", err))
		// 输出：误判为失败！动态类型: *main.MyErr
	}
	if err := mightFailOK(false); err == nil {
		fmt.Println("正确：err == nil")
	}

	// 2. 类型断言与 type switch
	var x any = 42
	if n, ok := x.(int); ok {
		fmt.Println("是 int:", n)
	}
	switch v := x.(type) {
	case string:
		fmt.Println("string", v)
	case int:
		fmt.Println("int", v)
	default:
		fmt.Println("其他", v)
	}

	// 3. 断言到另一个接口（检查能力）
	var w any = errors.New("e")
	if _, ok := w.(interface{ Unwrap() error }); ok {
		fmt.Println("支持 Unwrap 的错误")
	}
}

// defer：注册延迟调用，函数返回时按 LIFO 逆序执行
defer f.Close()
defer mu.Unlock()
defer func() { /* 闭包可引用外层变量 */ }()

// panic：中断执行，逐层向上传播，途中执行已注册的 defer
panic("致命状态")

// recover：仅在 defer 的函数体内直接调用才生效
defer func() {
    if r := recover(); r != nil {
        log.Printf("recovered: %v", r)
    }
}()

package main

import "fmt"

// 命名返回值 + defer 修改返回值：defer 在赋值之后、返回之前执行
func double(n int) (result int) {
	defer func() { result *= 10 }()
	return n // 先 result = n，再 defer，最后返回
}

// 参数立即求值 vs 闭包延迟求值
func evalOrder() {
	x := 1
	defer fmt.Println("defer 参数（立即求值）:", x) // 打印 1
	x = 99
	defer func() { fmt.Println("defer 闭包（延迟求值）:", x) }() // 打印 99
}

// LIFO 顺序
func lifo() {
	defer fmt.Println("first registered")   // 第 3 个执行
	defer fmt.Println("second registered")  // 第 2 个执行
	fmt.Println("body")                     // 第 1 个执行
}

// recover：把 panic 转回普通错误（HTTP 中间件兜底的标准写法）
func safeCall(f func()) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("recovered: %v", r)
		}
	}()
	f()
	return nil
}

func main() {
	evalOrder()
	lifo()
	fmt.Println("double(3) =", double(3)) // 30

	err := safeCall(func() { panic("boom") })
	fmt.Println(err) // recovered: boom
}

package main

import "fmt"

func main() {
	// 1. nil slice：append 合法，len/range 安全（Go 惯用的"零值可用"）
	var s []int
	fmt.Println(len(s), cap(s)) // 0 0
	for range s {}              // 安全
	s = append(s, 1)            // 合法：自动分配底层数组
	fmt.Println(s)              // [1]

	// 2. nil map：读安全、写 panic（对照记忆）
	var m map[string]int
	fmt.Println(m["k"]) // 0（读返回零值，不 panic）
	fmt.Println(len(m)) // 0
	// m["k"] = 1        // panic: assignment to entry in nil map
	m = make(map[string]int) // 写之前必须 make
	m["k"] = 1

	// 3. nil func：调用 panic，回调先判空
	var cb func()
	fmt.Println(cb == nil) // true
	if cb != nil {
		cb()
	}

	// 4. nil interface：只有"零值接口"才等于 nil
	var i interface{ Speak() }
	fmt.Println(i == nil) // true（类型与值都是 nil）

	// 5. nil pointer：解引用 panic；方法有 nil 接收者防御则可调用
	type Node struct{ v int }
	var p *Node
	fmt.Println(p == nil) // true
	// _ = p.v            // panic: invalid memory address or nil pointer dereference
}

