// 定义函数类型
type Calculator func(int, int) int

// 定义函数
func add(a, b int) int {
    return a + b
}

func subtract(a, b int) int {
    return a - b
}

// 接受函数作为参数
func calculate(a, b int, op Calculator) int {
    return op(a, b)
}

func main() {
    // 将函数作为参数传递
    result1 := calculate(10, 5, add)
    fmt.Printf("10 + 5 = %d\n", result1)

    result2 := calculate(10, 5, subtract)
    fmt.Printf("10 - 5 = %d\n", result2)
}

func main() {
    // 匿名函数赋值给变量
    add := func(a, b int) int {
        return a + b
    }

    result := add(3, 4)
    fmt.Printf("3 + 4 = %d\n", result)

    // 在其他函数中使用匿名函数
    numbers := []int{1, 2, 3, 4, 5}
    filtered := filter(numbers, func(n int) bool {
        return n%2 == 0  // 只保留偶数
    })
    fmt.Printf("偶数: %v\n", filtered)
}

// 过滤函数
func filter(numbers []int, predicate func(int) bool) []int {
    var result []int
    for _, num := range numbers {
        if predicate(num) {
            result = append(result, num)
        }
    }
    return result
}

// 返回函数的函数
func makeAdder(x int) func(int) int {
    return func(y int) int {
        return x + y  // 闭包：访问外部变量x
    }
}

// 计数器工厂
func makeCounter() func() int {
    count := 0
    return func() int {
        count++
        return count
    }
}

func main() {
    // 闭包示例1
    add5 := makeAdder(5)
    add10 := makeAdder(10)

    fmt.Printf("5 + 3 = %d\n", add5(3))   // 8
    fmt.Printf("10 + 7 = %d\n", add10(7))  // 17

    // 闭包示例2 - 计数器
    counter1 := makeCounter()
    counter2 := makeCounter()

    fmt.Printf("计数器1: %d\n", counter1())  // 1
    fmt.Printf("计数器1: %d\n", counter1())  // 2
    fmt.Printf("计数器2: %d\n", counter2())  // 1 (独立状态)
    fmt.Printf("计数器1: %d\n", counter1())  // 3
}

// 定义结构体
type Rectangle struct {
    Width  float64
    Height float64
}

// 定义方法 - 值接收者
func (r Rectangle) Area() float64 {
    return r.Width * r.Height
}

// 定义方法 - 指针接收者（可以修改结构体）
func (r *Rectangle) SetDimensions(width, height float64) {
    r.Width = width
    r.Height = height
}

func (r Rectangle) String() string {
    return fmt.Sprintf("Rectangle{Width: %.1f, Height: %.1f}", r.Width, r.Height)
}

func main() {
    // 创建结构体实例
    rect := Rectangle{Width: 10.0, Height: 5.0}

    // 调用方法
    area := rect.Area()
    fmt.Printf("面积: %.2f\n", area)

    // 调用指针接收者方法
    rect.SetDimensions(20.0, 10.0)
    area = rect.Area()
    fmt.Printf("新面积: %.2f\n", area)

    // String()方法会被fmt.Printf自动调用
    fmt.Printf("矩形: %s\n", rect)
}

type Counter struct {
    count int
}

// 值接收者方法 - 不能修改原始值
func (c Counter) Increment() {
    c.count++
    fmt.Printf("值接收者内部: %d\n", c.count)
}

// 指针接收者方法 - 可以修改原始值
func (c *Counter) IncrementPtr() {
    c.count++
    fmt.Printf("指针接收者内部: %d\n", c.count)
}

func main() {
    counter := Counter{count: 0}

    fmt.Printf("初始值: %d\n", counter.count)

    // 调用值接收者方法
    counter.Increment()
    fmt.Printf("值接收者调用后: %d\n", counter.count)  // 仍然是0

    // 调用指针接收者方法
    counter.IncrementPtr()
    fmt.Printf("指针接收者调用后: %d\n", counter.count)  // 变为1
}

// 接口：只声明"能做什么"，不声明"是什么"
type Speaker interface {
    Speak() string
}

// 任何类型只要实现了 Speak() string，就自动满足 Speaker —— 无需声明
type Dog struct{ Name string }
type Robot struct{ ID int }

func (d Dog) Speak() string   { return d.Name + ": 汪汪" }
func (r Robot) Speak() string { return fmt.Sprintf("Robot-%d: 嘀嘀", r.ID) }

// 面向接口编程：函数不关心具体类型
func greet(s Speaker) {
    fmt.Println(s.Speak())
}

func main() {
    greet(Dog{Name: "旺财"})  // 旺财: 汪汪
    greet(Robot{ID: 7})       // Robot-7: 嘀嘀

    // 接口是"装具体值"的盒子
    speakers := []Speaker{Dog{Name: "阿黄"}, Robot{ID: 42}}
    for _, s := range speakers {
        greet(s)
    }
}

