package main

import (
    "errors"
    "fmt"
    "io"
    "os"
    "path/filepath"
)

// 文件处理错误类型
type FileProcessError struct {
    Operation string
    Filename  string
    Err       error
}

func (e FileProcessError) Error() string {
    return fmt.Sprintf("文件处理失败 [%s]: %s - %v",
        e.Operation, e.Filename, e.Err)
}

func (e FileProcessError) Unwrap() error {
    return e.Err
}

// 文件复制函数
func copyFile(src, dst string) error {
    // 检查源文件是否存在
    if _, err := os.Stat(src); os.IsNotExist(err) {
        return FileProcessError{
            Operation: "stat",
            Filename:  src,
            Err:       fmt.Errorf("源文件不存在"),
        }
    }

    // 创建目标目录
    if err := os.MkdirAll(filepath.Dir(dst), 0755); err != nil {
        return FileProcessError{
            Operation: "mkdir",
            Filename:  filepath.Dir(dst),
            Err:       err,
        }
    }

    // 打开源文件
    srcFile, err := os.Open(src)
    if err != nil {
        return FileProcessError{
            Operation: "open",
            Filename:  src,
            Err:       err,
        }
    }
    defer srcFile.Close()

    // 创建目标文件
    dstFile, err := os.Create(dst)
    if err != nil {
        return FileProcessError{
            Operation: "create",
            Filename:  dst,
            Err:       err,
        }
    }
    defer dstFile.Close()

    // 复制内容
    if _, err := io.Copy(dstFile, srcFile); err != nil {
        return FileProcessError{
            Operation: "copy",
            Filename:  fmt.Sprintf("%s -> %s", src, dst),
            Err:       err,
        }
    }

    return nil
}

func main() {
    src := "source.txt"
    dst := "backup/destination.txt"

    if err := copyFile(src, dst); err != nil {
        fmt.Printf("文件复制失败: %v\n", err)

        // 检查具体错误类型
        var fileErr FileProcessError
        if errors.As(err, &fileErr) {
            fmt.Printf("操作: %s\n", fileErr.Operation)
            fmt.Printf("文件: %s\n", fileErr.Filename)
        }

        os.Exit(1)
    }

    fmt.Printf("文件复制成功: %s -> %s\n", src, dst)
}

package main

import (
    "encoding/json"
    "errors"
    "fmt"
    "net/http"
)

// API错误响应结构
type APIError struct {
    Code    string                 `json:"code"`
    Message string                 `json:"message"`
    Details map[string]interface{} `json:"details,omitempty"`
}

func (e APIError) Error() string {
    return fmt.Sprintf("API错误 [%s]: %s", e.Code, e.Message)
}

// 常用API错误
var (
    ErrInvalidRequest = APIError{
        Code:    "INVALID_REQUEST",
        Message: "请求参数无效",
    }

    ErrUnauthorized = APIError{
        Code:    "UNAUTHORIZED",
        Message: "未授权访问",
    }

    ErrResourceNotFound = APIError{
        Code:    "RESOURCE_NOT_FOUND",
        Message: "资源不存在",
    }
)

// HTTP错误响应写入器
func writeError(w http.ResponseWriter, err error) {
    w.Header().Set("Content-Type", "application/json")

    var apiErr APIError
    if errors.As(err, &apiErr) {
        // 已知的API错误
        switch apiErr.Code {
        case "INVALID_REQUEST":
            w.WriteHeader(http.StatusBadRequest)
        case "UNAUTHORIZED":
            w.WriteHeader(http.StatusUnauthorized)
        case "RESOURCE_NOT_FOUND":
            w.WriteHeader(http.StatusNotFound)
        default:
            w.WriteHeader(http.StatusInternalServerError)
        }
    } else {
        // 未知错误
        apiErr = APIError{
            Code:    "INTERNAL_ERROR",
            Message: "内部服务器错误",
        }
        w.WriteHeader(http.StatusInternalServerError)
    }

    json.NewEncoder(w).Encode(apiErr)
}

// 业务处理器
func getUserHandler(w http.ResponseWriter, r *http.Request) {
    userID := r.URL.Query().Get("id")
    if userID == "" {
        writeError(w, ErrInvalidRequest)
        return
    }

    if userID == "123" {
        // 模拟未找到用户
        err := ErrResourceNotFound
        err.Details = map[string]interface{}{
            "user_id": userID,
            "resource": "user",
        }
        writeError(w, err)
        return
    }

    // 成功响应
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(map[string]interface{}{
        "user_id": userID,
        "name":    "张三",
    })
}

func main() {
    http.HandleFunc("/user", getUserHandler)
    fmt.Println("API服务器启动在 :8080")
    http.ListenAndServe(":8080", nil)
}

