)

type User struct {
	ID        int       `json:"id"`
	Username  string    `json:"username"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
}

type UserRepository struct {
	db *sql.DB
}

func NewUserRepository(db *sql.DB) *UserRepository {
	return &UserRepository{db: db}
}

func (r *UserRepository) Create(ctx context.Context, user *User) error {
	query := `INSERT INTO users (username, email, created_at) VALUES ($1, $2, $3) RETURNING id`
	return r.db.QueryRowContext(ctx, query, user.Username, user.Email, user.CreatedAt).Scan(&user.ID)
}

func (r *UserRepository) GetByID(ctx context.Context, id int) (*User, error) {
	user := &User{}
	query := `SELECT id, username, email, created_at FROM users WHERE id = $1`
	err := r.db.QueryRowContext(ctx, query, id).Scan(&user.ID, &user.Username, &user.Email, &user.CreatedAt)
	return user, err
}

func (r *UserRepository) Update(ctx context.Context, user *User) error {
	query := `UPDATE users SET username = $1, email = $2 WHERE id = $3`
	_, err := r.db.ExecContext(ctx, query, user.Username, user.Email, user.ID)
	return err
}

func (r *UserRepository) Delete(ctx context.Context, id int) error {
	query := `DELETE FROM users WHERE id = $1`
	_, err := r.db.ExecContext(ctx, query, id)
	return err
}

func TestUserRepositoryIntegration(t *testing.T) {
	ctx := context.Background()

	// 创建PostgreSQL容器
	pgContainer, err := postgres.RunContainer(ctx,
		testcontainers.WithImage("postgres:15-alpine"),
		postgres.WithDatabase("testdb"),
		postgres.WithUsername("testuser"),
		postgres.WithPassword("testpass"),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").
				WithOccurrence(2).
				WithStartupTimeout(5*time.Second),
		),
	)
	if err != nil {
		t.Fatalf("Failed to start PostgreSQL container: %v", err)
	}
	defer pgContainer.Terminate(ctx)

	// 获取数据库连接字符串
	connStr, err := pgContainer.ConnectionString(ctx, "sslmode=disable")
	if err != nil {
		t.Fatalf("Failed to get connection string: %v", err)
	}

	// 连接数据库
	db, err := sql.Open("postgres", connStr)
	if err != nil {
		t.Fatalf("Failed to connect to database: %v", err)
	}
	defer db.Close()

	// 创建表
	_, err = db.ExecContext(ctx, `
		CREATE TABLE IF NOT EXISTS users (
			id SERIAL PRIMARY KEY,
			username VARCHAR(50) NOT NULL UNIQUE,
			email VARCHAR(100) NOT NULL UNIQUE,
			created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
		)
	`)
	if err != nil {
		t.Fatalf("Failed to create table: %v", err)
	}

	// 创建用户仓库
	repo := NewUserRepository(db)

	// 测试创建用户
	t.Run("CreateUser", func(t *testing.T) {
		user := &User{
			Username:  "testuser",
			Email:     "test@example.com",
			CreatedAt: time.Now(),
		}

		err := repo.Create(ctx, user)
		if err != nil {
			t.Errorf("Failed to create user: %v", err)
		}

		if user.ID == 0 {
			t.Error("User ID should not be zero")
		}
	})

	// 测试获取用户
	t.Run("GetUser", func(t *testing.T) {
		user := &User{
			Username:  "getuser",
			Email:     "get@example.com",
			CreatedAt: time.Now(),
		}

		// 先创建用户
		err := repo.Create(ctx, user)
		if err != nil {
			t.Fatalf("Failed to create user: %v", err)
		}

		// 获取用户
		retrieved, err := repo.GetByID(ctx, user.ID)
		if err != nil {
			t.Errorf("Failed to get user: %v", err)
		}

		if retrieved.Username != user.Username {
			t.Errorf("Expected username %s, got %s", user.Username, retrieved.Username)
		}

		if retrieved.Email != user.Email {
			t.Errorf("Expected email %s, got %s", user.Email, retrieved.Email)
		}
	})

	// 测试更新用户
	t.Run("UpdateUser", func(t *testing.T) {
		user := &User{
			Username:  "updateuser",
			Email:     "update@example.com",
			CreatedAt: time.Now(),
		}

		// 先创建用户
		err := repo.Create(ctx, user)
		if err != nil {
			t.Fatalf("Failed to create user: %v", err)
		}

		// 更新用户
		user.Username = "updateduser"
		user.Email = "updated@example.com"

		err = repo.Update(ctx, user)
		if err != nil {
			t.Errorf("Failed to update user: %v", err)
		}

		// 验证更新
		retrieved, err := repo.GetByID(ctx, user.ID)
		if err != nil {
			t.Errorf("Failed to get updated user: %v", err)
		}

		if retrieved.Username != "updateduser" {
			t.Errorf("Expected updated username %s, got %s", "updateduser", retrieved.Username)
		}
	})

	// 测试删除用户
	t.Run("DeleteUser", func(t *testing.T) {
		user := &User{
			Username:  "deleteuser",
			Email:     "delete@example.com",
			CreatedAt: time.Now(),
		}

		// 先创建用户
		err := repo.Create(ctx, user)
		if err != nil {
			t.Fatalf("Failed to create user: %v", err)
		}

		// 删除用户
		err = repo.Delete(ctx, user.ID)
		if err != nil {
			t.Errorf("Failed to delete user: %v", err)
		}

		// 验证删除
		_, err = repo.GetByID(ctx, user.ID)
		if err == nil {
			t.Error("Expected error when getting deleted user")
		}
	})
}

