// 先写测试，预期会失败
func TestStringReverse(t *testing.T) {
    result := ReverseString("hello")
    expected := "olleh"
    if result != expected {
        t.Errorf("Expected %q, got %q", expected, result)
    }
}

// 最少代码使测试通过
func ReverseString(s string) string {
    // 硬编码解决当前测试
    if s == "hello" {
        return "olleh"
    }
    return ""
}

// 重构为通用实现
func ReverseString(s string) string {
    runes := []rune(s)
    n := len(runes)

    for i := 0; i < n/2; i++ {
        runes[i], runes[n-1-i] = runes[n-1-i], runes[i]
    }

    return string(runes)
}

