// 重构1：添加参数验证
func (c *Calculator) Add(a, b int) (int, error) {
    if a < 0 || b < 0 {
        return 0, errors.New("negative numbers not supported")
    }
    return a + b, nil
}

// 重构2：支持更多数值类型
func (c *Calculator) Add(a, b interface{}) (interface{}, error) {
    switch a := a.(type) {
    case int:
        if b, ok := b.(int); ok {
            return a + b, nil
        }
    case float64:
        if b, ok := b.(float64); ok {
            return a + b, nil
        }
    }
    return nil, errors.New("unsupported types")
}

