// 旧版本（已发版，只读，永不修改）
enum SchemaV1: VersionedSchema {
    static var versionIdentifier = Schema.Version(1, 0, 0)
    static var models: [any PersistentModel.Type] { [SchemaV1.Note.self] }

    @Model
    final class Note {
        var title: String
        var content: String
        var createdAt: Date
        init(title: String, content: String) {
            self.title = title
            self.content = content
            self.createdAt = .now
        }
    }
}

// 新版本（当前开发）
enum SchemaV2: VersionedSchema {
    static var versionIdentifier = Schema.Version(2, 0, 0)
    static var models: [any PersistentModel.Type] { [SchemaV2.Note.self] }

    @Model
    final class Note {
        var title: String
        var content: String
        var color: String?          // 本次新增字段（可选 → 轻量迁移可处理）
        var createdAt: Date
        init(title: String, content: String, color: String? = nil) {
            self.title = title
            self.content = content
            self.color = color
            self.createdAt = .now
        }
    }
}

enum NotesMigrationPlan: SchemaMigrationPlan {
    static var schemas: [any VersionedSchema.Type] {
        [SchemaV1.self, SchemaV2.self]          // 按版本顺序列出全部历史版本
    }

    static var stages: [MigrationStage] {
        [migrationV1toV2]
    }

    // 轻量迁移：加可选/带默认值字段这类可自动推断的改动
    static let migrationV1toV2 = MigrationStage.lightweight(
        fromVersion: SchemaV1.self,
        toVersion: SchemaV2.self
    )

    // 自定义迁移：框架推断不了时，手动搬数据（旧数据术语里的"重量级"）
    static let migrationV2toV3 = MigrationStage.custom(
        fromVersion: SchemaV2.self,
        toVersion: SchemaV3.self,
        willMigrate: { context in
            // 迁移前：旧 schema 的 ModelContext，可预读/暂存
        },
        didMigrate: { context in
            // 迁移后：新 schema 的 ModelContext，在此改写数据
        }
    )
}

// SchemaV3.Note 把 content 重命名为 body（并保留 color）
static let migrationV2toV3 = MigrationStage.custom(
    fromVersion: SchemaV2.self,
    toVersion: SchemaV3.self,
    willMigrate: { context in },
    didMigrate: { context in
        // didMigrate 拿到新 schema 上下文；旧值已由框架按同名/可推断字段搬运，
        // 重命名的字段在此按业务规则补偿（简单场景可让新旧字段并存一版，这里搬值）
        let notes = try context.fetch(FetchDescriptor<SchemaV3.Note>())
        for note in notes where note.body == nil {
            note.body = note.content        // 旧列值补到新列
        }
        try context.save()
    }
)

struct ZoomableImage: View {
    @GestureState private var scale: CGFloat = 1.0     // 手势结束自动回 1.0

    var body: some View {
        Image("photo")
            .scaleEffect(scale)
            .gesture(
                MagnifyGesture()
                    .updating($scale) { value, state, _ in
                        state = value.magnification     // 每帧回传
                    }
            )
    }
}

@GestureState var dragging: CGSize = .zero
@State var position: CGSize = .zero

content
    .offset(x: position.width + dragging.width,
            y: position.height + dragging.height)
    .gesture(
        DragGesture()
            .updating($dragging) { v, s, _ in s = v.translation }
            .onEnded { v in position.width += v.translation.width
                              position.height += v.translation.height }
    )

// 长按解锁后才进入拖拽（SequenceGesture）
let longPressThenDrag = SequenceGesture(LongPressGesture(minimumDuration: 0.3), DragGesture())
    .onEnded { value in
        if case .second(let drag) = value {
            _ = drag.translation      // .second 分支携带 DragGesture.Value
        }
    }

// 捏合 + 旋转同时进行（simultaneously(with:)）
let pinch = MagnifyGesture().updating($scale) { v, s, _ in s = v.magnification }
let rotate = RotateGesture().updating($angle) { v, s, _ in s = v.rotation }
image
    .scaleEffect(scale)
    .rotationEffect(angle)
    .gesture(pinch.simultaneously(with: rotate))

