@Retention(RetentionPolicy.RUNTIME)      // 运行时反射要读 → 必须 RUNTIME
@Target(ElementType.METHOD)
@Repeatable(Tags.class)                  // 允许重复
public @interface Tag {
    String value();                      // 属性名 value，使用时可省略 "value ="
}

