// 高性能过滤组件
interface PerformanceFilterProps {
  items: any[]
  onFilterChange: (filteredItems: any[]) => void
}

export function PerformanceFilter({ items, onFilterChange }: PerformanceFilterProps) {
  const [filters, setFilters] = useState({
    category: '',
    priceRange: [0, 1000] as [number, number],
    inStockOnly: false,
    searchTerm: ''
  })

  const [isPending, startTransition] = useTransition()

  // 记忆化过滤逻辑
  const filteredItems = useMemo(() => {
    return items.filter(item => {
      // 类别过滤
      if (filters.category && item.category !== filters.category) {
        return false
      }

      // 价格范围过滤
      if (item.price < filters.priceRange[0] || item.price > filters.priceRange[1]) {
        return false
      }

      // 库存过滤
      if (filters.inStockOnly && !item.inStock) {
        return false
      }

      // 搜索过滤
      if (filters.searchTerm) {
        const searchLower = filters.searchTerm.toLowerCase()
        return (
          item.title.toLowerCase().includes(searchLower) ||
          item.description.toLowerCase().includes(searchLower)
        )
      }

      return true
    })
  }, [items, filters])

  // 防抖的过滤更新
  const updateFilters = useCallback((newFilters: typeof filters) => {
    startTransition(() => {
      setFilters(newFilters)
    })
  }, [])

  // 当过滤结果变化时，通知父组件
  useEffect(() => {
    onFilterChange(filteredItems)
  }, [filteredItems, onFilterChange])

  return (
    <div className="bg-white rounded-lg shadow p-6 mb-6">
      <h2 className="text-xl font-semibold mb-4">高级过滤</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* 搜索框 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            搜索
          </label>
          <input
            type="text"
            value={filters.searchTerm}
            onChange={(e) => updateFilters({ ...filters, searchTerm: e.target.value })}
            placeholder="搜索商品..."
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
          />
        </div>

        {/* 类别选择 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            类别
          </label>
          <select
            value={filters.category}
            onChange={(e) => updateFilters({ ...filters, category: e.target.value })}
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
          >
            <option value="">全部类别</option>
            <option value="electronics">电子产品</option>
            <option value="clothing">服装</option>
            <option value="books">图书</option>
            <option value="home">家居</option>
          </select>
        </div>

        {/* 价格范围 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            价格范围
          </label>
          <div className="flex items-center space-x-2">
            <input
              type="number"
              value={filters.priceRange[0]}
              onChange={(e) => updateFilters({
                ...filters,
                priceRange: [parseInt(e.target.value), filters.priceRange[1]]
              })}
              className="w-20 px-2 py-1 border border-gray-300 rounded focus:ring-blue-500 focus:border-blue-500"
            />
            <span>-</span>
            <input
              type="number"
              value={filters.priceRange[1]}
              onChange={(e) => updateFilters({
                ...filters,
                priceRange: [filters.priceRange[0], parseInt(e.target.value)]
              })}
              className="w-20 px-2 py-1 border border-gray-300 rounded focus:ring-blue-500 focus:border-blue-500"
            />
          </div>
        </div>

        {/* 库存状态 */}
        <div className="flex items-end">
          <label className="flex items-center space-x-2">
            <input
              type="checkbox"
              checked={filters.inStockOnly}
              onChange={(e) => updateFilters({ ...filters, inStockOnly: e.target.checked })}
              className="rounded text-blue-600 focus:ring-blue-500"
            />
            <span className="text-sm font-medium text-gray-700">
              仅显示有库存
            </span>
          </label>
        </div>
      </div>

      {/* 过滤状态 */}
      <div className="mt-4 flex items-center justify-between">
        <div className="text-sm text-gray-600">
          找到 {filteredItems.length} 个商品
          {isPending && <span className="ml-2 text-blue-600">(更新中...)</span>}
        </div>

        <button
          onClick={() => updateFilters({
            category: '',
            priceRange: [0, 1000],
            inStockOnly: false,
            searchTerm: ''
          })}
          className="text-sm text-blue-600 hover:text-blue-800"
        >
          重置过滤
        </button>
      </div>
    </div>
  )
}

// 虚拟滚动组件
interface VirtualScrollProps {
  items: any[]
  itemHeight: number
  containerHeight: number
  renderItem: (item: any, index: number) => React.ReactNode
}

export function VirtualScroll({
  items,
  itemHeight,
  containerHeight,
  renderItem
}: VirtualScrollProps) {
  const [scrollTop, setScrollTop] = useState(0)

  // 计算可见项目
  const visibleRange = useMemo(() => {
    const startIndex = Math.floor(scrollTop / itemHeight)
    const endIndex = Math.min(
      startIndex + Math.ceil(containerHeight / itemHeight) + 1,
      items.length - 1
    )
    return { startIndex, endIndex }
  }, [scrollTop, itemHeight, containerHeight, items.length])

  const visibleItems = useMemo(() => {
    return items.slice(visibleRange.startIndex, visibleRange.endIndex + 1)
  }, [items, visibleRange])

  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop)
  }, [])

  return (
    <div
      style={{ height: containerHeight, overflow: 'auto' }}
      onScroll={handleScroll}
      className="border border-gray-200 rounded-lg"
    >
      <div style={{ height: items.length * itemHeight, position: 'relative' }}>
        {visibleItems.map((item, index) => {
          const actualIndex = visibleRange.startIndex + index
          return (
            <div
              key={item.id || actualIndex}
              style={{
                position: 'absolute',
                top: actualIndex * itemHeight,
                left: 0,
                right: 0,
                height: itemHeight
              }}
            >
              {renderItem(item, actualIndex)}
            </div>
          )
        })}
      </div>
    </div>
  )
}

