import { NextAuthOptions } from 'next-auth'
import { PrismaAdapter } from '@next-auth/prisma-adapter'
import CredentialsProvider from 'next-auth/providers/credentials'
import GoogleProvider from 'next-auth/providers/google'
import GitHubProvider from 'next-auth/providers/github'
import bcrypt from 'bcryptjs'
import { prisma } from '@/lib/db'

// 认证选项配置
export const authOptions: NextAuthOptions = {
  // 数据库适配器
  adapter: PrismaAdapter(prisma),

  // 会话配置
  session: {
    strategy: 'jwt',
    maxAge: 30 * 24 * 60 * 60, // 30天
    updateAge: 24 * 60 * 60 // 24小时更新一次
  },

  // JWT配置
  jwt: {
    secret: process.env.NEXTAUTH_SECRET!,
    encryption: true,
    maxAge: 30 * 24 * 60 * 60
  },

  // 认证提供者
  providers: [
    // 凭证认证
    CredentialsProvider({
      name: 'credentials',
      credentials: {
        email: { label: 'Email', type: 'email' },
        password: { label: 'Password', type: 'password' }
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) {
          return null
        }

        const user = await prisma.user.findUnique({
          where: { email: credentials.email },
          include: {
            roles: true,
            permissions: true
          }
        })

        if (!user || !user.isActive) {
          return null
        }

        const isPasswordValid = await bcrypt.compare(
          credentials.password,
          user.passwordHash
        )

        if (!isPasswordValid) {
          return null
        }

        // 检查账户是否被锁定
        if (user.lockedUntil && user.lockedUntil > new Date()) {
          throw new Error('账户已被锁定，请稍后再试')
        }

        // 更新最后登录时间
        await prisma.user.update({
          where: { id: user.id },
          data: {
            lastLoginAt: new Date(),
            loginAttempts: 0,
            lockedUntil: null
          }
        })

        return {
          id: user.id,
          email: user.email,
          name: user.displayName,
          role: user.roles.map(r => r.name),
          permissions: user.permissions.map(p => p.name)
        }
      }
    }),

    // Google OAuth
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
      allowDangerousEmailAccountLinking: true
    }),

    // GitHub OAuth
    GitHubProvider({
      clientId: process.env.GITHUB_ID!,
      clientSecret: process.env.GITHUB_SECRET!,
      allowDangerousEmailAccountLinking: true
    })
  ],

  // 回调函数
  callbacks: {
    // JWT回调
    async jwt({ token, user, trigger, session }) {
      // 用户登录时添加额外信息
      if (user) {
        token.id = user.id
        token.role = user.role
        token.permissions = user.permissions
        token.emailVerified = user.emailVerified
      }

      // 会话更新时更新token
      if (trigger === 'update' && session) {
        token.id = session.user.id
        token.role = session.user.role
        token.permissions = session.user.permissions
      }

      return token
    },

    // 会话回调
    async session({ session, token }) {
      if (token) {
        session.user.id = token.id
        session.user.role = token.role
        session.user.permissions = token.permissions
        session.user.emailVerified = token.emailVerified
      }
      return session
    },

    // 重定向回调
    async redirect({ url, baseUrl }) {
      // 允许相对URL和同源URL
      if (url.startsWith('/')) return `${baseUrl}${url}`
      if (new URL(url).origin === baseUrl) return url
      return baseUrl
    },

    // 登录回调
    async signIn({ user, account, profile }) {
      if (account?.provider === 'credentials') {
        return true // 允许凭据登录
      }

      // OAuth登录时的额外验证
      if (account?.provider === 'google') {
        // 验证Google账户
        const allowedDomains = ['example.com', 'company.com']
        const domain = profile?.email?.split('@')[1]

        if (domain && !allowedDomains.includes(domain)) {
          throw new Error('不允许的邮箱域名')
        }
      }

      return true
    }
  },

  // 页面配置
  pages: {
    signIn: '/auth/login',
    signUp: '/auth/register',
    error: '/auth/error',
    verifyRequest: '/auth/verify-request',
    newUser: '/auth/welcome'
  },

  // 事件回调
  events: {
    // 创建用户时
    async createUser({ user }) {
      console.log('New user created:', user)
      // 发送欢迎邮件
      await sendWelcomeEmail(user.email || '')
    },

    // 登录时
    async signIn({ user, account, isNewUser }) {
      console.log('User signed in:', { user, account, isNewUser })

      if (isNewUser) {
        // 新用户引导
        await trackNewUserOnboarding(user.id)
      }
    },

    // 登出时
    async signOut({ session }) {
      console.log('User signed out:', session)
      // 清理用户相关缓存
      await clearUserCache(session.user.id)
    }
  }
}

