  SYSTEM_ADMIN: 'system:admin'
} as const

export type Permission = typeof PERMISSIONS[keyof typeof PERMISSIONS]

// 用户角色基础权限（独立常量：避免对象字面量初始化期间自引用引发的 TDZ ReferenceError）
const USER_PERMISSIONS: Permission[] = [
  PERMISSIONS.USER_READ,
  PERMISSIONS.USER_UPDATE_OWN,
  PERMISSIONS.USER_DELETE_OWN,
  PERMISSIONS.ARTICLE_READ,
  PERMISSIONS.ARTICLE_CREATE,
  PERMISSIONS.ARTICLE_UPDATE_OWN,
  PERMISSIONS.ARTICLE_DELETE_OWN,
  PERMISSIONS.COMMENT_READ,
  PERMISSIONS.COMMENT_CREATE,
  PERMISSIONS.COMMENT_UPDATE_OWN,
  PERMISSIONS.COMMENT_DELETE_OWN
]

// 角色权限映射
export const ROLE_PERMISSIONS: Record<string, Permission[]> = {
  guest: [],

  user: USER_PERMISSIONS,

  moderator: [
    ...USER_PERMISSIONS,
    PERMISSIONS.COMMENT_DELETE_ANY
  ],

  author: [
    ...USER_PERMISSIONS,
    PERMISSIONS.ARTICLE_PUBLISH
  ],

  editor: [
    ...USER_PERMISSIONS,
    PERMISSIONS.ARTICLE_PUBLISH,
    PERMISSIONS.ARTICLE_UPDATE_ANY,
    PERMISSIONS.ARTICLE_DELETE_ANY
  ],

  admin: Object.values(PERMISSIONS)
}

// 权限检查中间件
export async function requireAuth(
  request: NextRequest,
  requiredPermissions: Permission[] = []
) {
  const token = await getToken({
    req: request,
    secret: process.env.NEXTAUTH_SECRET!
  })

  if (!token) {
    return {
      error: 'Unauthorized',
      status: 401
    }
  }

  // 获取用户权限
  const user = await prisma.user.findUnique({
    where: { id: token.sub },
    include: {
      roles: true,
      permissions: true
    }
  })

  if (!user || !user.isActive) {
    return {
      error: 'User not found or inactive',
      status: 401
    }
  }

  // 检查权限
  const userPermissions = user.permissions.map(p => p.name)
  const userRoles = user.roles.map(r => r.name)

  // 检查管理员权限
  if (userRoles.includes('admin')) {
    return { user }
  }

  // 检查所需权限
  const hasAllPermissions = requiredPermissions.every(permission =>
    userPermissions.includes(permission) ||
    userRoles.some(role =>
      ROLE_PERMISSIONS[role as keyof typeof ROLE_PERMISSIONS]?.includes(permission)
    )
  )

  if (!hasAllPermissions) {
    return {
      error: 'Insufficient permissions',
      status: 403
    }
  }

  return { user }
}

// 权限检查Hook (客户端)
export function usePermissions() {
  const { data: session } = useSession()

  const user = session?.user

  const hasPermission = useCallback((permission: Permission) => {
    if (!user) return false
    return user.permissions?.includes(permission) || user.role?.includes('admin')
  }, [user])

  const hasRole = useCallback((role: string) => {
    if (!user) return false
    return user.role?.includes(role) || user.role?.includes('admin')
  }, [user])

  const hasAnyPermission = useCallback((permissions: Permission[]) => {
    if (!user) return false
    return permissions.some(permission => hasPermission(permission))
  }, [hasPermission])

  const hasAllPermissions = useCallback((permissions: Permission[]) => {
    if (!user) return false
    return permissions.every(permission => hasPermission(permission))
  }, [hasPermission])

  return {
    user,
    hasPermission,
    hasRole,
    hasAnyPermission,
    hasAllPermissions
  }
}

// 权限包装器组件
interface PermissionWrapperProps {
  children: React.ReactNode
  permission?: Permission
  permissions?: Permission[]
  role?: string
  fallback?: React.ReactNode
}

export function PermissionWrapper({
  children,
  permission,
  permissions = [],
  role,
  fallback = null
}: PermissionWrapperProps) {
  const { hasPermission, hasRole } = usePermissions()

  const hasAccess = role
    ? hasRole(role)
    : permission
    ? hasPermission(permission)
    : permissions.length > 0
    ? permissions.some(p => hasPermission(p))
    : true

  if (!hasAccess) {
    return <>{fallback}</>
  }

  return <>{children}</>
}

// src/app/api/v1/users/[id]/route.ts
import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { requireAuth } from '@/lib/auth/permissions'
import { PERMISSIONS } from '@/lib/auth/permissions'
import { updateUserSchema, paginationSchema } from '@/lib/validation'
import { prisma } from '@/lib/db'
import { rateLimit } from '@/lib/rate-limit'
import { auditLog } from '@/lib/audit'

// 输入验证schema
const updateParamsSchema = z.object({
  id: z.string().cuid()
})

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // 参数验证
    const { id } = updateParamsSchema.parse(await params)

    // 权限检查
    const auth = await requireAuth(request, [PERMISSIONS.USER_READ])
    if (auth.error) {
      return NextResponse.json(
        { error: auth.error },
        { status: auth.status }
      )
    }

    // 查询用户
    const user = await prisma.user.findUnique({
      where: { id },
      select: {
        id: true,
        email: true,
        username: true,
        displayName: true,
        avatar: true,
        bio: true,
        isActive: true,
        emailVerified: true,
        roles: {
          select: {
            id: true,
            name: true,
            description: true
          }
        },
        permissions: {
          select: {
            id: true,
            name: true,
            description: true
          }
        },
        createdAt: true,
        updatedAt: true,
        lastLoginAt: true
      }
    })

    if (!user) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      )
    }

    // 审计日志
    await auditLog({
      action: 'USER_READ',
      userId: auth.user.id,
      targetId: id,
      metadata: { requestedBy: auth.user.id }
    })

    return NextResponse.json({
      success: true,
      data: user
    })

  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid parameters', details: error.issues },
        { status: 400 }
      )
    }

    console.error('Error fetching user:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // 参数验证
    const { id } = updateParamsSchema.parse(await params)
    const body = await request.json()
    const validatedData = updateUserSchema.parse(body)

    // 权限检查 - 用户只能更新自己的信息，管理员可以更新任何人
    const auth = await requireAuth(request, [])
    if (auth.error) {
      return NextResponse.json(
        { error: auth.error },
        { status: auth.status }
      )
    }

    // 检查权限
    const canUpdate =
      auth.user.id === id ||
      auth.user.permissions.includes(PERMISSIONS.USER_UPDATE_ANY) ||
      auth.user.role.includes('admin')

    if (!canUpdate) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      )
    }

    // 更新用户
    const updatedUser = await prisma.user.update({
      where: { id },
      data: {
        ...validatedData,
        updatedAt: new Date()
      },
      select: {
        id: true,
        email: true,
        username: true,
        displayName: true,
        avatar: true,
        bio: true,
        updatedAt: true
      }
    })

    // 审计日志
    await auditLog({
      action: 'USER_UPDATE',
      userId: auth.user.id,
      targetId: id,
      metadata: {
        updatedFields: Object.keys(validatedData),
        updatedBy: auth.user.id
      }
    })

    return NextResponse.json({
      success: true,
      data: updatedUser,
      message: 'User updated successfully'
    })

  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid data', details: error.issues },
        { status: 400 }
      )
    }

    console.error('Error updating user:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // 参数验证
    const { id } = updateParamsSchema.parse(await params)

    // 权限检查
    const auth = await requireAuth(request, [PERMISSIONS.USER_DELETE_ANY])
    if (auth.error) {
      return NextResponse.json(
        { error: auth.error },
        { status: auth.status }
      )
    }

    // 软删除用户
    const deletedUser = await prisma.user.update({
      where: { id },
      data: {
        isActive: false,
        deletedAt: new Date()
      },
      select: {
        id: true,
        email: true,
        displayName: true
      }
    })

    // 审计日志
    await auditLog({
      action: 'USER_DELETE',
      userId: auth.user.id,
      targetId: id,
      metadata: { deletedBy: auth.user.id }
    })

    return NextResponse.json({
      success: true,
      message: 'User deleted successfully'
    })

  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid parameters', details: error.issues },
        { status: 400 }
      )
    }

    console.error('Error deleting user:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

