  memory: { trend: 'increasing' | 'decreasing' | 'stable'; growth: number }
  disk: { trend: 'increasing' | 'decreasing' | 'stable'; growth: number }
  network: { trend: 'increasing' | 'decreasing' | 'stable'; growth: number }
