import { createStore } from 'redux';

interface GlobalState {
  user: UserSession | null;
  cart: CartItem[];
  theme: 'light' | 'dark';
  locale: string;
  notifications: Notification[];
}

type GlobalAction =
  | { type: 'SET_USER'; payload: UserSession | null }
  | { type: 'UPDATE_CART'; payload: CartItem[] }
  | { type: 'SET_THEME'; payload: 'light' | 'dark' }
  | { type: 'SET_LOCALE'; payload: string }
  | { type: 'ADD_NOTIFICATION'; payload: Notification };

const initialState: GlobalState = {
  user: null,
  cart: [],
  theme: 'light',
  locale: 'zh-CN',
  notifications: [],
};

function globalReducer(state: GlobalState, action: GlobalAction): GlobalState {
  switch (action.type) {
    case 'SET_USER':
      return { ...state, user: action.payload };
    case 'UPDATE_CART':
      return { ...state, cart: action.payload };
    case 'SET_THEME':
      return { ...state, theme: action.payload };
    case 'SET_LOCALE':
      return { ...state, locale: action.payload };
    case 'ADD_NOTIFICATION':
      return {
        ...state,
        notifications: [...state.notifications, action.payload]
      };
    default:
      return state;
  }
}

export const globalStore = createStore(globalReducer);

// 全局状态Hook
export function useGlobalState() {
  const [state, setState] = React.useState(globalStore.getState());

  React.useEffect(() => {
    const unsubscribe = globalStore.subscribe(() => {
      setState(globalStore.getState());
    });

    return unsubscribe;
  }, []);

  const dispatch = React.useCallback((action: GlobalAction) => {
    globalStore.dispatch(action);
  }, []);

  return { state, dispatch };
}

// src/events/event-bus.ts
type EventHandler = (data?: any) => void;

class EventBus {
  private events: Map<string, EventHandler[]> = new Map();

  // 订阅事件
  on(event: string, handler: EventHandler): () => void {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }

    const handlers = this.events.get(event)!;
    handlers.push(handler);

    // 返回取消订阅函数
    return () => {
      const index = handlers.indexOf(handler);
      if (index > -1) {
        handlers.splice(index, 1);
      }
    };
  }

  // 发布事件
  emit(event: string, data?: any): void {
    const handlers = this.events.get(event);
    if (handlers) {
      handlers.forEach(handler => {
        try {
          handler(data);
        } catch (error) {
          console.error(`Event handler error for ${event}:`, error);
        }
      });
    }
  }

  // 取消订阅
  off(event: string, handler?: EventHandler): void {
    if (!handler) {
      this.events.delete(event);
      return;
    }

    const handlers = this.events.get(event);
    if (handlers) {
      const index = handlers.indexOf(handler);
      if (index > -1) {
        handlers.splice(index, 1);
      }
    }
  }

  // 清理所有事件
  clear(): void {
    this.events.clear();
  }
}

// 创建全局事件总线实例
export const globalEventBus = new EventBus();

// 标准化事件类型
