  },
  jwt: {
    secret: process.env.NEXTAUTH_JWT_SECRET!,
    encryption: true,
    signingKey: process.env.NEXTAUTH_JWT_SIGNING_KEY!,
    encryptionKey: process.env.NEXTAUTH_JWT_ENCRYPTION_KEY!,
    // 自定义JWT Header
    headers: {
      typ: 'JWT',
      alg: 'HS256'
    },
    // JWT Claims
    claims: {
      iss: 'your-app',
      aud: 'your-users',
      exp: 1800, // 30分钟
      nbf: true,
      iat: true,
      jti: true
    }
  },
  providers: [
    CredentialsProvider({
      id: 'credentials',
      name: 'Credentials',
      type: 'credentials',
      credentials: {
        email: { label: 'Email', type: 'email' },
        password: { label: 'Password', type: 'password' }
      },
      async authorize(credentials) {
        try {
          const { email, password } = credentials

          // 输入验证
          if (!email || !password) {
            return null
          }

          // 查找用户
          const user = await prisma.user.findUnique({
            where: { email },
            include: { security: true }
          })

          if (!user) {
            return null
          }

          // 账户状态检查
          if (!user.isActive) {
            return null
          }

          // 锁定状态检查
          if (user.security?.isLocked) {
            const lockUntil = new Date(user.security.lockedUntil!)
            if (new Date() < lockUntil) {
              return null
            }
            // 解锁账户
            await prisma.userSecurity.update({
              where: { userId: user.id },
              data: { isLocked: false, lockedUntil: null, failedAttempts: 0 }
            })
          }

          // 密码验证
          const isPasswordValid = await passwordSecurity.verifyPassword(password, user.password)
          if (!isPasswordValid) {
            // 更新失败尝试
            await this.handleFailedLogin(user.id, user.security?.failedAttempts || 0)
            return null
          }

          // 重置失败尝试
          if (user.security?.failedAttempts > 0) {
            await prisma.userSecurity.update({
              where: { userId: user.id },
              data: { failedAttempts: 0, isLocked: false, lockedUntil: null }
            })
          }

          // 会话审计日志
          await prisma.sessionAudit.create({
            data: {
              userId: user.id,
              action: 'login_success',
              ipAddress: 'REMOTE_ADDR', // 需要在中间件中获取
              userAgent: 'HTTP_USER_AGENT', // 需要在中间件中获取
              device: this.detectDevice()
            }
          })

          return {
            id: user.id,
            email: user.email,
            name: user.name,
            role: user.role,
            image: user.image
          }
        } catch (error) {
          console.error('Authorization error:', error)
          return null
        }
      },

      // 处理失败登录
      async handleFailedLogin(userId: string, failedAttempts: number) {
        const maxAttempts = 5
        const newAttempts = failedAttempts + 1

        let lockUntil: Date | null = null

        if (newAttempts >= maxAttempts) {
          // 锁定账户30分钟
          lockUntil = new Date(Date.now() + 30 * 60 * 1000)
        }

        await prisma.userSecurity.update({
          where: { userId },
          data: {
            failedAttempts: newAttempts,
            isLocked: lockUntil !== null,
            lockedUntil
          }
        })

        // 安全审计日志
        await prisma.securityAudit.create({
          data: {
            userId,
            action: 'login_failed',
            ipAddress: 'REMOTE_ADDR',
            userAgent: 'HTTP_USER_AGENT',
            device: this.detectDevice(),
            details: `Failed attempt ${newAttempts}/${maxAttempts}`
          }
        })
      },

      // 设备检测
      detectDevice(): string {
        const userAgent = navigator.userAgent
        if (/Mobile/i.test(userAgent)) {
          return 'mobile'
        } else if (/Tablet|iPad/i.test(userAgent)) {
          return 'tablet'
        } else {
          return 'desktop'
        }
      }
    }),
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
      authorization: {
        params: {
          prompt: 'consent',
          access_type: 'offline',
          response_type: 'code',
          scope: 'openid email profile'
        }
      }
    })
  ],
  pages: {
    signIn: '/auth/signin',
    error: '/auth/error',
    signOut: '/auth/signout'
  },
  callbacks: {
    // JWT签名回调
    async jwt({ token, user }) {
      const payload = {
        sub: user.id,
        email: user.email,
        role: user.role,
        iat: Date.now() / 1000,
        exp: Math.floor(Date.now() / 1000) + (30 * 24 * 60 * 60)
      }

      return { ...payload, jti: generateRandomString(16) }
    },

    // 会话回调
    async session({ session, token }) {
      try {
        const decodedToken = await verifyJWT(token, process.env.NEXTAUTH_JWT_SECRET!)

        // 验证会话有效性
        const userSession = await prisma.session.findFirst({
          where: {
            userId: decodedToken.sub,
            expiresAt: { gt: new Date() }
          },
          include: { user: true }
        })

        if (!userSession || !userSession.user.isActive) {
          return null
        }

        // 更新会话活跃状态
        await prisma.session.update({
          where: { id: userSession.id },
          data: { lastActiveAt: new Date() }
        })

        return {
          ...session,
          user: {
            ...session.user,
            role: decodedToken.role
          }
        }
      } catch (error) {
        console.error('Session verification error:', error)
        return null
      }
    },

    // 重定向回调
    async redirect({ url, baseUrl }) {
      // 根据用户角色重定向
      if (url.includes('/auth/callback')) {
        const session = await auth()
        if (session?.user?.role === 'admin') {
          return '/admin/dashboard'
        } else if (session?.user?.role === 'moderator') {
          return '/moderator/dashboard'
        } else {
          return '/user/dashboard'
        }
      }
      return url
    }
  },

  // 事件处理
  events: {
    async signIn(message) {
      console.log('Sign in event:', message)
    },
    async signOut(message) {
      console.log('Sign out event:', message)
    },
    async createUser(message) {
      console.log('Create user event:', message)
    },
    async updateUser(message) {
      console.log('Update user event:', message)
    },
    async linkAccount(message) {
      console.log('Link account event:', message)
    },
    async session(message) {
      console.log('Session event:', message)
    }
  },

  // 调试
  debug: process.env.NODE_ENV === 'development'
}

