// lib/apollo-server.ts
import { ApolloServer } from '@apollo/server';
import { startServerAndCreateNextHandler } from '@as-integrations/next';
import { NextRequest } from 'next/server';
import { makeExecutableSchema } from '@graphql-tools/schema';
import { loadFilesSync } from '@graphql-tools/load-files';
import { mergeTypeDefs, mergeResolvers } from '@graphql-tools/merge';
import { GraphQLContext } from '@/types/graphql';
import { authMiddleware } from '@/middleware/auth';
import { rateLimitMiddleware } from '@/middleware/rate-limit';
import { errorHandlingMiddleware } from '@/middleware/error-handling';
import { performanceMiddleware } from '@/middleware/performance';
import { loggingMiddleware } from '@/middleware/logging';

// 加载GraphQL Schema
const typeDefs = mergeTypeDefs(
  loadFilesSync('graphql/schemas/**/*.graphql', { recursive: true })
);

// 加载解析器
const resolvers = mergeResolvers(
  loadFilesSync('graphql/resolvers/**/*.ts', { recursive: true })
);

// 创建可执行Schema
const schema = makeExecutableSchema({
  typeDefs,
  resolvers,
  resolverValidationOptions: {
    requireResolversForResolveType: false,
  },
});

// 创建Apollo Server
const server = new ApolloServer<GraphQLContext>({
  schema,
  introspection: process.env.NODE_ENV === 'development',
  persistedQueries: {
    cache: 'bounded',
    ttl: 900, // 15分钟缓存
  },
  plugins: [
    // 查询复杂度分析插件
    complexityAnalysisPlugin(),
    // 查询深度限制插件
    depthLimitPlugin(7),
    // 查询缓存插件
    responseCachePlugin({
      sessionId: (requestContext) => requestContext.request.http.headers.get('authorization') || null,
    }),
    // 性能监控插件
    performanceMonitoringPlugin(),
    // 错误报告插件
    errorReportingPlugin(),
  ],
  // 验证规则
  validationRules: [
    // 深度限制
    depthLimit(7, { ignore: ['IntrospectionQuery'] }),
    // 复杂度限制
    complexityLimit({
      estimators: [
        fieldExtensionsEstimator(),
        simpleEstimator({ defaultComplexity: 1 }),
      ],
      createError: (max, actual) => new GraphQLError(`Query complexity limit exceeded: ${actual} > ${max}`),
      onComplete: (complexity: number) => console.log(`Query complexity: ${complexity}`),
    }),
  ],
});

// 创建Next.js处理器
export const handler = startServerAndCreateNextHandler<NextRequest>(server, {
  context: async (req) => {
    // 创建GraphQL上下文
    const context: GraphQLContext = {
      req,
      user: null,
      dataSources: {},
      startTime: Date.now(),
    };

    // 执行中间件链
    await authMiddleware(context);
    await rateLimitMiddleware(context);
    await loggingMiddleware(context);
    await performanceMiddleware(context);

    return context;
  },
});

// GraphQL端点
export async function GET(request: NextRequest) {
  return handler(request);
}

export async function POST(request: NextRequest) {
  return handler(request);
}

// middleware/auth.ts
import jwt from 'jsonwebtoken';
import { GraphQLContext } from '@/types/graphql';
import { prisma } from '@/lib/prisma';

export async function authMiddleware(context: GraphQLContext): Promise<void> {
  const { req } = context;
  const authHeader = req.headers.get('authorization');

  if (!authHeader) {
    context.user = null;
    return;
  }

  try {
    // 提取Bearer Token
    const token = authHeader.replace('Bearer ', '');

    // 验证JWT令牌
    const decoded = jwt.verify(token, process.env.JWT_SECRET!) as any;

    // 从数据库获取用户信息
    const user = await prisma.user.findUnique({
      where: { id: decoded.userId },
      include: {
        roles: true,
        permissions: true,
      },
    });

    if (!user || !user.isActive) {
      context.user = null;
      return;
    }

    // 更新最后活动时间
    await prisma.user.update({
      where: { id: user.id },
      data: { lastActiveAt: new Date() },
    });

    context.user = {
      id: user.id,
      email: user.email,
      roles: user.roles.map(role => role.name),
      permissions: user.permissions.map(perm => perm.name),
    };

  } catch (error) {
    console.error('Authentication error:', error);
    context.user = null;
  }
}

// GraphQL上下文类型定义
export interface GraphQLContext {
  req: NextRequest;
  user: {
    id: string;
    email: string;
    roles: string[];
    permissions: string[];
  } | null;
  dataSources: Record<string, any>;
  startTime: number;
}

// middleware/rate-limit.ts
import { GraphQLContext } from '@/types/graphql';
import { prisma } from '@/lib/prisma';

interface RateLimitConfig {
  windowMs: number;
  max: number;
  keyGenerator?: (context: GraphQLContext) => string;
  skipSuccessfulRequests?: boolean;
  skipFailedRequests?: boolean;
}

const defaultConfig: RateLimitConfig = {
  windowMs: 60 * 1000, // 1分钟
  max: 100, // 最多100个请求
  keyGenerator: (context) => {
    const userId = context.user?.id;
    // NextRequest 无 ip 属性，从代理头取客户端 IP
    const ip = context.req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown';
    return userId ? `user:${userId}` : `ip:${ip}`;
  },
};

export async function rateLimitMiddleware(
  context: GraphQLContext,
  config: Partial<RateLimitConfig> = {}
): Promise<void> {
  const finalConfig = { ...defaultConfig, ...config };
  const key = finalConfig.keyGenerator!(context);
  const now = new Date();

  // 清理过期记录
  const cutoff = new Date(now.getTime() - finalConfig.windowMs);
  await prisma.rateLimit.deleteMany({
    where: {
      key,
      timestamp: { lt: cutoff },
    },
  });

  // 获取当前窗口内的请求计数
  const count = await prisma.rateLimit.count({
    where: {
      key,
      timestamp: { gte: cutoff },
    },
  });

  if (count >= finalConfig.max) {
    throw new GraphQLError('Rate limit exceeded', {
      extensions: {
        code: 'RATE_LIMIT_EXCEEDED',
        retryAfter: Math.ceil(finalConfig.windowMs / 1000),
      },
    });
  }

  // 记录当前请求
  await prisma.rateLimit.create({
    data: {
      key,
      timestamp: now,
    },
  });
}

