import qs from 'qs';

const CMS_URL = process.env.CMS_URL || 'http://localhost:1337';

export interface CmsResponse<T> {
  data: T;
  meta: {
    pagination: {
      page: number;
      pageSize: number;
      pageCount: number;
      total: number;
    };
  };
}

export interface Post {
  id: number;
  attributes: {
    title: string;
    slug: string;
    content: string;
    excerpt: string;
    coverImage?: {
      data: {
        attributes: {
          url: string;
          alternativeText?: string;
        };
      };
    };
    publishedAt: string;
    locale: string;
  };
}

class CmsClient {
  private baseUrl: string;

  constructor(baseUrl: string = CMS_URL) {
    this.baseUrl = baseUrl;
  }

  private async request<T>(endpoint: string, query?: any): Promise<CmsResponse<T>> {
    const url = `${this.baseUrl}/api${endpoint}${query ? `?${qs.stringify(query)}` : ''}`;

    const response = await fetch(url, {
      headers: {
        'Authorization': `Bearer ${process.env.CMS_TOKEN}`,
        'Content-Type': 'application/json',
      },
      next: { revalidate: 3600 }, // 缓存1小时
    });

    if (!response.ok) {
      throw new Error(`CMS request failed: ${response.statusText}`);
    }

    return response.json();
  }

  async getPosts(locale: string = 'en', page: number = 1, pageSize: number = 10) {
    return this.request<Post[]>('/posts', {
      locale,
      populate: ['coverImage'],
      pagination: {
        page,
        pageSize,
      },
      sort: ['publishedAt:desc'],
    });
  }

  async getPost(slug: string, locale: string = 'en') {
    return this.request<Post[]>('/posts', {
      locale,
      filters: { slug },
      populate: ['coverImage'],
    });
  }

  async getPage(slug: string, locale: string = 'en') {
    return this.request('/pages', {
      locale,
      filters: { slug },
      populate: ['components'],
    });
  }
}

export const cmsClient = new CmsClient();

