  params,
}: {
  params: Promise<{ locale: string }>;
}): Promise<Metadata> {
  const { locale } = await params;

  return {
    metadataBase: new URL(process.env.NEXT_PUBLIC_SITE_URL ?? 'https://example.com'),
    title: {
      default: 'Acme Corp',
      template: '%s | Acme Corp',
    },
    description: '全球领先的企业服务提供商',
    alternates: {
      canonical: `/${locale}`,
    },
    openGraph: {
      siteName: 'Acme Corp',
      type: 'website',
    },
  };
}

