import NextAuth, { type NextAuthConfig, type DefaultSession } from 'next-auth'
import { PrismaAdapter } from '@auth/prisma-adapter'
import Google from 'next-auth/providers/google'
import Credentials from 'next-auth/providers/credentials'
import { z } from 'zod'
import { prisma } from '@/lib/db/prisma'
import bcrypt from 'bcryptjs'

declare module 'next-auth' {
  interface User {
    role?: string
  }
  interface Session {
    user: { id?: string; role?: string } & DefaultSession['user']
  }
}

declare module 'next-auth/jwt' {
  interface JWT {
    role?: string
  }
}

const credentialsSchema = z.object({
  email: z.string().email(),
  password: z.string().min(6),
})

export const authConfig: NextAuthConfig = {
  adapter: PrismaAdapter(prisma),
  providers: [
    Google({
      clientId: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
    }),
    Credentials({
      credentials: {
        email: { label: 'Email', type: 'email' },
        password: { label: 'Password', type: 'password' },
      },
      async authorize(credentials) {
        const parsedCredentials = credentialsSchema.safeParse(credentials)

        if (!parsedCredentials.success) {
          return null
        }

        const { email, password } = parsedCredentials.data

        const user = await prisma.user.findUnique({
          where: { email },
        })

        if (!user || !user.password) {
          return null
        }

        const isPasswordValid = await bcrypt.compare(password, user.password)

        if (!isPasswordValid) {
          return null
        }

        return {
          id: user.id,
          email: user.email,
          name: user.name,
          role: user.role,
        }
      },
    }),
  ],
  pages: {
    signIn: '/login',
    signUp: '/register',
    error: '/auth/error',
  },
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.role = user.role
      }
      return token
    },
    async session({ session, token }) {
      if (token.sub) {
        session.user.id = token.sub
      }
      if (token.role) {
        session.user.role = token.role as string
      }
      return session
    },
  },
  session: {
    strategy: 'jwt',
  },
}

// NextAuth v5：实例化并导出路由处理器与会话工具
export const { handlers, auth, signIn, signOut } = NextAuth(authConfig)

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/db/prisma'
import { z } from 'zod'

const productQuerySchema = z.object({
  page: z.string().optional().transform(val => val ? parseInt(val) : 1),
  limit: z.string().optional().transform(val => val ? parseInt(val) : 12),
  category: z.string().optional(),
  search: z.string().optional(),
  sort: z.enum(['name', 'price', 'createdAt']).optional(),
  order: z.enum(['asc', 'desc']).optional(),
  minPrice: z.string().optional().transform(val => val ? parseFloat(val) : undefined),
  maxPrice: z.string().optional().transform(val => val ? parseFloat(val) : undefined),
})

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const query = productQuerySchema.parse(Object.fromEntries(searchParams))

    const where: any = {
      status: 'ACTIVE',
    }

    if (query.category) {
      where.category = {
        slug: query.category,
      }
    }

    if (query.search) {
      where.OR = [
        { name: { contains: query.search, mode: 'insensitive' } },
        { description: { contains: query.search, mode: 'insensitive' } },
      ]
    }

    if (query.minPrice !== undefined || query.maxPrice !== undefined) {
      where.price = {}
      if (query.minPrice !== undefined) {
        where.price.gte = query.minPrice
      }
      if (query.maxPrice !== undefined) {
        where.price.lte = query.maxPrice
      }
    }

    const orderBy: any = {}
    if (query.sort) {
      orderBy[query.sort] = query.order || 'asc'
    } else {
      orderBy.createdAt = 'desc'
    }

    const [products, total] = await Promise.all([
      prisma.product.findMany({
        where,
        include: {
          category: true,
          images: {
            orderBy: { position: 'asc' },
          },
          variants: {
            include: {
              options: true,
            },
          },
          reviews: {
            select: {
              rating: true,
            },
          },
        },
        orderBy,
        skip: (query.page - 1) * query.limit,
        take: query.limit,
      }),
      prisma.product.count({ where }),
    ])

    // 计算平均评分
    const productsWithRating = products.map(product => ({
      ...product,
      averageRating: product.reviews.length > 0
        ? product.reviews.reduce((sum, review) => sum + review.rating, 0) / product.reviews.length
        : 0,
      reviewCount: product.reviews.length,
      reviews: undefined, // 移除原始评论数据
    }))

    return NextResponse.json({
      products: productsWithRating,
      pagination: {
        page: query.page,
        limit: query.limit,
        total,
        pages: Math.ceil(total / query.limit),
      },
    })
  } catch (error) {
    console.error('Products API error:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

const createProductSchema = z.object({
  name: z.string().min(1),
  slug: z.string().min(1),
  description: z.string().optional(),
  price: z.number().positive(),
  comparePrice: z.number().positive().optional(),
  cost: z.number().positive().optional(),
  sku: z.string().min(1),
  categoryId: z.string(),
  trackInventory: z.boolean().default(true),
  images: z.array(z.object({
    url: z.string().url(),
    alt: z.string().optional(),
    position: z.number().default(0),
  })).optional(),
  variants: z.array(z.object({
    name: z.string(),
    sku: z.string(),
    price: z.number().positive(),
    inventory: z.number().default(0),
    options: z.array(z.object({
      name: z.string(),
      value: z.string(),
    })),
  })).optional(),
})

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const validatedData = createProductSchema.parse(body)

    const product = await prisma.product.create({
      data: {
        ...validatedData,
        images: {
          create: validatedData.images || [],
        },
        variants: {
          create: validatedData.variants || [],
        },
      },
      include: {
        category: true,
        images: {
          orderBy: { position: 'asc' },
        },
        variants: {
          include: {
            options: true,
          },
        },
      },
    })

    return NextResponse.json(product, { status: 201 })
  } catch (error) {
    console.error('Create product error:', error)
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid data', details: error.issues },
        { status: 400 }
      )
    }
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

import { prisma } from '@/lib/db/prisma'
import { auth } from '@/lib/auth/config'
import { cookies } from 'next/headers'

export interface CartItem {
  id: string
  productId: string
  productVariantId?: string
  quantity: number
  unitPrice: number
  product: {
    id: string
    name: string
    slug: string
    images: { url: string; alt?: string }[]
  }
  productVariant?: {
    id: string
    name: string
    sku: string
    options: { name: string; value: string }[]
  }
}

export interface Cart {
  id: string
  items: CartItem[]
  subtotal: number
  total: number
}

export async function getCart(): Promise<Cart> {
  const session = await auth()
  const cookieStore = await cookies()
  const cartId = cookieStore.get('cartId')?.value

  let cart

  if (session?.user?.id) {
    // 用户已登录，获取用户购物车
    cart = await prisma.cart.findUnique({
      where: { userId: session.user.id },
      include: {
        items: {
          include: {
            product: {
              include: {
                images: {
                  orderBy: { position: 'asc' },
                  take: 1,
                },
              },
            },
            productVariant: {
              include: {
                options: true,
              },
            },
          },
        },
      },
    })
  } else if (cartId) {
    // 游客用户，获取会话购物车
    cart = await prisma.cart.findUnique({
      where: { sessionId: cartId },
      include: {
        items: {
          include: {
            product: {
              include: {
                images: {
                  orderBy: { position: 'asc' },
                  take: 1,
                },
              },
            },
            productVariant: {
              include: {
                options: true,
              },
            },
          },
        },
      },
    })
  }

  if (!cart) {
    return {
      id: '',
      items: [],
      subtotal: 0,
      total: 0,
    }
  }

  const subtotal = cart.items.reduce(
    (sum, item) => sum + item.unitPrice * item.quantity,
    0
  )

  return {
    id: cart.id,
    items: cart.items.map(item => ({
      ...item,
      product: {
        id: item.product.id,
        name: item.product.name,
        slug: item.product.slug,
        images: item.product.images,
      },
    })),
    subtotal,
    total: subtotal, // 这里可以添加税费和运费计算
  }
}

export async function addToCart(
  productId: string,
  quantity: number,
  productVariantId?: string
): Promise<Cart> {
  const session = await auth()
  const cookieStore = await cookies()
  const cartId = cookieStore.get('cartId')?.value

  // 获取产品信息
  const product = await prisma.product.findUnique({
    where: { id: productId },
    include: {
      variants: true,
    },
  })

  if (!product) {
    throw new Error('Product not found')
  }

  let variant
  if (productVariantId) {
    variant = product.variants.find(v => v.id === productVariantId)
    if (!variant) {
      throw new Error('Product variant not found')
    }
  }

  const unitPrice = variant?.price || product.price

  let cart

  if (session?.user?.id) {
    // 用户已登录
    cart = await prisma.cart.upsert({
      where: { userId: session.user.id },
      update: {},
      create: {
        userId: session.user.id,
      },
      include: {
        items: true,
      },
    })
  } else {
    // 游客用户
    if (!cartId) {
      // 创建新购物车
      const newCart = await prisma.cart.create({
        data: {
          sessionId: crypto.randomUUID(),
          expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 7天后过期
        },
      })

      cookieStore.set('cartId', newCart.sessionId!, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict',
        maxAge: 7 * 24 * 60 * 60, // 7天
      })

      cart = newCart
    } else {
      cart = await prisma.cart.findUnique({
        where: { sessionId: cartId },
        include: { items: true },
      })
    }
  }

  if (!cart) {
    throw new Error('Failed to create or retrieve cart')
  }

  // 检查是否已存在相同的商品
  const existingItem = cart.items.find(
    item =>
      item.productId === productId &&
      item.productVariantId === productVariantId
  )

  if (existingItem) {
    // 更新数量
    await prisma.cartItem.update({
      where: { id: existingItem.id },
      data: {
        quantity: existingItem.quantity + quantity,
      },
    })
  } else {
    // 添加新商品
    await prisma.cartItem.create({
      data: {
        cartId: cart.id,
        productId,
        productVariantId,
        quantity,
        unitPrice,
      },
    })
  }

  return getCart()
}

export async function updateCartItem(
  itemId: string,
  quantity: number
): Promise<Cart> {
  if (quantity <= 0) {
    await prisma.cartItem.delete({
      where: { id: itemId },
    })
  } else {
    await prisma.cartItem.update({
      where: { id: itemId },
      data: { quantity },
    })
  }

  return getCart()
}

export async function removeFromCart(itemId: string): Promise<Cart> {
  await prisma.cartItem.delete({
    where: { id: itemId },
  })

  return getCart()
}

export async function clearCart(): Promise<void> {
  const session = await auth()
  const cookieStore = await cookies()
  const cartId = cookieStore.get('cartId')?.value

  if (session?.user?.id) {
    await prisma.cartItem.deleteMany({
      where: {
        cart: {
          userId: session.user.id,
        },
      },
    })
  } else if (cartId) {
    await prisma.cartItem.deleteMany({
      where: {
        cart: {
          sessionId: cartId,
        },
      },
    })
  }
}

