  productVariantId: z.string().optional(),
})

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { productId, quantity, productVariantId } = addToCartSchema.parse(body)

    const cart = await addToCart(productId, quantity, productVariantId)

    return NextResponse.json(cart)
  } catch (error) {
    console.error('Add to cart error:', error)
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid data', details: error.issues },
        { status: 400 }
      )
    }
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

import Stripe from 'stripe'
import { prisma } from '@/lib/db/prisma'

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2026-08-26.dahlia', // stripe SDK v22 LatestApiVersion
})

export interface CreatePaymentIntentParams {
  orderId: string
  amount: number
  currency?: string
}

export async function createPaymentIntent({
  orderId,
  amount,
  currency = 'usd',
}: CreatePaymentIntentParams) {
  try {
    // 创建支付意图
    const paymentIntent = await stripe.paymentIntents.create({
      amount: Math.round(amount * 100), // Stripe使用分为单位
      currency,
      metadata: {
        orderId,
      },
      automatic_payment_methods: {
        enabled: true,
      },
    })

    // 保存交易记录
    await prisma.paymentTransaction.create({
      data: {
        orderId,
        paymentIntentId: paymentIntent.id,
        amount,
        currency,
        status: 'PENDING',
        paymentMethod: 'stripe',
        provider: 'stripe',
      },
    })

    return {
      clientSecret: paymentIntent.client_secret,
      paymentIntentId: paymentIntent.id,
    }
  } catch (error) {
    console.error('Create payment intent error:', error)
    throw new Error('Failed to create payment intent')
  }
}

export async function confirmPayment(paymentIntentId: string) {
  try {
    const paymentIntent = await stripe.paymentIntents.retrieve(paymentIntentId)

    if (paymentIntent.status === 'succeeded') {
      // 更新交易状态
      await prisma.paymentTransaction.updateMany({
        where: {
          paymentIntentId,
        },
        data: {
          status: 'COMPLETED',
        },
      })

      // 更新订单状态
      const orderId = paymentIntent.metadata.orderId
      if (orderId) {
        await prisma.order.update({
          where: { id: orderId },
          data: {
            status: 'CONFIRMED',
            paymentStatus: 'COMPLETED',
          },
        })
      }
    }

    return paymentIntent
  } catch (error) {
    console.error('Confirm payment error:', error)
    throw new Error('Failed to confirm payment')
  }
}

export async function handleStripeWebhook(
  payload: string,
  signature: string
) {
  let event: Stripe.Event

  try {
    event = stripe.webhooks.constructEvent(
      payload,
      signature,
      process.env.STRIPE_WEBHOOK_SECRET!
    )
  } catch (error) {
    console.error('Webhook signature verification failed:', error)
    throw new Error('Invalid signature')
  }

  switch (event.type) {
    case 'payment_intent.succeeded':
      await handlePaymentSucceeded(event.data.object as Stripe.PaymentIntent)
      break
    case 'payment_intent.payment_failed':
      await handlePaymentFailed(event.data.object as Stripe.PaymentIntent)
      break
    default:
      console.log(`Unhandled event type: ${event.type}`)
  }

  return event
}

async function handlePaymentSucceeded(paymentIntent: Stripe.PaymentIntent) {
  const orderId = paymentIntent.metadata.orderId

  if (!orderId) {
    console.error('No order ID in payment intent metadata')
    return
  }

  await prisma.$transaction(async (tx) => {
    // 更新支付交易状态
    await tx.paymentTransaction.updateMany({
      where: {
        paymentIntentId: paymentIntent.id,
      },
      data: {
        status: 'COMPLETED',
      },
    })

    // 更新订单状态
    await tx.order.update({
      where: { id: orderId },
      data: {
        status: 'CONFIRMED',
        paymentStatus: 'COMPLETED',
      },
    })

    // 减少库存
    const order = await tx.order.findUnique({
      where: { id: orderId },
      include: {
        items: true,
      },
    })

    if (order) {
      for (const item of order.items) {
        if (item.productVariantId) {
          await tx.productVariant.update({
            where: { id: item.productVariantId },
            data: {
              inventory: {
                decrement: item.quantity,
              },
            },
          })
        } else {
          // 如果没有变体，减少主产品库存
          await tx.product.update({
            where: { id: item.productId },
            data: {
              // 这里需要在产品表中添加inventory字段
              // inventory: { decrement: item.quantity },
            },
          })
        }
      }
    }
  })

  // 发送确认邮件（这里需要实现邮件发送逻辑）
  console.log(`Payment succeeded for order: ${orderId}`)
}

async function handlePaymentFailed(paymentIntent: Stripe.PaymentIntent) {
  const orderId = paymentIntent.metadata.orderId

  if (!orderId) {
    console.error('No order ID in payment intent metadata')
    return
  }

  await prisma.$transaction(async (tx) => {
    // 更新支付交易状态
    await tx.paymentTransaction.updateMany({
      where: {
        paymentIntentId: paymentIntent.id,
      },
      data: {
        status: 'FAILED',
      },
    })

    // 更新订单状态
    await tx.order.update({
      where: { id: orderId },
      data: {
        status: 'CANCELLED',
        paymentStatus: 'FAILED',
      },
    })
  })

  // 发送失败通知邮件
  console.log(`Payment failed for order: ${orderId}`)
}

import { NextRequest, NextResponse } from 'next/server'
import { auth } from '@/lib/auth/config'
import { createPaymentIntent } from '@/lib/payments/stripe'
import { prisma } from '@/lib/db/prisma'
import { z } from 'zod'

const createIntentSchema = z.object({
  orderId: z.string(),
})

export async function POST(request: NextRequest) {
  try {
    const session = await auth()
    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    const body = await request.json()
    const { orderId } = createIntentSchema.parse(body)

    // 获取订单信息
    const order = await prisma.order.findUnique({
      where: { id: orderId },
    })

    if (!order) {
      return NextResponse.json(
        { error: 'Order not found' },
        { status: 404 }
      )
    }

    if (order.userId !== session.user.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    if (order.paymentStatus !== 'PENDING') {
      return NextResponse.json(
        { error: 'Order already paid or cancelled' },
        { status: 400 }
      )
    }

    const result = await createPaymentIntent({
      orderId,
      amount: order.total,
      currency: order.currency,
    })

    return NextResponse.json(result)
  } catch (error) {
    console.error('Create payment intent error:', error)
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid data', details: error.issues },
        { status: 400 }
      )
    }
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

import { prisma } from '@/lib/db/prisma'
import { getCart } from '@/lib/cart/cart'
import { clearCart } from '@/lib/cart/cart'

export interface CreateOrderParams {
  email: string
  shippingAddressId: string
  billingAddressId?: string
  paymentMethod: string
  couponCode?: string
}

export async function createOrder({
  email,
  shippingAddressId,
  billingAddressId,
  paymentMethod,
  couponCode,
}: CreateOrderParams) {
  const cart = await getCart()

  if (cart.items.length === 0) {
    throw new Error('Cart is empty')
  }

  // 验证地址
  const shippingAddress = await prisma.address.findUnique({
    where: { id: shippingAddressId },
  })

  if (!shippingAddress) {
    throw new Error('Shipping address not found')
  }

  const billingAddress = billingAddressId
    ? await prisma.address.findUnique({
        where: { id: billingAddressId },
      })
    : shippingAddress

  if (!billingAddress) {
    throw new Error('Billing address not found')
  }

  // 计算订单总额
  const subtotal = cart.subtotal
  let tax = subtotal * 0.08 // 8% 税率
  let shipping = 0
  let discount = 0

  // 应用优惠券
  if (couponCode) {
    const coupon = await prisma.coupon.findUnique({
      where: {
        code: couponCode.toUpperCase(),
        isActive: true,
        OR: [
          { expiresAt: null },
          { expiresAt: { gt: new Date() } },
        ],
      },
    })

    if (coupon) {
      if (coupon.minAmount && subtotal < coupon.minAmount) {
        throw new Error(`Minimum order amount is $${coupon.minAmount}`)
      }

      if (coupon.maxUsage && coupon.usedCount >= coupon.maxUsage) {
        throw new Error('Coupon has reached maximum usage')
      }

      if (coupon.type === 'PERCENTAGE') {
        discount = subtotal * (coupon.value / 100)
      } else {
        discount = Math.min(coupon.value, subtotal)
      }

      // 增加优惠券使用次数
      await prisma.coupon.update({
        where: { id: coupon.id },
        data: {
          usedCount: {
            increment: 1,
          },
        },
      })
    } else {
      throw new Error('Invalid or expired coupon')
    }
  }

  // 计算运费
  if (subtotal < 50) {
    shipping = 10
  }

  const total = subtotal + tax + shipping - discount

  const order = await prisma.$transaction(async (tx) => {
    // 生成订单号
    const orderNumber = generateOrderNumber()

    // 创建订单
    const newOrder = await tx.order.create({
      data: {
        orderNumber,
        email,
        status: 'PENDING',
        paymentStatus: 'PENDING',
        paymentMethod,
        currency: 'USD',
        subtotal,
        tax,
        shipping,
        discount,
        total,
        shippingAddressId: shippingAddress.id,
        billingAddressId: billingAddress.id,
        items: {
          create: cart.items.map(item => ({
            productId: item.productId,
            productVariantId: item.productVariantId,
            quantity: item.quantity,
            unitPrice: item.unitPrice,
            total: item.unitPrice * item.quantity,
          })),
        },
      },
      include: {
        items: {
          include: {
            product: true,
            productVariant: true,
          },
        },
      },
    })

    // 检查库存
    for (const item of cart.items) {
      if (item.productVariantId) {
        const variant = await tx.productVariant.findUnique({
          where: { id: item.productVariantId },
        })

        if (!variant || variant.inventory < item.quantity) {
          throw new Error(`Insufficient inventory for ${item.product.name}`)
        }
      }
    }

    // 预留库存（可选）
    // 这里可以实现库存预留逻辑

    return newOrder
  })

  // 清空购物车
  await clearCart()

  return order
}

function generateOrderNumber(): string {
  const timestamp = Date.now().toString()
  const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0')
  return `ORD-${timestamp.slice(-6)}-${random}`
}

export async function getOrder(orderId: string, userId?: string) {
  const order = await prisma.order.findUnique({
    where: { id: orderId },
    include: {
      items: {
        include: {
          product: {
            include: {
              images: {
                orderBy: { position: 'asc' },
                take: 1,
              },
            },
          },
          productVariant: {
            include: {
              options: true,
            },
          },
        },
      },
      shippingAddress: true,
      billingAddress: true,
      transactions: true,
    },
  })

  if (!order) {
    throw new Error('Order not found')
  }

  if (userId && order.userId !== userId) {
    throw new Error('Unauthorized')
  }

  return order
}

export async function getUserOrders(userId: string, page = 1, limit = 10) {
  const skip = (page - 1) * limit

  const [orders, total] = await Promise.all([
    prisma.order.findMany({
      where: { userId },
      include: {
        items: {
          include: {
            product: {
              include: {
                images: {
                  orderBy: { position: 'asc' },
                  take: 1,
                },
              },
            },
          },
        },
      },
      orderBy: { createdAt: 'desc' },
      skip,
      take: limit,
    }),
    prisma.order.count({
      where: { userId },
    }),
  ])

  return {
    orders,
    pagination: {
      page,
      limit,
      total,
      pages: Math.ceil(total / limit),
    },
  }
}

import { prisma } from '@/lib/db/prisma'

export interface SearchParams {
  query: string
  category?: string
  minPrice?: number
  maxPrice?: number
  sortBy?: 'name' | 'price' | 'rating' | 'createdAt'
  sortOrder?: 'asc' | 'desc'
  page?: number
  limit?: number
}

export interface SearchResult {
  products: any[]
  categories: any[]
  pagination: {
    page: number
    limit: number
    total: number
    pages: number
  }
}

export async function searchProducts(params: SearchParams): Promise<SearchResult> {
  const {
    query,
    category,
    minPrice,
    maxPrice,
    sortBy = 'createdAt',
    sortOrder = 'desc',
    page = 1,
    limit = 12,
  } = params

  const skip = (page - 1) * limit

  // 构建搜索条件
  const where: any = {
    status: 'ACTIVE',
  }

  if (query) {
    where.OR = [
      { name: { contains: query, mode: 'insensitive' } },
      { description: { contains: query, mode: 'insensitive' } },
      { sku: { contains: query, mode: 'insensitive' } },
      {
        tags: {
          some: {
            tag: {
              name: { contains: query, mode: 'insensitive' },
            },
          },
        },
      },
    ]
  }

  if (category) {
    where.category = {
      slug: category,
    }
  }

  if (minPrice !== undefined || maxPrice !== undefined) {
    where.price = {}
    if (minPrice !== undefined) {
      where.price.gte = minPrice
    }
    if (maxPrice !== undefined) {
      where.price.lte = maxPrice
    }
  }

  // 构建排序条件
  const orderBy: any = {}
  if (sortBy === 'rating') {
    // 按评分排序需要特殊处理
    orderBy.reviews = {
      _avg: {
        rating: sortOrder,
      },
    }
  } else {
    orderBy[sortBy] = sortOrder
  }

  const [products, total, categories] = await Promise.all([
    prisma.product.findMany({
      where,
      include: {
        category: true,
        images: {
          orderBy: { position: 'asc' },
          take: 1,
        },
        variants: {
          include: {
            options: true,
          },
        },
        reviews: {
          select: {
            rating: true,
          },
        },
        _count: {
          select: {
            reviews: true,
          },
        },
      },
      orderBy,
      skip,
      take: limit,
    }),
    prisma.product.count({ where }),
    // 获取相关分类
    prisma.category.findMany({
      where: {
        products: {
          some: where,
        },
      },
      include: {
        _count: {
          select: {
            products: {
              where,
            },
          },
        },
      },
      orderBy: {
        name: 'asc',
      },
    }),
  ])

  // 处理产品数据
  const processedProducts = products.map(product => ({
    ...product,
    averageRating: product.reviews.length > 0
      ? product.reviews.reduce((sum, review) => sum + review.rating, 0) / product.reviews.length
      : 0,
    reviewCount: product._count.reviews,
    reviews: undefined,
    _count: undefined,
  }))

  return {
    products: processedProducts,
    categories: categories.map(category => ({
      ...category,
      productCount: category._count.products,
      _count: undefined,
    })),
    pagination: {
      page,
      limit,
      total,
      pages: Math.ceil(total / limit),
    },
  }
}

export async function getSuggestions(query: string, limit = 5) {
  if (!query || query.length < 2) {
    return { products: [], categories: [] }
  }

  const [products, categories] = await Promise.all([
    prisma.product.findMany({
      where: {
        status: 'ACTIVE',
        name: {
          contains: query,
          mode: 'insensitive',
        },
      },
      select: {
        id: true,
        name: true,
        slug: true,
        images: {
          select: {
            url: true,
          },
          orderBy: { position: 'asc' },
          take: 1,
        },
      },
      take: limit,
    }),
    prisma.category.findMany({
      where: {
        name: {
          contains: query,
          mode: 'insensitive',
        },
      },
      select: {
        id: true,
        name: true,
        slug: true,
        image: true,
      },
      take: Math.floor(limit / 2),
    }),
  ])

  return { products, categories }
}

import { prisma } from '@/lib/db/prisma'

export interface RecommendationParams {
  userId?: string
  productId?: string
  categoryIds?: string[]
  limit?: number
}

export async function getRecommendations({
  userId,
  productId,
  categoryIds,
  limit = 10,
}: RecommendationParams) {
  const recommendations = []

  // 基于用户行为的推荐
  if (userId) {
    const userRecommendations = await getUserBasedRecommendations(userId, limit)
    recommendations.push(...userRecommendations)
  }

  // 基于商品的协同过滤推荐
  if (productId) {
    const collaborativeRecommendations = await getCollaborativeRecommendations(productId, limit)
    recommendations.push(...collaborativeRecommendations)
  }

  // 基于分类的推荐
  if (categoryIds && categoryIds.length > 0) {
    const categoryRecommendations = await getCategoryBasedRecommendations(categoryIds, limit)
    recommendations.push(...categoryRecommendations)
  }

  // 热门商品推荐
  if (recommendations.length < limit) {
    const popularProducts = await getPopularProducts(limit - recommendations.length)
    recommendations.push(...popularProducts)
  }

  // 去重并限制数量
  const uniqueRecommendations = recommendations
    .filter((product, index, self) =>
      self.findIndex(p => p.id === product.id) === index
    )
    .slice(0, limit)

  return uniqueRecommendations
}

async function getUserBasedRecommendations(userId: string, limit: number) {
  // 获取用户购买历史
  const userOrders = await prisma.order.findMany({
    where: { userId },
    include: {
      items: {
        include: {
          product: {
            include: {
              category: true,
            },
          },
        },
      },
    },
  })

  // 提取用户偏好的分类
  const categoryPreferences = userOrders.flatMap(order =>
    order.items.map(item => item.product.categoryId)
  )

  const uniqueCategoryIds = [...new Set(categoryPreferences)]

  // 获取这些分类中的其他商品
  const recommendations = await prisma.product.findMany({
    where: {
      categoryId: { in: uniqueCategoryIds },
      status: 'ACTIVE',
      // 排除已购买的商品
      id: {
        notIn: userOrders.flatMap(order =>
          order.items.map(item => item.productId)
        ),
      },
    },
    include: {
      category: true,
      images: {
        orderBy: { position: 'asc' },
        take: 1,
      },
      reviews: {
        select: { rating: true },
      },
      _count: {
        select: { reviews: true },
      },
    },
    orderBy: [
      { reviews: { _avg: { rating: 'desc' } } },
      { _count: { reviews: 'desc' } },
    ],
    take: limit,
  })

  return recommendations.map(product => ({
    ...product,
    averageRating: product.reviews.length > 0
      ? product.reviews.reduce((sum, review) => sum + review.rating, 0) / product.reviews.length
      : 0,
    reviewCount: product._count.reviews,
    reviews: undefined,
    _count: undefined,
  }))
}

async function getCollaborativeRecommendations(productId: string, limit: number) {
  // 找到购买过此商品的用户还购买了哪些其他商品
  const relatedProducts = await prisma.orderItem.findMany({
    where: {
      productId,
    },
    include: {
      order: {
        include: {
          items: {
            include: {
              product: {
                include: {
                  category: true,
                  images: {
                    orderBy: { position: 'asc' },
                    take: 1,
                  },
                  reviews: {
                    select: { rating: true },
                  },
                  _count: {
                    select: { reviews: true },
                  },
                },
              },
            },
          },
        },
      },
    },
  })

  // 统计其他商品的购买次数
  const productFrequency = new Map<string, number>()

  relatedProducts.forEach(orderItem => {
    orderItem.order.items.forEach(item => {
      if (item.productId !== productId) {
        const current = productFrequency.get(item.productId) || 0
        productFrequency.set(item.productId, current + 1)
      }
    })
  })

  // 获取最频繁购买的商品
  const sortedProductIds = Array.from(productFrequency.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([productId]) => productId)

  if (sortedProductIds.length === 0) {
    return []
  }

  const recommendations = await prisma.product.findMany({
    where: {
      id: { in: sortedProductIds },
      status: 'ACTIVE',
    },
    include: {
      category: true,
      images: {
        orderBy: { position: 'asc' },
        take: 1,
      },
      reviews: {
        select: { rating: true },
      },
      _count: {
        select: { reviews: true },
      },
    },
  })

  // 按照购买频率排序
  const productOrder = new Map(sortedProductIds.map((id, index) => [id, index]))

  return recommendations
    .sort((a, b) => (productOrder.get(a.id) || 0) - (productOrder.get(b.id) || 0))
    .map(product => ({
      ...product,
      averageRating: product.reviews.length > 0
        ? product.reviews.reduce((sum, review) => sum + review.rating, 0) / product.reviews.length
        : 0,
      reviewCount: product._count.reviews,
      reviews: undefined,
      _count: undefined,
    }))
}

async function getCategoryBasedRecommendations(categoryIds: string[], limit: number) {
  const recommendations = await prisma.product.findMany({
    where: {
      categoryId: { in: categoryIds },
      status: 'ACTIVE',
    },
    include: {
      category: true,
      images: {
        orderBy: { position: 'asc' },
        take: 1,
      },
      reviews: {
        select: { rating: true },
      },
      _count: {
        select: { reviews: true },
      },
    },
    orderBy: [
      { reviews: { _avg: { rating: 'desc' } } },
      { _count: { reviews: 'desc' } },
    ],
    take: limit,
  })

  return recommendations.map(product => ({
    ...product,
    averageRating: product.reviews.length > 0
      ? product.reviews.reduce((sum, review) => sum + review.rating, 0) / product.reviews.length
      : 0,
    reviewCount: product._count.reviews,
    reviews: undefined,
    _count: undefined,
  }))
}

async function getPopularProducts(limit: number) {
  const recommendations = await prisma.product.findMany({
    where: {
      status: 'ACTIVE',
    },
    include: {
      category: true,
      images: {
        orderBy: { position: 'asc' },
        take: 1,
      },
      reviews: {
        select: { rating: true },
      },
      _count: {
        select: { reviews: true, orderItems: true },
      },
    },
    orderBy: [
      { _count: { orderItems: 'desc' } },
      { reviews: { _avg: { rating: 'desc' } } },
    ],
    take: limit,
  })

  return recommendations.map(product => ({
    ...product,
    averageRating: product.reviews.length > 0
      ? product.reviews.reduce((sum, review) => sum + review.rating, 0) / product.reviews.length
      : 0,
    reviewCount: product._count.reviews,
    reviews: undefined,
    _count: undefined,
  }))
}

import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
