import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js'
import { Pie } from 'react-chartjs-2'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { LoadingSpinner } from '@/components/ui/loading-spinner'

ChartJS.register(ArcElement, Tooltip, Legend)

interface PieChartProps {
  data: {
    labels: string[]
    datasets: Array<{
      data: number[]
      backgroundColor?: string[]
      borderColor?: string[]
      borderWidth?: number
    }>
  }
  title?: string
  height?: number
  isLoading?: boolean
  showLegend?: boolean
  showLabels?: boolean
}

export function PieChart({
  data,
  title,
  height = 300,
  isLoading = false,
  showLegend = true,
  showLabels = true,
}: PieChartProps) {
  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: showLegend,
        position: 'right' as const,
        labels: {
          usePointStyle: true,
          padding: 20,
          generateLabels: (chart: any) => {
            const data = chart.data
            if (data.labels.length && data.datasets.length) {
              const dataset = data.datasets[0]
              const total = dataset.data.reduce((a: number, b: number) => a + b, 0)

              return data.labels.map((label: string, i: number) => {
                const value = dataset.data[i]
                const percentage = ((value / total) * 100).toFixed(1)

                return {
                  text: `${label} (${percentage}%)`,
                  fillStyle: dataset.backgroundColor[i],
                  hidden: false,
                  index: i,
                }
              })
            }
            return []
          },
        },
      },
      tooltip: {
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        titleColor: '#fff',
        bodyColor: '#fff',
        borderColor: '#333',
        borderWidth: 1,
        padding: 12,
        callbacks: {
          label: (context: any) => {
            const label = context.label || ''
            const value = context.parsed
            const total = context.dataset.data.reduce((a: number, b: number) => a + b, 0)
            const percentage = ((value / total) * 100).toFixed(1)

            return `${label}: ${value.toLocaleString()} (${percentage}%)`
          },
        },
      },
    },
    animation: {
      animateRotate: true,
      animateScale: false,
      duration: 750,
      easing: 'easeInOutQuart' as const,
    },
  }

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>{title}</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center h-[300px]">
            <LoadingSpinner />
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card>
      {(title || showLegend) && (
        <CardHeader>
          {title && <CardTitle>{title}</CardTitle>}
        </CardHeader>
      )}
      <CardContent>
        <div style={{ height }}>
          <Pie data={data} options={options} />
        </div>
      </CardContent>
    </Card>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { io, Socket } from 'socket.io-client'
import { useSession } from 'next-auth/react'

interface UseSocketOptions {
  autoConnect?: boolean
  reconnection?: boolean
  reconnectionDelay?: number
  reconnectionAttempts?: number
}

export function useSocket(options: UseSocketOptions = {}) {
  const {
    autoConnect = true,
    reconnection = true,
    reconnectionDelay = 1000,
    reconnectionAttempts = 5,
  } = options

  const { data: session } = useSession()
  const [isConnected, setIsConnected] = useState(false)
  const [connectionError, setConnectionError] = useState<string | null>(null)
  const socketRef = useRef<Socket | null>(null)

  useEffect(() => {
    if (!session?.user) return

    const socket = io(process.env.NEXT_PUBLIC_SOCKET_URL || 'ws://localhost:3001', {
      auth: {
        token: session.user.id,
      },
      reconnection,
      reconnectionDelay,
      reconnectionAttempts,
    })

    socketRef.current = socket

    socket.on('connect', () => {
      setIsConnected(true)
      setConnectionError(null)
      console.log('Socket connected')
    })

    socket.on('disconnect', (reason) => {
      setIsConnected(false)
      console.log('Socket disconnected:', reason)
    })

    socket.on('connect_error', (error) => {
      setConnectionError(error.message)
      console.error('Socket connection error:', error)
    })

    socket.on('reconnect', (attemptNumber) => {
      console.log('Socket reconnected after', attemptNumber, 'attempts')
    })

    socket.on('reconnect_failed', () => {
      setConnectionError('Failed to reconnect to server')
      console.error('Socket reconnection failed')
    })

    if (!autoConnect) {
      socket.disconnect()
    }

    return () => {
      socket.disconnect()
      socketRef.current = null
    }
  }, [session, autoConnect, reconnection, reconnectionDelay, reconnectionAttempts])

  const connect = () => {
    if (socketRef.current && !socketRef.current.connected) {
      socketRef.current.connect()
    }
  }

  const disconnect = () => {
    if (socketRef.current) {
      socketRef.current.disconnect()
    }
  }

  const emit = (event: string, data: any) => {
    if (socketRef.current?.connected) {
      socketRef.current.emit(event, data)
    } else {
      console.warn('Socket not connected, cannot emit event:', event)
    }
  }

  const subscribe = (event: string, callback: (data: any) => void) => {
    if (socketRef.current) {
      socketRef.current.on(event, callback)
    }

    return () => {
      if (socketRef.current) {
        socketRef.current.off(event, callback)
      }
    }
  }

  return {
    socket: socketRef.current,
    isConnected,
    connectionError,
    connect,
    disconnect,
    emit,
    subscribe,
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useSocket } from './useSocket'
import { DataPoint } from '@/types/analytics'

interface UseRealTimeDataOptions {
  metricId: string
  timeRange?: {
    start: Date
    end: Date
  }
  updateInterval?: number
  maxDataPoints?: number
}

export function useRealTimeData({
  metricId,
  timeRange,
  updateInterval = 5000,
  maxDataPoints = 100,
}: UseRealTimeDataOptions) {
  const [data, setData] = useState<DataPoint[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [lastUpdate, setLastUpdate] = useState<Date | null>(null)

  const { socket, isConnected, subscribe } = useSocket()

  // 处理新数据点
  const handleNewDataPoint = useCallback((newDataPoint: DataPoint) => {
    setData(prevData => {
      const updatedData = [...prevData, newDataPoint]

      // 应用时间范围过滤
      if (timeRange) {
        return updatedData.filter(
          point => point.timestamp >= timeRange.start && point.timestamp <= timeRange.end
        )
      }

      // 限制数据点数量
      if (maxDataPoints && updatedData.length > maxDataPoints) {
        return updatedData.slice(-maxDataPoints)
      }

      return updatedData
    })

    setLastUpdate(new Date())
    setIsLoading(false)
    setError(null)
  }, [timeRange, maxDataPoints])

  // 处理批量数据更新
  const handleBatchUpdate = useCallback((batchData: DataPoint[]) => {
    setData(prevData => {
      let updatedData = [...prevData, ...batchData]

      // 去重（基于时间戳）
      const uniqueData = updatedData.filter((point, index, self) =>
        index === self.findIndex(p => p.timestamp.getTime() === point.timestamp.getTime())
      )

      // 按时间排序
      uniqueData.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime())

      // 应用时间范围过滤
      if (timeRange) {
        uniqueData = uniqueData.filter(
          point => point.timestamp >= timeRange.start && point.timestamp <= timeRange.end
        )
      }

      // 限制数据点数量
      if (maxDataPoints && uniqueData.length > maxDataPoints) {
        return uniqueData.slice(-maxDataPoints)
      }

      return uniqueData
    })

    setLastUpdate(new Date())
    setIsLoading(false)
    setError(null)
  }, [timeRange, maxDataPoints])

  // 请求历史数据
  const fetchHistoricalData = useCallback(async () => {
    if (!metricId) return

    try {
      setIsLoading(true)
      setError(null)

      const response = await fetch(`/api/analytics/metrics/${metricId}/data`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          timeRange,
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to fetch historical data')
      }

      const historicalData: DataPoint[] = await response.json()
      setData(historicalData)
      setLastUpdate(new Date())
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error')
    } finally {
      setIsLoading(false)
    }
  }, [metricId, timeRange])

  // 订阅实时数据更新
  useEffect(() => {
    if (!isConnected || !metricId) return

    const unsubscribeNewData = subscribe(`metric:${metricId}:new`, handleNewDataPoint)
    const unsubscribeBatchUpdate = subscribe(`metric:${metricId}:batch`, handleBatchUpdate)

    return () => {
      unsubscribeNewData()
      unsubscribeBatchUpdate()
    }
  }, [isConnected, metricId, subscribe, handleNewDataPoint, handleBatchUpdate])

  // 初始化时获取历史数据
  useEffect(() => {
    fetchHistoricalData()
  }, [fetchHistoricalData])

  // 手动刷新数据
  const refresh = useCallback(() => {
    fetchHistoricalData()
  }, [fetchHistoricalData])

  // 清除数据
  const clear = useCallback(() => {
    setData([])
    setLastUpdate(null)
    setError(null)
  }, [])

  return {
    data,
    isLoading,
    error,
    lastUpdate,
    isConnected,
    refresh,
    clear,
  }
}

