import { css } from '@/styles/emotion';
import styled from '@emotion/styled';

interface ButtonProps {
  variant?: 'primary' | 'secondary' | 'outline';
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
  children: React.ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  className?: string;
}

const StyledButton = styled.button<ButtonProps>`
  /* 基础样式 */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border-radius: var(--radius);
  font-weight: 500;
  transition: all 0.2s ease-in-out;
  cursor: pointer;
  outline: none;
  border: 2px solid transparent;

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  &:focus-visible {
    outline: 2px solid hsl(var(--ring));
    outline-offset: 2px;
  }

  /* 变体样式 */
  ${({ variant = 'primary' }) => {
    switch (variant) {
      case 'primary':
        return css`
          background-color: hsl(var(--primary));
          color: hsl(var(--primary-foreground));

          &:hover:not(:disabled) {
            background-color: hsl(217.2 91.2% 59.8%);
          }

          &:active:not(:disabled) {
            background-color: hsl(217.2 91.2% 54.1%);
          }
        `;

      case 'secondary':
        return css`
          background-color: hsl(var(--secondary));
          color: hsl(var(--secondary-foreground));

          &:hover:not(:disabled) {
            background-color: hsl(215.4 16.3% 46.9%);
          }
        `;

      case 'outline':
        return css`
          background-color: transparent;
          color: hsl(var(--foreground));
          border-color: hsl(var(--border));

          &:hover:not(:disabled) {
            background-color: hsl(var(--accent));
          }
        `;

      default:
        return '';
    }
  }}

  /* 尺寸样式 */
  ${({ size = 'md' }) => {
    switch (size) {
      case 'sm':
        return css`
          height: 2.25rem;
          padding: 0 1rem;
          font-size: 0.875rem;
        `;

      case 'md':
        return css`
          height: 2.5rem;
          padding: 0 1.5rem;
          font-size: 0.875rem;
        `;

      case 'lg':
        return css`
          height: 2.75rem;
          padding: 0 2rem;
          font-size: 1rem;
        `;

      default:
        return '';
    }
  }}

  /* 全宽样式 */
  ${({ fullWidth = false }) =>
    fullWidth &&
    css`
      width: 100%;
    `}

  /* 自定义类名 */
  ${({ className }) => className}
`;

// 加载动画组件
