  line-height: 1.25rem;
}

.button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.button:focus-visible {
  outline: 2px solid hsl(var(--ring));
  outline-offset: 2px;
}

/* 变体 */
.primary {
  background-color: hsl(var(--primary));
  color: hsl(var(--primary-foreground));
}

.primary:hover:not(:disabled) {
  background-color: hsl(217.2 91.2% 59.8%);
}

.primary:active:not(:disabled) {
  background-color: hsl(217.2 91.2% 54.1%);
}

.secondary {
  background-color: hsl(var(--secondary));
  color: hsl(var(--secondary-foreground));
}

.secondary:hover:not(:disabled) {
  background-color: hsl(215.4 16.3% 46.9%);
}

.outline {
  background-color: transparent;
  color: hsl(var(--foreground));
  border-color: hsl(var(--border));
}

.outline:hover:not(:disabled) {
  background-color: hsl(var(--accent));
}

/* 尺寸 */
.sm {
  height: 2.25rem;
  padding: 0 1rem;
  font-size: 0.875rem;
}

.md {
  height: 2.5rem;
  padding: 0 1.5rem;
  font-size: 0.875rem;
}

.lg {
  height: 2.75rem;
  padding: 0 2rem;
  font-size: 1rem;
}

/* 全宽 */
.fullWidth {
  width: 100%;
}

/* 加载动画 */
.loading {
  position: relative;
}

.loading::after {
  content: '';
  position: absolute;
  width: 1rem;
  height: 1rem;
  border: 2px solid transparent;
  border-top-color: currentColor;
  border-radius: 50%;
  animation: spin 1s linear infinite;
  top: 50%;
  left: 50%;
  margin-left: -0.5rem;
  margin-top: -0.5rem;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* 响应式 */
@media (max-width: 640px) {
  .button {
    width: 100%;
  }
}

// src/components/Button/Button.tsx
import React from 'react';
import styles from './Button.module.css';

interface ButtonProps {
  variant?: 'primary' | 'secondary' | 'outline';
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
  loading?: boolean;
  children: React.ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  className?: string;
}

export const Button: React.FC<ButtonProps> = ({
  variant = 'primary',
  size = 'md',
  fullWidth = false,
  loading = false,
  children,
  onClick,
  disabled = false,
  className = ''
}) => {
  const classNames = [
    styles.button,
    styles[variant],
    styles[size],
    fullWidth && styles.fullWidth,
    loading && styles.loading,
    className
  ].filter(Boolean).join(' ');

  return (
    <button
      className={classNames}
      onClick={onClick}
      disabled={disabled || loading}
      type="button"
    >
      {children}
    </button>
  );
};

// src/styles/breakpoints.ts
export const breakpoints = {
  xs: '475px',
  sm: '640px',
  md: '768px',
  lg: '1024px',
  xl: '1280px',
  '2xl': '1536px',
} as const;

export type Breakpoint = keyof typeof breakpoints;

export const mediaQueries = {
  xs: `@media (min-width: ${breakpoints.xs})`,
  sm: `@media (min-width: ${breakpoints.sm})`,
  md: `@media (min-width: ${breakpoints.md})`,
  lg: `@media (min-width: ${breakpoints.lg})`,
  xl: `@media (min-width: ${breakpoints.xl})`,
  '2xl': `@media (min-width: ${breakpoints['2xl']})`,

  // 最大宽度查询
  'max-xs': `@media (max-width: ${breakpoints.xs})`,
  'max-sm': `@media (max-width: ${breakpoints.sm})`,
  'max-md': `@media (max-width: ${breakpoints.md})`,
  'max-lg': `@media (max-width: ${breakpoints.lg})`,
  'max-xl': `@media (max-width: ${breakpoints.xl})`,

  // 范围查询
  'sm-only': `@media (min-width: ${breakpoints.sm}) and (max-width: ${breakpoints.md})`,
  'md-only': `@media (min-width: ${breakpoints.md}) and (max-width: ${breakpoints.lg})`,
  'lg-only': `@media (min-width: ${breakpoints.lg}) and (max-width: ${breakpoints.xl})`,
} as const;

// 响应式Hook
export const useBreakpoint = (breakpoint: Breakpoint) => {
  const [matches, setMatches] = React.useState(false);

  React.useEffect(() => {
    const media = window.matchMedia(`(min-width: ${breakpoints[breakpoint]})`);
    setMatches(media.matches);

    const handler = (event: MediaQueryListEvent) => {
      setMatches(event.matches);
    };

    media.addEventListener('change', handler);
    return () => media.removeEventListener('change', handler);
  }, [breakpoint]);

  return matches;
};

// src/components/Grid/Grid.tsx
import React from 'react';
import styled from '@emotion/styled';
import { mediaQueries } from '@/styles/breakpoints';

interface GridProps {
  columns?: number | ResponsiveColumns;
  gap?: string | ResponsiveGap;
  children: React.ReactNode;
  className?: string;
}

interface ResponsiveColumns {
  xs?: number;
  sm?: number;
  md?: number;
  lg?: number;
  xl?: number;
  '2xl'?: number;
}

interface ResponsiveGap {
  xs?: string;
  sm?: string;
  md?: string;
  lg?: string;
  xl?: string;
  '2xl'?: string;
}

const StyledGrid = styled.div<GridProps>`
  display: grid;

  /* 列数配置 */
  ${({ columns = 1 }) => {
    if (typeof columns === 'number') {
      return `grid-template-columns: repeat(${columns}, 1fr);`;
    }

    let cssString = '';

    if (columns.xs) {
      cssString += `grid-template-columns: repeat(${columns.xs}, 1fr);`;
    }

    if (columns.sm) {
      cssString += `${mediaQueries.sm} { grid-template-columns: repeat(${columns.sm}, 1fr); }`;
    }

    if (columns.md) {
      cssString += `${mediaQueries.md} { grid-template-columns: repeat(${columns.md}, 1fr); }`;
    }

    if (columns.lg) {
      cssString += `${mediaQueries.lg} { grid-template-columns: repeat(${columns.lg}, 1fr); }`;
    }

    if (columns.xl) {
      cssString += `${mediaQueries.xl} { grid-template-columns: repeat(${columns.xl}, 1fr); }`;
    }

    if (columns['2xl']) {
      cssString += `${mediaQueries['2xl']} { grid-template-columns: repeat(${columns['2xl']}, 1fr); }`;
    }

    return cssString;
  }}

  /* 间距配置 */
  ${({ gap = '1rem' }) => {
    if (typeof gap === 'string') {
      return `gap: ${gap};`;
    }

    let cssString = '';

    if (gap.xs) {
      cssString += `gap: ${gap.xs};`;
    }

    if (gap.sm) {
      cssString += `${mediaQueries.sm} { gap: ${gap.sm}; }`;
    }

    if (gap.md) {
      cssString += `${mediaQueries.md} { gap: ${gap.md}; }`;
    }

    if (gap.lg) {
      cssString += `${mediaQueries.lg} { gap: ${gap.lg}; }`;
    }

    if (gap.xl) {
      cssString += `${mediaQueries.xl} { gap: ${gap.xl}; }`;
    }

    if (gap['2xl']) {
      cssString += `${mediaQueries['2xl']} { gap: ${gap['2xl']}; }`;
    }

    return cssString;
  }}

  /* 自定义类名 */
  ${({ className }) => className}
`;

export const Grid: React.FC<GridProps> = ({
  columns = 1,
  gap = '1rem',
  children,
  className,
  ...props
}) => {
  return (
    <StyledGrid
      columns={columns}
      gap={gap}
      className={className}
      {...props}
    >
      {children}
    </StyledGrid>
  );
};

