    'src/styles/main.css',
  ],
  bundle: true,
  sourcemap: !isProduction,
  target: ['es2020', 'chrome58', 'firefox57', 'safari11'],
  format: 'esm',
  mainFields: ['browser', 'module', 'main'],
  conditions: ['browser', 'default'],
  outdir: 'dist',
  loader: {
    '.tsx': 'tsx',
    '.ts': 'ts',
    '.jsx': 'jsx',
    '.js': 'js',
    '.json': 'json',
