  },
  define: {
    'process.env.NODE_ENV': `"${isProduction ? 'production' : 'development'}"`,
    'process.env.VERSION': `"${process.env.npm_package_version}"`,
  },
  external: [
    'react',
    'react-dom',
    // 排除 Node.js 内置模块
