interface LazyLoadProps {
  component: () => Promise<React.ComponentType<any>>;
  fallback?: React.ReactNode;
  ssr?: boolean;
  [key: string]: any;
}

export function LazyLoad({
  component,
  fallback = <LoadingSpinner />,
  ssr = false,
  ...props
}: LazyLoadProps) {
