import React, { useMemo, useCallback } from 'react';

interface UseMemoizedComponentProps<T, P> {
  component: React.ComponentType<T>;
  props: T;
  memoProps?: (prev: P, next: P) => boolean;
  deps?: any[];
}

export function useMemoizedComponent<T, P = {}>({
  component: Component,
  props,
  memoProps,
  deps = [],
}: UseMemoizedComponentProps<T, P>) {
  return useMemo(() => {
    const MemoizedComponent = React.memo(Component, memoProps);
    return <MemoizedComponent {...props} />;
  }, [Component, props, memoProps, ...deps]);
}

// 虚拟列表优化
// components/lists/VirtualizedList.tsx
import { useMemo, useState, useEffect, useRef } from 'react';

interface VirtualizedListProps<T> {
  items: T[];
  itemHeight: number;
  containerHeight: number;
  renderItem: (item: T, index: number) => React.ReactNode;
  overscan?: number;
}

export function VirtualizedList<T>({
  items,
  itemHeight,
  containerHeight,
  renderItem,
  overscan = 5,
}: VirtualizedListProps<T>) {
  const [scrollTop, setScrollTop] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  const visibleItems = useMemo(() => {
    const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - overscan);
    const endIndex = Math.min(
      items.length - 1,
      Math.ceil((scrollTop + containerHeight) / itemHeight) + overscan
    );

    return items.slice(startIndex, endIndex + 1).map((item, index) => ({
      item,
      index: startIndex + index,
      style: {
        position: 'absolute',
        top: (startIndex + index) * itemHeight,
        left: 0,
        right: 0,
        height: itemHeight,
      },
    }));
  }, [items, itemHeight, containerHeight, scrollTop, overscan]);

  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  const totalHeight = items.length * itemHeight;

  return (
    <div
      ref={containerRef}
      style={{
        height: containerHeight,
        overflow: 'auto',
        position: 'relative',
      }}
      onScroll={handleScroll}
    >
      <div style={{ height: totalHeight, position: 'relative' }}>
        {visibleItems.map(({ item, index, style }) => (
          <div key={index} style={style}>
            {renderItem(item, index)}
          </div>
        ))}
      </div>
    </div>
  );
}

// hooks/useOptimizedState.ts
import { useState, useCallback, useMemo } from 'react';

interface StateUpdater<T> {
  (updater: T | ((prev: T) => T)): void;
}

export function useOptimizedState<T>(
  initialState: T,
  areEqual?: (prev: T, next: T) => boolean
): [T, StateUpdater<T>] {
  const [state, setState] = useState(initialState);

  const setStateOptimized = useCallback(
    (updater: T | ((prev: T) => T)) => {
      setState((prevState) => {
        const newState = typeof updater === 'function' ? updater(prevState) : updater;

        if (areEqual && areEqual(prevState, newState)) {
          return prevState;
        }

        return newState;
      });
    },
    [areEqual]
  );

  return [state, setStateOptimized];
}

// 选择器优化
export function useSelector<T, R>(
  state: T,
  selector: (state: T) => R,
  equalityFn?: (a: R, b: R) => boolean
): R {
  return useMemo(() => {
    const selected = selector(state);
    return selected;
  }, [state, selector, equalityFn]);
}

