// 条件类型在函数中的应用
function processValue<T>(value: T): T extends string
  ? string
  : T extends number
    ? number
    : any {
  if (typeof value === "string") {
    return value.toUpperCase() as any
  }
  if (typeof value === "number") {
    return value * 2 as any
  }
  return value
}

