  return (
    <button
      style={{
        background: 'var(--color-primary)',
        color: 'var(--color-text)',
        borderRadius: 'var(--border-radius)',
        transition: 'var(--transition)',
        padding: '0.5rem 1rem',
        border: 'none',
        cursor: 'pointer'
      }}
      onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
      {...props}
    >
      {children}
    </button>
  )
}

