  prevState: { ok: boolean; message: string },
  formData: FormData,
): Promise<{ ok: boolean; message: string }> {
  const email = String(formData.get('email') ?? '')
  if (!email.includes('@')) {
    return { ok: false, message: '邮箱格式不正确' }
  }
  await saveSubscriber(email) // 写库等真实副作用
  return { ok: true, message: '订阅成功' }
}

