'use client';

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { ClientComponentProps } from '@/types/client-component';

interface BasicClientComponentState {
  count: number;
  isVisible: boolean;
  data: any[] | null;
  error: string | null;
}

export const BasicClientComponent: React.FC<
  ClientComponentProps<BasicClientComponentState>
> = ({
  id,
  className = '',
  children,
  initialState,
  onStateChange,
  onLoad,
  onError
}) => {
  // 状态管理
  const [state, setState] = useState<BasicClientComponentState>(
    initialState || {
      count: 0,
      isVisible: false,
      data: null,
      error: null
    }
  );

  // 副作用管理
  useEffect(() => {
    // 组件挂载时执行
    onLoad?.();

    return () => {
      // 清理函数
      console.log('Component unmounted');
    };
  }, [onLoad]);

  // 状态更新回调
  const updateState = useCallback((
    updates: Partial<BasicClientComponentState>
  ) => {
    setState(prevState => {
      const newState = { ...prevState, ...updates };
      onStateChange?.(newState);
      return newState;
    });
  }, [onStateChange]);

  // 计算属性
  const computedValue = useMemo(() => {
    return state.count * 2;
  }, [state.count]);

  // 事件处理器
  const handleIncrement = useCallback(() => {
    updateState({ count: state.count + 1 });
  }, [state.count, updateState]);

  const handleToggle = useCallback(() => {
    updateState({ isVisible: !state.isVisible });
  }, [state.isVisible, updateState]);

  return (
    <div
      id={id}
      className={`basic-client-component ${className}`}
      data-count={state.count}
      data-visible={state.isVisible}
    >
      <h2>基础客户端组件</h2>

      {/* 状态显示 */}
      <div className="state-display">
        <p>计数: {state.count}</p>
        <p>计算值: {computedValue}</p>
        <p>可见性: {state.isVisible ? '可见' : '隐藏'}</p>
      </div>

      {/* 交互按钮 */}
      <div className="controls">
        <button onClick={handleIncrement}>
          增加计数
        </button>
        <button onClick={handleToggle}>
          切换可见性
        </button>
      </div>

      {/* 子组件渲染 */}
      {state.isVisible && children}
    </div>
  );
};

// components/higher-order-client-component.tsx
'use client';

import React, { ComponentType, useState, useEffect, useCallback } from 'react';
import { ClientComponentMetadata } from '@/types/client-component';

// 高阶组件接口
interface WithLoadingProps {
  loading?: boolean;
  error?: Error | null;
}

interface WithCounterProps {
  count?: number;
  onIncrement?: () => void;
  onDecrement?: () => void;
}

// 加载状态高阶组件
export function withLoading<P extends object>(
  WrappedComponent: ComponentType<P>
): ComponentType<P & WithLoadingProps> {
  return function WithLoadingComponent({
    loading = false,
    error = null,
    ...props
  }: P & WithLoadingProps) {
    if (loading) {
      return (
        <div className="loading-container">
          <div className="loading-spinner" />
          <p>加载中...</p>
        </div>
      );
    }

    if (error) {
      return (
        <div className="error-container">
          <h3>加载错误</h3>
          <p>{error.message}</p>
        </div>
      );
    }

    return <WrappedComponent {...(props as P)} />;
  };
}

// 计数器高阶组件
export function withCounter<P extends object>(
  WrappedComponent: ComponentType<P>
): ComponentType<P & WithCounterProps> {
  return function WithCounterComponent({
    count: initialCount = 0,
    onIncrement,
    onDecrement,
    ...props
  }: P & WithCounterProps) {
    const [count, setCount] = useState(initialCount);

    const handleIncrement = useCallback(() => {
      setCount(prev => prev + 1);
      onIncrement?.();
    }, [onIncrement]);

    const handleDecrement = useCallback(() => {
      setCount(prev => prev - 1);
      onDecrement?.();
    }, [onDecrement]);

    return (
      <div className="counter-wrapper">
        <div className="counter-display">
          计数: {count}
        </div>
        <div className="counter-controls">
          <button onClick={handleIncrement}>+</button>
          <button onClick={handleDecrement}>-</button>
        </div>
        <WrappedComponent {...(props as P)} />
      </div>
    );
  };
}

// 组合高阶组件使用
export const EnhancedComponent = withLoading(
  withCounter(BasicClientComponent)
);

// components/local-state-component.tsx
'use client';

import React, { useReducer, useCallback, useContext } from 'react';
import { createContext } from 'react';

// 状态类型定义
interface LocalState {
  user: User | null;
  preferences: UserPreferences;
  notifications: Notification[];
  ui: UIState;
}

interface User {
  id: string;
  name: string;
  email: string;
  avatar?: string;
}

interface UserPreferences {
  theme: 'light' | 'dark' | 'auto';
  language: string;
  notifications: boolean;
}

interface Notification {
  id: string;
  type: 'info' | 'success' | 'warning' | 'error';
  message: string;
  timestamp: Date;
}

interface UIState {
  sidebarOpen: boolean;
  modalOpen: boolean;
  loading: boolean;
}

// Action 类型定义
type LocalAction =
  | { type: 'SET_USER'; payload: User | null }
  | { type: 'UPDATE_PREFERENCES'; payload: Partial<UserPreferences> }
  | { type: 'ADD_NOTIFICATION'; payload: Omit<Notification, 'id' | 'timestamp'> }
  | { type: 'REMOVE_NOTIFICATION'; payload: string }
  | { type: 'TOGGLE_SIDEBAR' }
  | { type: 'SET_LOADING'; payload: boolean }
  | { type: 'RESET_STATE' };

// Reducer 函数
function localStateReducer(state: LocalState, action: LocalAction): LocalState {
  switch (action.type) {
    case 'SET_USER':
      return { ...state, user: action.payload };

    case 'UPDATE_PREFERENCES':
      return {
        ...state,
        preferences: { ...state.preferences, ...action.payload }
      };

    case 'ADD_NOTIFICATION':
      return {
        ...state,
        notifications: [
          ...state.notifications,
          {
            ...action.payload,
            id: Date.now().toString(),
            timestamp: new Date()
          }
        ]
      };

    case 'REMOVE_NOTIFICATION':
      return {
        ...state,
        notifications: state.notifications.filter(
          notification => notification.id !== action.payload
        )
      };

    case 'TOGGLE_SIDEBAR':
      return {
        ...state,
        ui: { ...state.ui, sidebarOpen: !state.ui.sidebarOpen }
      };

    case 'SET_LOADING':
      return {
        ...state,
        ui: { ...state.ui, loading: action.payload }
      };

    case 'RESET_STATE':
      return initialState;

    default:
      return state;
  }
}

// 初始状态
const initialState: LocalState = {
  user: null,
  preferences: {
    theme: 'auto',
    language: 'zh-CN',
    notifications: true
  },
  notifications: [],
  ui: {
    sidebarOpen: false,
    modalOpen: false,
    loading: false
  }
};

// Context 创建
const LocalStateContext = createContext<{
  state: LocalState;
  dispatch: React.Dispatch<LocalAction>;
} | null>(null);

// Provider 组件
export const LocalStateProvider: React.FC<{
  children: React.ReactNode;
}> = ({ children }) => {
  const [state, dispatch] = useReducer(localStateReducer, initialState);

  return (
    <LocalStateContext.Provider value={{ state, dispatch }}>
      {children}
    </LocalStateContext.Provider>
  );
};

// Hook 使用
export const useLocalState = () => {
  const context = useContext(LocalStateContext);
  if (!context) {
    throw new Error('useLocalState must be used within LocalStateProvider');
  }
  return context;
};

// 具体使用组件
