// components/event-handling-component.tsx
'use client';

import React, {
  useState,
  useCallback,
  useEffect,
  useRef,
  useMemo
} from 'react';
import {
  MouseEvent,
  KeyboardEvent,
  ChangeEvent,
  FormEvent,
  FocusEvent,
  DragEvent,
  WheelEvent,
  TouchEvent
} from 'react';

interface EventHandlingState {
  mousePosition: { x: number; y: number };
  keyPressed: string;
  inputValue: string;
  isDragging: boolean;
  dragData: any;
  scrollPosition: number;
  touchPosition: { x: number; y: number } | null;
  focusTarget: string;
  formValues: Record<string, any>;
}

export const EventHandlingComponent: React.FC = () => {
  const [state, setState] = useState<EventHandlingState>({
    mousePosition: { x: 0, y: 0 },
    keyPressed: '',
    inputValue: '',
    isDragging: false,
    dragData: null,
    scrollPosition: 0,
    touchPosition: null,
    focusTarget: '',
    formValues: {}
  });

  const containerRef = useRef<HTMLDivElement>(null);
  const dragCounterRef = useRef(0);

  // 鼠标事件处理
  const handleMouseMove = useCallback((e: MouseEvent<HTMLDivElement>) => {
    setState(prev => ({
      ...prev,
      mousePosition: { x: e.clientX, y: e.clientY }
    }));
  }, []);

  const handleMouseClick = useCallback((e: MouseEvent<HTMLButtonElement>) => {
    console.log('Button clicked at:', e.clientX, e.clientY);

    // 阻止事件冒泡
    e.stopPropagation();

    // 阻止默认行为
    e.preventDefault();
  }, []);

  const handleContextMenu = useCallback((e: MouseEvent<HTMLDivElement>) => {
    e.preventDefault();
    console.log('Context menu blocked');
  }, []);

  // 键盘事件处理
  const handleKeyDown = useCallback((e: KeyboardEvent<HTMLInputElement>) => {
    setState(prev => ({
      ...prev,
      keyPressed: e.key
    }));

    // 快捷键处理
    if (e.ctrlKey && e.key === 's') {
      e.preventDefault();
      console.log('Save shortcut triggered');
    }

    if (e.key === 'Enter') {
      console.log('Enter key pressed');
    }
  }, []);

  const handleKeyUp = useCallback((e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key.length === 1) {
      setState(prev => ({
        ...prev,
        keyPressed: ''
      }));
    }
  }, []);

  // 表单事件处理
  const handleInputChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
    const { name, value, type, checked } = e.target;

    setState(prev => ({
      ...prev,
      inputValue: value,
      formValues: {
        ...prev.formValues,
        [name]: type === 'checkbox' ? checked : value
      }
    }));
  }, []);

  const handleFormSubmit = useCallback((e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    console.log('Form submitted with:', state.formValues);
  }, [state.formValues]);

  // 焦点事件处理
  const handleFocus = useCallback((e: FocusEvent<HTMLInputElement>) => {
    setState(prev => ({
      ...prev,
      focusTarget: e.target.name
    }));
  }, []);

  const handleBlur = useCallback((e: FocusEvent<HTMLInputElement>) => {
    setState(prev => ({
      ...prev,
      focusTarget: ''
    }));
  }, []);

  // 拖拽事件处理
  const handleDragStart = useCallback((e: DragEvent<HTMLDivElement>) => {
    setState(prev => ({
      ...prev,
      isDragging: true,
      dragData: { message: 'Dragging started' }
    }));

    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', 'Drag data');
  }, []);

  const handleDragOver = useCallback((e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  }, []);

  const handleDrop = useCallback((e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();

    const data = e.dataTransfer.getData('text/plain');
    console.log('Dropped data:', data);

    setState(prev => ({
      ...prev,
      isDragging: false,
      dragData: { message: 'Dropped', data }
    }));
  }, []);

  const handleDragEnd = useCallback((e: DragEvent<HTMLDivElement>) => {
    setState(prev => ({
      ...prev,
      isDragging: false,
      dragData: null
    }));
  }, []);

  // 滚轮事件处理
  const handleWheel = useCallback((e: WheelEvent<HTMLDivElement>) => {
    e.preventDefault();

    setState(prev => ({
      ...prev,
      scrollPosition: prev.scrollPosition + e.deltaY
    }));
  }, []);

  // 触摸事件处理
  const handleTouchStart = useCallback((e: TouchEvent<HTMLDivElement>) => {
    const touch = e.touches[0];
    setState(prev => ({
      ...prev,
      touchPosition: { x: touch.clientX, y: touch.clientY }
    }));
  }, []);

  const handleTouchMove = useCallback((e: TouchEvent<HTMLDivElement>) => {
    const touch = e.touches[0];
    setState(prev => ({
      ...prev,
      touchPosition: { x: touch.clientX, y: touch.clientY }
    }));
  }, []);

  const handleTouchEnd = useCallback((e: TouchEvent<HTMLDivElement>) => {
    setState(prev => ({
      ...prev,
      touchPosition: null
    }));
  }, []);

  // 计算鼠标位置样式
  const mousePositionStyle = useMemo(() => ({
    position: 'absolute' as const,
    left: `${state.mousePosition.x}px`,
    top: `${state.mousePosition.y}px`,
    width: '10px',
    height: '10px',
    backgroundColor: 'red',
    borderRadius: '50%',
    pointerEvents: 'none' as const,
    transform: 'translate(-50%, -50%)'
  }), [state.mousePosition]);

  return (
    <div
      ref={containerRef}
      className="event-handling-component"
      onMouseMove={handleMouseMove}
      onContextMenu={handleContextMenu}
      onWheel={handleWheel}
    >
      <h2>事件处理组件</h2>

      {/* 鼠标事件 */}
      <div className="mouse-events">
        <h3>鼠标事件</h3>
        <p>鼠标位置: ({state.mousePosition.x}, {state.mousePosition.y})</p>
        <button onClick={handleMouseClick}>
          点击我 (阻止冒泡和默认行为)
        </button>
        <div className="context-menu-area">
          右键点击这里查看阻止的上下文菜单
        </div>
        <div style={mousePositionStyle} />
      </div>

      {/* 键盘事件 */}
      <div className="keyboard-events">
        <h3>键盘事件</h3>
        <input
          type="text"
          placeholder="在这里输入文字，试试 Ctrl+S 快捷键"
          onKeyDown={handleKeyDown}
          onKeyUp={handleKeyUp}
          onFocus={handleFocus}
          onBlur={handleBlur}
        />
        <p>最后按下的键: {state.keyPressed || '无'}</p>
        <p>当前焦点: {state.focusTarget || '无'}</p>
      </div>

      {/* 表单事件 */}
      <div className="form-events">
        <h3>表单事件</h3>
        <form onSubmit={handleFormSubmit}>
          <input
            type="text"
            name="username"
            placeholder="用户名"
            value={state.formValues.username || ''}
            onChange={handleInputChange}
          />
          <input
            type="email"
            name="email"
            placeholder="邮箱"
            value={state.formValues.email || ''}
            onChange={handleInputChange}
          />
          <label>
            <input
              type="checkbox"
              name="newsletter"
              checked={state.formValues.newsletter || false}
              onChange={handleInputChange}
            />
            订阅新闻
          </label>
          <button type="submit">提交</button>
        </form>
        <p>输入值: {state.inputValue}</p>
        <p>表单数据: {JSON.stringify(state.formValues)}</p>
      </div>

      {/* 拖拽事件 */}
      <div className="drag-events">
        <h3>拖拽事件</h3>
        <div
          className="draggable-item"
          draggable
          onDragStart={handleDragStart}
          onDragEnd={handleDragEnd}
        >
          拖拽我
        </div>
        <div
          className="drop-zone"
          onDragOver={handleDragOver}
          onDrop={handleDrop}
        >
          放置区域
        </div>
        <p>拖拽状态: {state.isDragging ? '正在拖拽' : '未拖拽'}</p>
        <p>拖拽数据: {JSON.stringify(state.dragData)}</p>
      </div>

      {/* 滚轮事件 */}
      <div className="wheel-events">
        <h3>滚轮事件</h3>
        <div className="wheel-area">
          在这里滚动鼠标滚轮
        </div>
        <p>滚动位置: {state.scrollPosition}</p>
      </div>

      {/* 触摸事件 */}
      <div className="touch-events">
        <h3>触摸事件</h3>
        <div
          className="touch-area"
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
        >
          在这里触摸
        </div>
        <p>触摸位置: {state.touchPosition ?
          `(${state.touchPosition.x}, ${state.touchPosition.y})` : '无'}</p>
      </div>
    </div>
  );
};

