    console.log('过滤数据...');
    return data.filter(item => item.toString().includes(filter));
  }, [data, filter]);

  const calculationResult = useMemo(() => {
    return expensiveCalculation(filteredData);
  }, [filteredData]);

  // 使用 useCallback 缓存事件处理函数
  const handleItemClick = useCallback((item: number) => {
