'use client';

import React, {
  useState,
  useEffect,
  useCallback,
  useRef,
  ComponentType
} from 'react';

// 数据状态接口
interface DataState<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
}

// Render Props 接口
interface DataFetcherProps<T> {
  url: string;
  children: (state: DataState<T>) => React.ReactNode;
  initialData?: T;
  refetchInterval?: number;
  onSuccess?: (data: T) => void;
  onError?: (error: Error) => void;
}

// 数据获取组件
export function DataFetcher<T>({
  url,
  children,
  initialData,
  refetchInterval,
  onSuccess,
  onError
}: DataFetcherProps<T>) {
  const [state, setState] = useState<DataState<T>>({
    data: initialData || null,
    loading: !initialData,
    error: null
  });

  const fetchData = useCallback(async () => {
    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      setState({
        data,
        loading: false,
        error: null
      });

      onSuccess?.(data);
    } catch (error) {
      const errorObj = error instanceof Error ? error : new Error('Unknown error');

      setState({
        data: null,
        loading: false,
        error: errorObj
      });

      onError?.(errorObj);
    }
  }, [url, onSuccess, onError]);

  useEffect(() => {
    if (!state.data && !state.error) {
      fetchData();
    }

    if (refetchInterval) {
      const interval = setInterval(fetchData, refetchInterval);
      return () => clearInterval(interval);
    }
  }, [fetchData, refetchInterval, state.data, state.error]);

  return <>{children(state)}</>;
}

// 高级数据获取器 - 支持缓存
interface AdvancedDataFetcherProps<T> extends DataFetcherProps<T> {
  cacheKey?: string;
  cacheTime?: number;
}

export function AdvancedDataFetcher<T>({
  url,
  cacheKey,
  cacheTime = 5 * 60 * 1000, // 5分钟
  children,
  ...props
}: AdvancedDataFetcherProps<T>) {
  // 简单的内存缓存实现
  const cache = useRef<Map<string, { data: T; timestamp: number }>>(new Map());

  const getCachedData = useCallback((key: string): T | null => {
    const cached = cache.current.get(key);
    if (cached && Date.now() - cached.timestamp < cacheTime) {
      return cached.data;
    }
    return null;
  }, [cacheTime]);

  const setCachedData = useCallback((key: string, data: T) => {
    cache.current.set(key, { data, timestamp: Date.now() });
  }, []);

  const handleSuccess = useCallback((data: T) => {
    if (cacheKey) {
      setCachedData(cacheKey, data);
    }
    props.onSuccess?.(data);
  }, [cacheKey, setCachedData, props.onSuccess]);

  // 检查缓存
  const cachedData = cacheKey ? getCachedData(cacheKey) : null;

  return (
    <DataFetcher
      url={url}
      initialData={cachedData}
      onSuccess={handleSuccess}
      {...props}
    >
      {children}
    </DataFetcher>
  );
}

