import { create } from 'zustand';
import { devtools, subscribeWithSelector, persist } from 'zustand/middleware';
import { immer } from 'zustand/middleware/immer';

// 类型定义
interface User {
  id: string;
  email: string;
  name: string;
  avatar?: string;
  role: 'user' | 'admin' | 'moderator';
  preferences: {
    theme: 'light' | 'dark' | 'auto';
    language: string;
    notifications: boolean;
  };
}

interface AppState {
  // 用户状态
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;

  // 应用状态
  theme: 'light' | 'dark' | 'auto';
  sidebarOpen: boolean;
  notifications: Array<{
    id: string;
    type: 'info' | 'success' | 'warning' | 'error';
    title: string;
    message: string;
    timestamp: Date;
    read: boolean;
  }>;

  // 系统状态
  online: boolean;
  lastActivity: Date;

  // 操作方法
  setUser: (user: User | null) => void;
  setTheme: (theme: 'light' | 'dark' | 'auto') => void;
  toggleSidebar: () => void;
  addNotification: (notification: Omit<AppState['notifications'][0], 'id' | 'timestamp' | 'read'>) => void;
  markNotificationRead: (id: string) => void;
  clearNotifications: () => void;
  setOnline: (online: boolean) => void;
  updateLastActivity: () => void;
  logout: () => void;
}

// 创建 Zustand Store
export const useAppStore = create<AppState>()(
  devtools(
    subscribeWithSelector(
      persist(
        immer((set, get) => ({
          // 初始状态
          user: null,
          isAuthenticated: false,
          isLoading: false,
          theme: 'auto',
          sidebarOpen: true,
          notifications: [],
          online: navigator.onLine,
          lastActivity: new Date(),

          // 用户操作
          setUser: (user) => set((state) => {
            state.user = user;
            state.isAuthenticated = !!user;
            state.isLoading = false;
          }),

          setTheme: (theme) => set((state) => {
            state.theme = theme;
            if (state.user) {
              state.user.preferences.theme = theme;
            }
          }),

          toggleSidebar: () => set((state) => {
            state.sidebarOpen = !state.sidebarOpen;
          }),

          // 通知操作
          addNotification: (notification) => set((state) => {
            const newNotification = {
              ...notification,
              id: crypto.randomUUID(),
              timestamp: new Date(),
              read: false,
            };
            state.notifications.unshift(newNotification);

            // 限制通知数量
            if (state.notifications.length > 50) {
              state.notifications = state.notifications.slice(0, 50);
            }
          }),

          markNotificationRead: (id) => set((state) => {
            const notification = state.notifications.find(n => n.id === id);
            if (notification) {
              notification.read = true;
            }
          }),

          clearNotifications: () => set((state) => {
            state.notifications = [];
          }),

          // 系统操作
          setOnline: (online) => set((state) => {
            state.online = online;
          }),

          updateLastActivity: () => set((state) => {
            state.lastActivity = new Date();
          }),

          logout: () => set((state) => {
            state.user = null;
            state.isAuthenticated = false;
            state.notifications = [];
          }),
        })),
        {
          name: 'app-store',
          partialize: (state) => ({
            user: state.user,
            theme: state.theme,
            sidebarOpen: state.sidebarOpen,
            notifications: state.notifications.filter(n => !n.read),
          }),
        }
      )
    ),
    {
      name: 'AppStore',
    }
  )
);

// 选择器 hooks - 优化性能
export const useUser = () => useAppStore((state) => state.user);
export const useIsAuthenticated = () => useAppStore((state) => state.isAuthenticated);
export const useTheme = () => useAppStore((state) => state.theme);
export const useSidebarOpen = () => useAppStore((state) => state.sidebarOpen);
export const useNotifications = () => useAppStore((state) => state.notifications);
export const useUnreadNotifications = () => useAppStore((state) =>
  state.notifications.filter(n => !n.read)
);
export const useOnlineStatus = () => useAppStore((state) => state.online);

// 监听器设置
if (typeof window !== 'undefined') {
  // 监听网络状态
  window.addEventListener('online', () => {
    useAppStore.getState().setOnline(true);
  });

  window.addEventListener('offline', () => {
    useAppStore.getState().setOnline(false);
  });

  // 监听用户活动
  const updateActivity = () => {
    useAppStore.getState().updateLastActivity();
  };

  window.addEventListener('click', updateActivity);
  window.addEventListener('keydown', updateActivity);
  window.addEventListener('scroll', updateActivity);

  // 自动登出检查
  setInterval(() => {
    const { lastActivity, isAuthenticated, logout } = useAppStore.getState();
    const now = new Date();
    const inactiveTime = now.getTime() - lastActivity.getTime();
    const maxInactiveTime = 30 * 60 * 1000; // 30分钟

    if (isAuthenticated && inactiveTime > maxInactiveTime) {
      logout();
      window.location.href = '/login?reason=timeout';
    }
  }, 60000); // 每分钟检查一次
}

// stores/base-store.ts
import { create } from 'zustand';
import { devtools, subscribeWithSelector } from 'zustand/middleware';
import { immer } from 'zustand/middleware/immer';

// 基础 Store 类型
interface BaseStore<T> {
  data: T | null;
  loading: boolean;
  error: string | null;
  lastUpdated: Date | null;

  // 操作
  setData: (data: T) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  clearData: () => void;
  refresh: () => Promise<void>;
}

// 创建基础 Store
export function createBaseStore<T>(
  name: string,
  fetchFn: () => Promise<T>
) {
  return create<BaseStore<T>>()(
    devtools(
      subscribeWithSelector(
        immer((set, get) => ({
          data: null,
          loading: false,
          error: null,
          lastUpdated: null,

          setData: (data) => set((state) => {
            state.data = data;
            state.loading = false;
            state.error = null;
            state.lastUpdated = new Date();
          }),

          setLoading: (loading) => set((state) => {
            state.loading = loading;
            if (loading) {
              state.error = null;
            }
          }),

          setError: (error) => set((state) => {
            state.error = error;
            state.loading = false;
          }),

          clearData: () => set((state) => {
            state.data = null;
            state.error = null;
            state.lastUpdated = null;
          }),

          refresh: async () => {
            const { setLoading, setError, setData } = get();

            setLoading(true);
            try {
              const data = await fetchFn();
              setData(data);
            } catch (error) {
              setError(error instanceof Error ? error.message : 'Unknown error');
            }
          },
        }))
      ),
      { name }
    )
  );
}

// 缓存 Store
interface CacheStore<T> extends BaseStore<T> {
  cacheTime: number;
  maxAge: number;

  setCacheTime: (time: number) => void;
  isExpired: () => boolean;
  getCachedData: () => T | null;
}

export function createCacheStore<T>(
  name: string,
  fetchFn: () => Promise<T>,
  maxAge: number = 5 * 60 * 1000 // 5分钟
) {
  return create<CacheStore<T>>()(
    devtools(
      subscribeWithSelector(
        immer((set, get) => ({
          data: null,
          loading: false,
          error: null,
          lastUpdated: null,
          cacheTime: 0,
          maxAge,

          setData: (data) => set((state) => {
            state.data = data;
            state.loading = false;
            state.error = null;
            state.lastUpdated = new Date();
            state.cacheTime = Date.now();
          }),

          setLoading: (loading) => set((state) => {
            state.loading = loading;
          }),

          setError: (error) => set((state) => {
            state.error = error;
            state.loading = false;
          }),

          clearData: () => set((state) => {
            state.data = null;
            state.error = null;
            state.lastUpdated = null;
            state.cacheTime = 0;
          }),

          setCacheTime: (time) => set((state) => {
            state.cacheTime = time;
          }),

          isExpired: () => {
            const { cacheTime, maxAge } = get();
            return Date.now() - cacheTime > maxAge;
          },

          getCachedData: () => {
            const { data, isExpired } = get();
            return isExpired() ? null : data;
          },

          refresh: async () => {
            const { setLoading, setError, setData, isExpired, data } = get();

            if (!isExpired() && data) {
              return; // 使用缓存数据
            }

            setLoading(true);
            try {
              const freshData = await fetchFn();
              setData(freshData);
            } catch (error) {
              setError(error instanceof Error ? error.message : 'Unknown error');
            }
          },
        }))
      ),
      { name }
    )
  );
}

