// lib/query-client.ts
import { QueryClient } from '@tanstack/react-query';

// 创建 Query Client
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // 重试配置
      retry: (failureCount, error: any) => {
        // 4xx 错误不重试
        if (error?.status >= 400 && error?.status < 500) {
          return false;
        }
        // 最多重试3次
        return failureCount < 3;
      },
      retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 30000),

      // 缓存配置
      staleTime: 5 * 60 * 1000, // 5分钟内数据视为新鲜
      gcTime: 10 * 60 * 1000, // 10分钟缓存时间
      refetchOnWindowFocus: false,
      refetchOnReconnect: true,

      // 错误处理
      throwOnError: false,

      // 查询配置
      networkMode: 'online',
    },
    mutations: {
      retry: 1,
      networkMode: 'online',
    },
  },
});

// hooks/use-query-with-error-handling.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';

// 增强的查询 Hook
export function useQueryWithError<T>(
  queryKey: any[],
  queryFn: () => Promise<T>,
  options?: {
    errorMessage?: string;
    successMessage?: string;
    onSuccess?: (data: T) => void;
    onError?: (error: Error) => void;
  }
) {
  return useQuery({
    queryKey,
    queryFn: async () => {
      try {
        const result = await queryFn();
        if (options?.successMessage) {
          toast.success(options.successMessage);
        }
        options?.onSuccess?.(result);
        return result;
      } catch (error) {
        const errorMessage = options?.errorMessage ||
          (error instanceof Error ? error.message : 'Query failed');
        toast.error(errorMessage);
        options?.onError?.(error instanceof Error ? error : new Error(String(error)));
        throw error;
      }
    },
  });
}

// 增强的变更 Hook
export function useMutationWithError<TData, TVariables, TContext>(
  mutationFn: (variables: TVariables) => Promise<TData>,
  options?: {
    successMessage?: string;
    errorMessage?: string;
    onSuccess?: (data: TData, variables: TVariables, context?: TContext) => void;
    onError?: (error: Error, variables: TVariables, context?: TContext) => void;
    invalidateQueries?: any[];
  }
) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (variables) => {
      try {
        const result = await mutationFn(variables);
        if (options?.successMessage) {
          toast.success(options.successMessage);
        }
        options?.onSuccess?.(result, variables);

        // 失效相关查询
        if (options?.invalidateQueries) {
          options.invalidateQueries.forEach(queryKey => {
            queryClient.invalidateQueries({ queryKey });
          });
        }

        return result;
      } catch (error) {
        const errorMessage = options?.errorMessage ||
          (error instanceof Error ? error.message : 'Mutation failed');
        toast.error(errorMessage);
        options?.onError?.(error instanceof Error ? error : new Error(String(error)), variables);
        throw error;
      }
    },
  });
}

