// hooks/use-optimized-selectors.ts
import { useMemo } from 'react';
import { useShallow } from 'zustand/react/shallow';

// 记忆化选择器
export function useMemoizedSelector<T, R>(
  selector: (state: T) => R,
  deps: any[] = []
) {
  return useMemo(() => selector, deps);
}

// 浅比较选择器
export function useShallowSelector<T, R>(
  selector: (state: T) => R
) {
  // Zustand 内置的 shallow 比较函数
  return selector;
}

// 复合选择器示例
export function useComplexUserSelector() {
  const user = useAppStore(useMemoizedSelector(
    (state) => ({
      id: state.user?.id,
      name: state.user?.name,
      avatar: state.user?.avatar,
      preferences: state.user?.preferences,
      isAuthenticated: state.isAuthenticated,
    }),
    []
  ));

  return user;
}

// 计算属性选择器
export function useComputedNotifications() {
  const notifications = useAppStore(useShallow(state => state.notifications));

  return useMemo(() => ({
    total: notifications.length,
    unread: notifications.filter(n => !n.read).length,
    byType: notifications.reduce((acc, n) => {
      acc[n.type] = (acc[n.type] || 0) + 1;
      return acc;
    }, {} as Record<string, number>),
    recent: notifications.filter(n =>
      new Date(n.timestamp).getTime() > Date.now() - 24 * 60 * 60 * 1000
    ),
  }), [notifications]);
}

// hooks/use-state-with-error-handling.ts
import { useState, useCallback, useEffect } from 'react';

interface StateWithRetry<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
  retryCount: number;

  retry: () => void;
  reset: () => void;
}

export function useStateWithRetry<T>(
  fetchFn: () => Promise<T>,
  options?: {
    maxRetries?: number;
    retryDelay?: number;
    exponentialBackoff?: boolean;
  }
): StateWithRetry<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [retryCount, setRetryCount] = useState(0);

  const maxRetries = options?.maxRetries ?? 3;
  const baseRetryDelay = options?.retryDelay ?? 1000;
  const useExponentialBackoff = options?.exponentialBackoff ?? true;

  const execute = useCallback(async (attempt = 1) => {
    setLoading(true);
    setError(null);

    try {
      const result = await fetchFn();
      setData(result);
      setRetryCount(0);
      return result;
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));

      if (attempt < maxRetries) {
        const delay = useExponentialBackoff
          ? baseRetryDelay * Math.pow(2, attempt - 1)
          : baseRetryDelay;

        setTimeout(() => {
          execute(attempt + 1);
        }, delay);

        setRetryCount(attempt);
      } else {
        setError(error);
        setRetryCount(attempt);
      }
    } finally {
      setLoading(false);
    }
  }, [fetchFn, maxRetries, baseRetryDelay, useExponentialBackoff]);

  const retry = useCallback(() => {
    execute(1);
  }, [execute]);

  const reset = useCallback(() => {
    setData(null);
    setError(null);
    setRetryCount(0);
  }, []);

  useEffect(() => {
    execute();
  }, [execute]);

  return {
    data,
    loading,
    error,
    retryCount,
    retry,
    reset,
  };
}

import { ReactNode, useState, useCallback, useMemo, useEffect } from "react"
import { z } from "zod"
import { useForm, UseFormReturn } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"
import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

// 类型安全的样式合并
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

// 表单字段基础类型
export interface FormField {
  id: string
  name: string
  label: string
  description?: string
  placeholder?: string
  required?: boolean
  disabled?: boolean
  type: "text" | "email" | "password" | "number" | "tel" | "url" | "search"
  validation?: z.ZodSchema
  defaultValue?: any
  component?: React.ComponentType<any>
  props?: Record<string, any>
}

// 表单配置接口
export interface FormConfig {
  fields: FormField[]
  defaultValues?: Record<string, any>
  onSubmit?: (data: any) => void | Promise<void>
  submitText?: string
  submitLoadingText?: string
  resetOnSubmit?: boolean
  className?: string
  mode?: "onBlur" | "onChange" | "onSubmit" | "all" | "default"
  reValidateMode?: "onChange" | "onBlur" | "onSubmit"
}

// 表单组件 Props
export interface FormProps<T extends z.ZodSchema> extends Omit<FormConfig, "fields"> {
  schema: T
  children?: React.ReactNode
  footer?: React.ReactNode
  title?: string
  description?: string
  loading?: boolean
  error?: string
}

// 高级表单字段配置（Omit 后重写 type，否则收窄失败：
// 接口继承要求子属性类型可赋给父属性类型，扩宽联合必须先剔除原字段）
export interface AdvancedFormField extends Omit<FormField, "type"> {
  type: FormField["type"] | "select" | "textarea" | "checkbox" | "radio" | "date" | "file" | "range" | "custom"
  options?: Array<{ label: string; value: any; disabled?: boolean }>
  multiple?: boolean
  accept?: string // 文件上传
  maxFiles?: number
  maxSize?: number // 文件大小限制 (bytes)
  min?: number
  max?: number
  step?: number
  rows?: number
  cols?: number
  customValidation?: (value: any) => string | boolean | Promise<string | boolean>
  conditional?: {
    field: string
    value: any
    operator?: "equals" | "notEquals" | "contains" | "notContains"
  }
  dependencies?: string[]
  transform?: (value: any) => any
  format?: (value: any) => string
  normalize?: (value: string) => string
  placeholder?: string
  helperText?: string
  errorText?: string
  showPasswordToggle?: boolean
  autoComplete?: string
  autoFocus?: boolean
  loading?: boolean
  rightElement?: React.ReactNode
  leftElement?: React.ReactNode
}

// 表单状态管理 Hook
export function useFormState<T extends z.ZodSchema>(
  schema: T,
  defaultValues?: Partial<z.infer<T>>
) {
  const form = useForm<z.infer<T>>({
    resolver: zodResolver(schema),
    defaultValues,
    mode: "onChange",
    reValidateMode: "onChange",
  })

  return form
}

// 动态表单 Hook
export function useDynamicForm<T extends z.ZodSchema>(
  initialSchema: T,
  initialDefaultValues?: Partial<z.infer<T>>
) {
  const [schema, setSchema] = useState(initialSchema)
  const formMethods = useFormState(schema, initialDefaultValues)
  const [fields, setFields] = useState<AdvancedFormField[]>([])

  const addField = useCallback((field: AdvancedFormField) => {
    setFields(prev => [...prev, field])
    // 动态更新表单值
    if (field.defaultValue !== undefined) {
      formMethods.setValue(field.name, field.defaultValue)
    }
  }, [formMethods])

  const removeField = useCallback((fieldName: string) => {
    setFields(prev => prev.filter(f => f.name !== fieldName))
    formMethods.unregister(fieldName)
  }, [formMethods])

  const updateField = useCallback((fieldName: string, updates: Partial<AdvancedFormField>) => {
    setFields(prev => prev.map(f =>
      f.name === fieldName ? { ...f, ...updates } : f
    ))
  }, [])

  const resetForm = useCallback(() => {
    formMethods.reset()
    setFields([])
  }, [formMethods])

  return {
    schema,
    setSchema,
    fields,
    form: formMethods,
    formMethods,
    addField,
    removeField,
    updateField,
    resetForm
  }
}

// 条件渲染 Hook
export function useConditionalField<T>(
  form: UseFormReturn<T>,
  condition: {
    field: keyof T
    value: any
    operator?: "equals" | "notEquals" | "contains" | "notContains"
  }
) {
  const value = form.watch(condition.field as string)

  const shouldShow = useMemo(() => {
    switch (condition.operator || "equals") {
      case "equals":
        return value === condition.value
      case "notEquals":
        return value !== condition.value
      case "contains":
        return typeof value === "string" && value.includes(condition.value)
      case "notContains":
        return typeof value === "string" && !value.includes(condition.value)
      default:
        return false
    }
  }, [value, condition])

  return shouldShow
}

// 异步验证 Hook
export function useAsyncValidation<T extends z.ZodSchema>(
  form: UseFormReturn<T>,
  fieldName: keyof T,
  validator: (value: any) => Promise<string | boolean>
) {
  const [isValidating, setIsValidating] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const validate = useCallback(async (value: any) => {
    setIsValidating(true)
    setError(null)

    try {
      const result = await validator(value)
      if (typeof result === "string") {
        setError(result)
        return false
      }
      if (!result) {
        setError("验证失败")
        return false
      }
      return true
    } catch (err) {
      setError(err instanceof Error ? err.message : "验证错误")
      return false
    } finally {
      setIsValidating(false)
    }
  }, [validator])

  useEffect(() => {
    const subscription = form.watch((value, { name }) => {
      if (name === fieldName) {
        validate(value[fieldName])
      }
    })

    return subscription.unsubscribe
  }, [form, fieldName, validate])

  return {
    validate,
    isValidating,
    error,
    setError
  }
}

// 文件上传 Hook
export function useFileUpload<T extends z.ZodSchema>(
  form: UseFormReturn<T>,
  fieldName: keyof T,
  options: {
    maxSize?: number
    maxFiles?: number
    accept?: string
    validator?: (file: File) => Promise<boolean>
    onUpload?: (files: File[]) => Promise<any>
  } = {}
) {
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [progress, setProgress] = useState(0)

  const maxSize = options.maxSize || 5 * 1024 * 1024 // 5MB
  const maxFiles = options.maxFiles || 5

  const uploadFiles = useCallback(async (files: FileList | File[]) => {
    setUploading(true)
    setError(null)
    setProgress(0)

    try {
      // 验证文件数量
      if (files.length > maxFiles) {
        throw new Error(`最多只能上传 ${maxFiles} 个文件`)
      }

      const validFiles: File[] = []

      // 验证每个文件
      for (let i = 0; i < files.length; i++) {
        const file = files[i]

        // 文件大小检查
        if (file.size > maxSize) {
          throw new Error(`文件 ${file.name} 超过大小限制 (${maxSize / 1024 / 1024}MB)`)
        }

        // 文件类型检查
        if (options.accept && !file.type.match(options.accept)) {
          throw new Error(`文件 ${file.name} 类型不被支持`)
        }

        // 自定义验证
        if (options.validator) {
          const isValid = await options.validator(file)
          if (!isValid) {
            throw new Error(`文件 ${file.name} 验证失败`)
          }
        }

        validFiles.push(file)
      }

      // 更新表单值
      form.setValue(fieldName as string, validFiles, { shouldValidate: true })

      // 自定义上传处理
      if (options.onUpload) {
        await options.onUpload(validFiles)
      }

      // 模拟上传进度
      for (let i = 0; i <= 100; i++) {
        setProgress(i)
        await new Promise(resolve => setTimeout(resolve, 50))
      }

      return validFiles
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "上传失败"
      setError(errorMessage)
      form.setError(fieldName as string, { type: "manual", message: errorMessage })
      return []
    } finally {
      setUploading(false)
      setProgress(0)
    }
  }, [form, fieldName, maxSize, maxFiles, options.accept, options.validator, options.onUpload])

  return {
    uploadFiles,
    uploading,
    error,
    progress,
    setError
  }
}

// 表单数据转换 Hook
export function useFormTransform<T extends z.ZodSchema>(
  form: UseFormReturn<T>,
  transforms: Record<string, (value: any) => any>
) {
  useEffect(() => {
    const subscription = form.watch((values) => {
      // 应用转换
      Object.entries(transforms).forEach(([field, transform]) => {
        if (field in values) {
          const transformedValue = transform(values[field as string])
          if (transformedValue !== values[field as string]) {
            form.setValue(field, transformedValue, { shouldValidate: true })
          }
        }
      })
    })

    return subscription.unsubscribe
  }, [form, transforms])
}

// 表单提交 Hook
export function useFormSubmit<T extends z.ZodSchema>(
  form: UseFormReturn<T>,
  options: {
    onSubmit?: (data: z.infer<T>) => void | Promise<void>
    onSuccess?: (data: z.infer<T>) => void
    onError?: (errors: any) => void
    validateOnSubmit?: boolean
    resetOnSubmit?: boolean
  } = {}
) {
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [submitError, setSubmitError] = useState<string | null>(null)

  const handleSubmit = useCallback(async (data: z.infer<T>) => {
    setIsSubmitting(true)
    setSubmitError(null)

    try {
      if (options.validateOnSubmit !== false) {
        const isValid = await form.trigger()
        if (!isValid) {
          return
        }
      }

      await options.onSubmit?.(data)
      options.onSuccess?.(data)

      if (options.resetOnSubmit !== false) {
        form.reset()
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "提交失败"
      setSubmitError(errorMessage)
      options.onError?.(err)
    } finally {
      setIsSubmitting(false)
    }
  }, [form, options])

  return {
    handleSubmit,
    isSubmitting,
    submitError,
    setSubmitError
  }
}

// 表单状态持久化 Hook
export function useFormPersistence<T extends z.ZodSchema>(
  form: UseFormReturn<T>,
  storageKey: string,
  options: {
    storage?: "localStorage" | "sessionStorage"
    debounceMs?: number
  } = {}
) {
  const storage = options.storage || "localStorage"
  const debounceMs = options.debounceMs || 500

  // 保存表单状态
  const saveFormState = useCallback(
    debounce((values: any) => {
      if (typeof window !== "undefined") {
        try {
          window[storage].setItem(storageKey, JSON.stringify(values))
        } catch (err) {
          console.warn("Failed to save form state:", err)
        }
      }
    }, debounceMs),
    [storageKey, debounceMs]
  )

  // 加载表单状态
  const loadFormState = useCallback(() => {
    if (typeof window !== "undefined") {
      try {
        const saved = window[storage].getItem(storageKey)
        if (saved) {
          return JSON.parse(saved)
        }
      } catch (err) {
        console.warn("Failed to load form state:", err)
      }
    }
    return null
  }, [storageKey])

  // 监听表单变化并保存
  useEffect(() => {
    const subscription = form.watch((values) => {
      saveFormState(values)
    })

    return subscription.unsubscribe
  }, [form, saveFormState])

  return {
    saveState: saveFormState,
    loadState: loadFormState,
    clearState: () => {
      if (typeof window !== "undefined") {
        window[storage].removeItem(storageKey)
      }
    }
  }
}

// 防抖函数
function debounce<T extends (...args: any[]) => void>(
  callback: (...args: T[]) => void,
  delay: number
) {
  let timeoutId: NodeJS.Timeout
  return (...args: T[]) => {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => callback(...args), delay)
  }
}

import { z } from "zod"

// 基础验证器
export const stringSchema = z.string({
  required_error: "此字段为必填项",
