import bcrypt from "bcrypt"
import { z } from "zod"
import { validatePasswordStrength } from "@/lib/security"
import { detectThreat, logSecurityEvent } from "@/lib/security"
import { authenticateWithTOTP } from "@/lib/mfa"

export const authConfig: NextAuthConfig = {
  // Prisma适配器支持数据库持久化
  adapter: PrismaAdapter(prisma),

  // 会话配置
  session: {
    strategy: "jwt",
    maxAge: 30 * 24 * 60 * 60, // 30天
    updateAge: 24 * 60 * 60, // 24小时更新一次
  },

  // JWT配置
  jwt: {
    secret: process.env.NEXTAUTH_JWT_SECRET!,
    encryption: true,
    maxAge: 60 * 60 * 24 * 30, // 30天
    signingKey: process.env.NEXTAUTH_JWT_SIGNING_KEY!,
    encryptionKey: process.env.NEXTAUTH_JWT_ENCRYPTION_KEY!,
  },

  // 页面配置
  pages: {
    signIn: "/auth/signin",
    signOut: "/auth/signout",
    error: "/auth/error",
    verifyRequest: "/auth/verify-request",
    newUser: "/auth/welcome",
  },

  // 回调配置
  callbacks: {
    // JWT回调 - 在JWT创建时执行
    async jwt({ token, user, account, profile, isNewUser }) {
      // 首次登录，添加额外信息
      if (isNewUser && user) {
        logSecurityEvent({
          type: "USER_REGISTERED",
          userId: user.id,
          email: user.email!,
          provider: account?.provider || "credentials",
          timestamp: new Date().toISOString()
        })
      }

      // 添加用户权限和角色
      if (user) {
        token.role = user.role
        token.permissions = user.permissions
        token.mfaEnabled = user.mfaEnabled
        token.emailVerified = user.emailVerified
      }

      // 添加账户信息
      if (account) {
        token.provider = account.provider
        token.providerAccountId = account.providerAccountId
      }

      return token
    },

    // 会话回调 - 在每次会话检查时执行
    async session({ session, token, user }) {
      // 添加用户信息到会话
      session.user.id = token.sub!
      session.user.role = token.role as string
      session.user.permissions = token.permissions as string[]
      session.user.mfaEnabled = token.mfaEnabled as boolean
      session.user.emailVerified = token.emailVerified as boolean
      session.user.provider = token.provider as string

      return session
    },

    // 重定向回调
    async redirect({ url, baseUrl }) {
      // 允许相对URL
      if (url.startsWith("/")) return `${baseUrl}${url}`
      // 允许同一域名下的URL
      else if (new URL(url).origin === baseUrl) return url
      return baseUrl
    },

    // 入场回调
    async signIn({ user, account, profile, email, credentials }) {
      // 威胁检测（signIn 回调无 request 参数，IP/UA 采集移至 middleware 层）
      const threatResult = await detectThreat({
        email: email!
      })

      if (threatResult.blocked) {
        logSecurityEvent({
          type: "SIGN_IN_BLOCKED",
          reason: threatResult.reason,
          email: email!,
          timestamp: new Date().toISOString()
        })
        return false
      }

      // 邮箱验证检查
      if (user && !user.emailVerified && account?.provider !== "credentials") {
        return "/auth/verify-email"
      }

      // MFA强制检查
      if (user && user.mfaEnabled && account?.provider === "credentials") {
        return "/auth/mfa"
      }

      return true
    },

    // 授权回调
    async authorized({ request, auth }) {
      const pathname = request.nextUrl.pathname

      // 公共页面无需认证
      const publicPaths = [
        "/", "/home", "/about", "/pricing",
        "/blog", "/auth/signin", "/auth/signup"
      ]

      if (publicPaths.includes(pathname)) return true

      // 需要认证的页面
      return !!auth
    }
  },

  // 事件配置
  events: {
    // 登录成功事件
    async signIn(message) {
      logSecurityEvent({
        type: "SIGN_IN_SUCCESS",
        userId: message.user?.id,
        email: message.user?.email!,
        provider: message.account?.provider || "credentials",
        timestamp: new Date().toISOString()
      })
    },

    // 登出事件
    async signOut(message) {
      logSecurityEvent({
        type: "SIGN_OUT",
        userId: message.session?.user?.id,
        timestamp: new Date().toISOString()
      })
    },

    // 会话创建事件
    async session(session) {
      logSecurityEvent({
        type: "SESSION_CREATED",
        userId: session.user?.id,
        timestamp: new Date().toISOString()
      })
    },

    // 错误事件
    async error(error) {
      logSecurityEvent({
        type: "AUTH_ERROR",
        error: error.name,
        message: error.message,
        timestamp: new Date().toISOString()
      })
    }
  },

  // 提供商配置
  providers: [
    // 凭证提供商（用户名/密码）
    CredentialsProvider({
      id: "credentials",
      name: "邮箱密码登录",
      credentials: {
        email: {
          label: "邮箱地址",
          type: "email",
          placeholder: "your@email.com"
        },
        password: {
          label: "密码",
          type: "password",
          placeholder: "输入您的密码"
        },
        totpCode: {
          label: "双因子验证码（如果启用）",
          type: "text",
          placeholder: "6位数验证码",
          required: false
        }
      },
      async authorize(credentials, req) {
        const { email, password, totpCode } = credentials

        if (!email || !password) {
          throw new Error("邮箱和密码不能为空")
        }

        // 速率限制检查
        const rateLimitResult = await rateLimit('login_attempts', {
          windowMs: 15 * 60 * 1000, // 15分钟
          max: 5,
          identifier: email
        })

        if (!rateLimitResult.success) {
          logSecurityEvent({
            type: "RATE_LIMIT_EXCEEDED",
            reason: "登录尝试过多",
            email,
            timestamp: new Date().toISOString()
          })
          throw new Error("登录尝试次数过多，请15分钟后再试")
        }

        try {
          // 获取用户信息
          const user = await prisma.user.findUnique({
            where: { email: email.toLowerCase() },
            include: {
              securitySettings: true,
              loginAttempts: {
                orderBy: { createdAt: 'desc' },
                take: 5
              }
            }
          })

          // 用户不存在
          if (!user) {
            await logFailedAttempt(email, "USER_NOT_FOUND", req)
            throw new Error("邮箱或密码错误")
          }

          // 检查账户状态
          if (!user.isActive) {
            await logFailedAttempt(user.id, "ACCOUNT_DISABLED", req)
            throw new Error("账户已被禁用，请联系客服")
          }

          if (user.lockedUntil && user.lockedUntil > new Date()) {
            await logFailedAttempt(user.id, "ACCOUNT_LOCKED", req)
            throw new Error("账户已临时锁定，请稍后再试")
          }

          // 验证密码
          const isPasswordValid = await bcrypt.compare(password, user.password)
          if (!isPasswordValid) {
            await logFailedAttempt(user.id, "INVALID_PASSWORD", req)
            await checkAccountLockout(user)
            throw new Error("邮箱或密码错误")
          }

          // MFA验证
          if (user.mfaEnabled) {
            if (!totpCode) {
              // 需要MFA但未提供验证码
              return null // 返回null会触发MFA流程
            }

            const isTOTPValid = await authenticateWithTOTP(user, totpCode)
            if (!isTOTPValid) {
              await logFailedAttempt(user.id, "INVALID_MFA_CODE", req)
              throw new Error("双因子验证码错误")
            }
          }

          // 验证成功，清除失败记录
          await prisma.loginAttempt.deleteMany({
            where: { userId: user.id }
          })

          // 更新登录信息
          await prisma.user.update({
            where: { id: user.id },
            data: {
              lastLoginAt: new Date(),
              lastLoginIp: req.ip || "unknown",
              lastLoginUserAgent: req.headers.get("user-agent") || "unknown",
              loginCount: { increment: 1 }
            }
          })

          // 记录安全事件
          await logSecurityEvent({
            type: "SIGN_IN_SUCCESS",
            userId: user.id,
            email: user.email,
            provider: "credentials",
            timestamp: new Date().toISOString()
          })

          return {
            id: user.id,
            email: user.email,
            name: user.name,
            role: user.role,
            permissions: user.permissions,
            mfaEnabled: user.mfaEnabled,
            emailVerified: user.emailVerified,
            image: user.image
          }

        } catch (error) {
          console.error("认证错误:", error)
          throw error
        }
      }
    }),

    // Google OAuth
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
      authorization: {
        params: {
          prompt: "consent",
          access_type: "offline",
          response_type: "code",
          scope: "openid email profile https://www.googleapis.com/auth/calendar.readonly"
        }
      },
      profile(profile) {
        return {
          id: profile.sub,
          name: profile.name,
          email: profile.email,
          image: profile.picture,
          emailVerified: profile.email_verified
        }
      }
    }),

    // GitHub OAuth
    GitHubProvider({
      clientId: process.env.GITHUB_CLIENT_ID!,
      clientSecret: process.env.GITHUB_CLIENT_SECRET!,
      authorization: {
        params: {
          scope: "read:user user:email"
        }
      },
      profile(profile) {
        return {
          id: profile.id.toString(),
          name: profile.name || profile.login,
          email: profile.email,
          image: profile.avatar_url,
          emailVerified: !!profile.email
        }
      }
    }),

    // Microsoft OAuth
    MicrosoftProvider({
      clientId: process.env.MICROSOFT_CLIENT_ID!,
      clientSecret: process.env.MICROSOFT_CLIENT_SECRET!,
      authorization: {
        params: {
          scope: "openid profile email User.Read"
        }
      },
      profile(profile) {
        return {
          id: profile.sub,
          name: profile.displayName,
          email: profile.mail,
          image: profile.photos?.[0]?.value,
          emailVerified: !!profile.mail
        }
      }
    }),

    // Apple OAuth
    AppleProvider({
      clientId: process.env.APPLE_CLIENT_ID!,
      clientSecret: {
        appleId: process.env.APPLE_CLIENT_ID!,
        teamId: process.env.APPLE_TEAM_ID!,
        privateKey: process.env.APPLE_PRIVATE_KEY!,
        keyId: process.env.APPLE_KEY_ID!,
      },
      profile(profile) {
        return {
          id: profile.sub,
          name: profile.name?.givenName && profile.name.familyName
            ? `${profile.name.givenName} ${profile.name.familyName}`
            : profile.email,
          email: profile.email,
          emailVerified: profile.email_verified
        }
      }
    }),
  ],

  // 调试配置（开发环境）
  debug: process.env.NODE_ENV === "development"
}

// 辅助函数：记录失败尝试
async function logFailedAttempt(userId: string, reason: string, req: any) {
  await prisma.loginAttempt.create({
    data: {
      userId,
      success: false,
      reason,
      ip: req.ip || "unknown",
      userAgent: req.headers.get("user-agent") || "unknown"
    }
  })

  logSecurityEvent({
    type: "SIGN_IN_FAILURE",
    userId,
    reason,
    timestamp: new Date().toISOString()
  })
}

// 辅助函数：检查账户锁定
async function checkAccountLockout(user: any) {
  const recentFailures = await prisma.loginAttempt.count({
    where: {
      userId: user.id,
      success: false,
      createdAt: {
        gte: new Date(Date.now() - 15 * 60 * 1000) // 最近15分钟
      }
    }
  })

  // 如果最近失败次数过多，锁定账户
  if (recentFailures >= 5) {
    const lockedUntil = new Date(Date.now() + 30 * 60 * 1000) // 锁定30分钟
    await prisma.user.update({
      where: { id: user.id },
      data: { lockedUntil }
    })

    logSecurityEvent({
      type: "ACCOUNT_LOCKED",
      userId: user.id,
      reason: `连续失败次数: ${recentFailures}`,
      lockedUntil: lockedUntil.toISOString(),
      timestamp: new Date().toISOString()
    })
  }
}

// 辅助函数：速率限制
async function rateLimit(key: string, options: { windowMs: number; max: number; identifier: string }) {
  const now = Date.now()
  const windowStart = now - options.windowMs

  // 检查时间窗口内的请求数量
  const requestCount = await prisma.rateLimit.count({
    where: {
      key,
      identifier: options.identifier,
      timestamp: { gte: new Date(windowStart) }
    }
  })

  if (requestCount >= options.max) {
    return { success: false, message: "请求频率过高" }
  }

  // 记录本次请求
  await prisma.rateLimit.create({
    data: {
      key,
      identifier: options.identifier,
      timestamp: new Date(now)
    }
  })

  // 清理过期的记录
  await prisma.rateLimit.deleteMany({
    where: {
      key,
      identifier: options.identifier,
      timestamp: { lt: new Date(windowStart) }
    }
  })

  return { success: true }
}

