// src/pages/api/users/index.ts
import type { NextApiRequest, NextApiResponse } from 'next'
import { ApiResponse, ApiHandler, User } from '@/types/api'

// 模拟用户数据
const users: User[] = [
  { id: '1', name: '张三', email: 'zhangsan@example.com', avatar: '', role: 'user', createdAt: new Date(), updatedAt: new Date() },
  { id: '2', name: '李四', email: 'lisi@example.com', avatar: '', role: 'admin', createdAt: new Date(), updatedAt: new Date() }
]

// 创建用户请求类型
interface CreateUserRequest {
  name: string
  email: string
  role?: 'user' | 'admin'
}

const handler: ApiHandler<CreateUserRequest, User[]> = async (req, res) => {
  try {
    switch (req.method) {
      case 'GET':
        // 获取用户列表
        return res.status(200).json({
          success: true,
          data: users,
          timestamp: new Date().toISOString()
        })

      case 'POST':
        // 创建新用户
        const { name, email, role = 'user' } = req.body as CreateUserRequest

        // 类型验证
        if (!name || !email) {
          return res.status(400).json({
            success: false,
            error: '姓名和邮箱是必填项',
            timestamp: new Date().toISOString()
          })
        }

        // 检查邮箱是否已存在
        if (users.some(user => user.email === email)) {
          return res.status(409).json({
            success: false,
            error: '邮箱已存在',
            timestamp: new Date().toISOString()
          })
        }

        // 创建新用户
        const newUser: User = {
          id: String(users.length + 1),
          name,
          email,
          role,
          createdAt: new Date(),
          updatedAt: new Date()
        }

        users.push(newUser)

        return res.status(201).json({
          success: true,
          data: [newUser],
          message: '用户创建成功',
          timestamp: new Date().toISOString()
        })

      default:
        // 不支持的HTTP方法
        return res.status(405).json({
          success: false,
          error: '不支持的请求方法',
          timestamp: new Date().toISOString()
        })
    }
  } catch (error) {
    console.error('API错误:', error)

    return res.status(500).json({
      success: false,
      error: '服务器内部错误',
      timestamp: new Date().toISOString()
    })
  }
}

export default handler

// src/hooks/useFetch.ts
import { useState, useEffect } from 'react'

interface FetchState<T> {
  data: T | null
  loading: boolean
  error: string | null
}

export function useFetch<T>(url: string): FetchState<T> & { refetch: () => void } {
  const [state, setState] = useState<FetchState<T>>({
    data: null,
    loading: true,
    error: null
  })

  const fetchData = async () => {
    setState(prev => ({ ...prev, loading: true, error: null }))

    try {
      const response = await fetch(url)

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`)
      }

      const result = await response.json() as { success: boolean; data: T; error?: string }

      if (result.success) {
        setState({
          data: result.data,
          loading: false,
          error: null
        })
      } else {
        setState({
          data: null,
          loading: false,
          error: result.error || '请求失败'
        })
      }
    } catch (error) {
      setState({
        data: null,
        loading: false,
        error: error instanceof Error ? error.message : '未知错误'
      })
    }
  }

  useEffect(() => {
    fetchData()
  }, [url])

  return {
    ...state,
    refetch: fetchData
  }
}

// src/types/store.ts
import { create } from 'zustand'
import { devtools, persist } from 'zustand/middleware'

// 用户状态类型
interface UserState {
  user: User | null
  isAuthenticated: boolean
  loading: boolean
}

// 用户操作类型
interface UserActions {
  login: (email: string, password: string) => Promise<void>
  logout: () => void
  updateUser: (updates: Partial<User>) => void
}

// 组合类型
type UserStore = UserState & UserActions

// 创建类型安全的store
export const useUserStore = create<UserStore>()(
  devtools(
    persist(
      (set, get) => ({
        // 初始状态
        user: null,
        isAuthenticated: false,
        loading: false,

        // 登录操作
        login: async (email: string, password: string) => {
          set({ loading: true })

          try {
            const response = await fetch('/api/auth/login', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ email, password })
            })

            const result = await response.json()

            if (result.success) {
              set({
                user: result.data,
                isAuthenticated: true,
                loading: false
              })
            } else {
              throw new Error(result.error)
            }
          } catch (error) {
            set({ loading: false })
            throw error
          }
        },

        // 登出操作
        logout: () => {
          set({
            user: null,
            isAuthenticated: false,
            loading: false
          })
        },

        // 更新用户信息
        updateUser: (updates: Partial<User>) => {
          const currentUser = get().user
          if (currentUser) {
            set({
              user: { ...currentUser, ...updates, updatedAt: new Date() }
            })
          }
        }
      }),
      {
        name: 'user-store',
        partialize: (state) => ({
          user: state.user,
          isAuthenticated: state.isAuthenticated
        })
      }
    )
  )
)

