import { z } from 'zod'

// 用户验证schema
export const userSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1).max(50),
  email: z.string().email(),
  avatar: z.string().url().optional(),
  role: z.enum(['admin', 'user', 'guest']),
