interface NavItem {
  href: string
  label: string
  icon?: React.ReactNode
  children?: NavItem[]
}

const navItems: NavItem[] = [
  { href: '/', label: '首页' },
  { href: '/about', label: '关于' },
  {
    href: '/blog',
    label: '博客',
