export function GlassEffect({
  children,
  className,
  blur = 'md',
  opacity = 'medium',
  border = true
}: GlassEffectProps) {
  const blurClasses = {
    sm: 'backdrop-blur-sm',
    md: 'backdrop-blur-md',
    lg: 'backdrop-blur-lg',
    xl: 'backdrop-blur-xl'
  }

  const opacityClasses = {
    low: 'bg-white/10 dark:bg-black/10',
    medium: 'bg-white/20 dark:bg-black/20',
    high: 'bg-white/30 dark:bg-black/30'
  }

  return (
    <div
      className={cn(
        'relative',
        blurClasses[blur],
        opacityClasses[opacity],
        border && 'border border-white/20 dark:border-white/10',
        'rounded-xl',
        className
      )}
    >
      {children}
    </div>
  )
}

