// src/hooks/useFetch.ts
'use client'

import { useState, useEffect, useCallback } from 'react'

interface FetchState<T> {
  data: T | null
  loading: boolean
  error: string | null
}

interface UseFetchOptions {
  immediate?: boolean
  cache?: RequestCache
}

export function useFetch<T>(
  url: string,
  options: UseFetchOptions = { immediate: true }
) {
  const [state, setState] = useState<FetchState<T>>({
    data: null,
    loading: options.immediate ?? true,
    error: null
  })

  const execute = useCallback(async () => {
    setState(prev => ({ ...prev, loading: true, error: null }))

    try {
      const response = await fetch(url, {
        cache: options.cache || 'default'
      })

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`)
      }

      const data = await response.json()
      setState({
        data,
        loading: false,
        error: null
      })
    } catch (error) {
      setState({
        data: null,
        loading: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      })
    }
  }, [url, options.cache])

  useEffect(() => {
    if (options.immediate) {
      execute()
    }
  }, [execute, options.immediate])

  return {
    ...state,
    execute,
    refetch: execute
  }
}

// src/hooks/useInfiniteFetch.ts
'use client'

import { useState, useEffect, useCallback } from 'react'

interface InfiniteFetchState<T> {
  data: T[]
  loading: boolean
  error: string | null
  hasMore: boolean
  page: number
}

interface UseInfiniteFetchOptions<T> {
  initialPage?: number
  pageSize?: number
  getNextPageParam?: (lastPage: T[], allPages: T[][]) => string | null
}

export function useInfiniteFetch<T>(
  getUrl: (page: number) => string,
  options: UseInfiniteFetchOptions<T> = {}
) {
  const {
    initialPage = 1,
    pageSize = 10,
    getNextPageParam
  } = options

  const [state, setState] = useState<InfiniteFetchState<T>>({
    data: [],
    loading: true,
    error: null,
    hasMore: true,
    page: initialPage
  })

  const fetchPage = useCallback(async (page: number) => {
    try {
      const url = getUrl(page)
      const response = await fetch(url)

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`)
      }

      const newItems: T[] = await response.json()

      setState(prev => ({
        ...prev,
        data: page === initialPage ? newItems : [...prev.data, ...newItems],
        loading: false,
        hasMore: newItems.length === pageSize,
        page: page + 1
      }))
    } catch (error) {
      setState(prev => ({
        ...prev,
        loading: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      }))
    }
  }, [getUrl, initialPage, pageSize])

  const loadMore = useCallback(() => {
    if (!state.loading && state.hasMore) {
      fetchPage(state.page)
    }
  }, [state.loading, state.hasMore, state.page, fetchPage])

  const reset = useCallback(() => {
    setState({
      data: [],
      loading: true,
      error: null,
      hasMore: true,
      page: initialPage
    })
  }, [initialPage])

  useEffect(() => {
    fetchPage(initialPage)
  }, [fetchPage, initialPage])

  return {
    ...state,
    loadMore,
    reset
  }
}

// src/hooks/useRealtimeData.ts
'use client'

import { useState, useEffect, useCallback } from 'react'

interface RealtimeDataState<T> {
  data: T | null
  loading: boolean
  error: string | null
  connected: boolean
}

export function useRealtimeData<T>(
  url: string,
  updateUrl?: string
) {
  const [state, setState] = useState<RealtimeDataState<T>>({
    data: null,
    loading: true,
    error: null,
    connected: false
  })

  // 初始数据获取
  const fetchData = useCallback(async () => {
    try {
      const response = await fetch(url)
      if (!response.ok) throw new Error('Failed to fetch data')

      const data = await response.json()
      setState(prev => ({ ...prev, data, loading: false }))
    } catch (error) {
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'Unknown error',
        loading: false
      }))
    }
  }, [url])

  // 建立WebSocket连接或Server-Sent Events
  useEffect(() => {
    if (!updateUrl) return

    let eventSource: EventSource | null = null

    try {
      // 使用Server-Sent Events
      eventSource = new EventSource(updateUrl)

      eventSource.onopen = () => {
        setState(prev => ({ ...prev, connected: true }))
      }

      eventSource.onmessage = (event) => {
        try {
          const updatedData = JSON.parse(event.data)
          setState(prev => ({ ...prev, data: updatedData }))
        } catch (error) {
          console.error('Error parsing SSE data:', error)
        }
      }

      eventSource.onerror = () => {
        setState(prev => ({ ...prev, connected: false }))
      }
    } catch (error) {
      console.error('Error setting up real-time connection:', error)
    }

    return () => {
      if (eventSource) {
        eventSource.close()
      }
    }
  }, [updateUrl])

  useEffect(() => {
    fetchData()
  }, [fetchData])

  return state
}

