// src/components/Counter.tsx
'use client'

import { useState, useCallback } from 'react'

interface CounterProps {
  initialValue?: number
  max?: number
  min?: number
  onChange?: (value: number) => void
}

export function Counter({
  initialValue = 0,
  max = 100,
  min = 0,
  onChange
}: CounterProps) {
  const [count, setCount] = useState(initialValue)

  const increment = useCallback(() => {
    setCount(prev => {
      const newValue = Math.min(prev + 1, max)
      onChange?.(newValue)
      return newValue
    })
  }, [max, onChange])

  const decrement = useCallback(() => {
    setCount(prev => {
      const newValue = Math.max(prev - 1, min)
      onChange?.(newValue)
      return newValue
    })
  }, [min, onChange])

  const reset = useCallback(() => {
    setCount(initialValue)
    onChange?.(initialValue)
  }, [initialValue, onChange])

  return (
    <div className="flex items-center space-x-4">
      <button
        onClick={decrement}
        disabled={count <= min}
        className="px-3 py-1 bg-gray-200 rounded hover:bg-gray-300 disabled:opacity-50 disabled:cursor-not-allowed"
      >
        -
      </button>

      <span className="text-xl font-semibold w-12 text-center">
        {count}
      </span>

      <button
        onClick={increment}
        disabled={count >= max}
        className="px-3 py-1 bg-gray-200 rounded hover:bg-gray-300 disabled:opacity-50 disabled:cursor-not-allowed"
      >
        +
      </button>

      <button
        onClick={reset}
        className="px-3 py-1 bg-blue-500 text-white rounded hover:bg-blue-600"
      >
        重置
      </button>
    </div>
  )
}

// src/components/TodoList.tsx
'use client'

import { useState, useCallback, useMemo } from 'react'
import { v4 as uuidv4 } from 'uuid'

interface Todo {
  id: string
  text: string
  completed: boolean
  createdAt: Date
  completedAt?: Date
}

interface TodoListProps {
  initialTodos?: Todo[]
}

export function TodoList({ initialTodos = [] }: TodoListProps) {
  const [todos, setTodos] = useState<Todo[]>(initialTodos)
  const [newTodoText, setNewTodoText] = useState('')
  const [filter, setFilter] = useState<'all' | 'active' | 'completed'>('all')

  // 添加新任务
  const addTodo = useCallback(() => {
    if (!newTodoText.trim()) return

    const newTodo: Todo = {
      id: uuidv4(),
      text: newTodoText.trim(),
      completed: false,
      createdAt: new Date()
    }

    setTodos(prev => [...prev, newTodo])
    setNewTodoText('')
  }, [newTodoText])

  // 切换任务状态
  const toggleTodo = useCallback((id: string) => {
    setTodos(prev => prev.map(todo =>
      todo.id === id
        ? {
            ...todo,
            completed: !todo.completed,
            completedAt: !todo.completed ? new Date() : undefined
          }
        : todo
    ))
  }, [])

  // 删除任务
  const deleteTodo = useCallback((id: string) => {
    setTodos(prev => prev.filter(todo => todo.id !== id))
  }, [])

  // 编辑任务
  const editTodo = useCallback((id: string, newText: string) => {
    setTodos(prev => prev.map(todo =>
      todo.id === id ? { ...todo, text: newText } : todo
    ))
  }, [])

  // 过滤后的任务
  const filteredTodos = useMemo(() => {
    switch (filter) {
      case 'active':
        return todos.filter(todo => !todo.completed)
      case 'completed':
        return todos.filter(todo => todo.completed)
      default:
        return todos
    }
  }, [todos, filter])

  // 统计信息
  const stats = useMemo(() => ({
    total: todos.length,
    active: todos.filter(todo => !todo.completed).length,
    completed: todos.filter(todo => todo.completed).length
  }), [todos])

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-3xl font-bold mb-8">待办事项</h1>

      {/* 添加新任务 */}
      <div className="flex space-x-2 mb-6">
        <input
          type="text"
          value={newTodoText}
          onChange={(e) => setNewTodoText(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && addTodo()}
          placeholder="添加新任务..."
          className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        />
        <button
          onClick={addTodo}
          disabled={!newTodoText.trim()}
          className="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          添加
        </button>
      </div>

      {/* 过滤器 */}
      <div className="flex space-x-2 mb-6">
        {(['all', 'active', 'completed'] as const).map(filterType => (
          <button
            key={filterType}
            onClick={() => setFilter(filterType)}
            className={`px-4 py-2 rounded-lg ${
              filter === filterType
                ? 'bg-blue-500 text-white'
                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
            }`}
          >
            {filterType === 'all' && `全部 (${stats.total})`}
            {filterType === 'active' && `进行中 (${stats.active})`}
            {filterType === 'completed' && `已完成 (${stats.completed})`}
          </button>
        ))}
      </div>

      {/* 任务列表 */}
      <div className="space-y-2">
        {filteredTodos.map(todo => (
          <TodoItem
            key={todo.id}
            todo={todo}
            onToggle={toggleTodo}
            onDelete={deleteTodo}
            onEdit={editTodo}
          />
        ))}
      </div>

      {filteredTodos.length === 0 && (
        <div className="text-center py-8 text-gray-500">
          {filter === 'all' && '暂无任务'}
          {filter === 'active' && '暂无进行中的任务'}
          {filter === 'completed' && '暂无已完成的任务'}
        </div>
      )}
    </div>
  )
}

// 任务项组件
interface TodoItemProps {
  todo: Todo
  onToggle: (id: string) => void
  onDelete: (id: string) => void
  onEdit: (id: string, text: string) => void
}

function TodoItem({ todo, onToggle, onDelete, onEdit }: TodoItemProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [editText, setEditText] = useState(todo.text)

  const saveEdit = () => {
    if (editText.trim() && editText !== todo.text) {
      onEdit(todo.id, editText.trim())
    }
    setIsEditing(false)
  }

  const cancelEdit = () => {
    setEditText(todo.text)
    setIsEditing(false)
  }

  return (
    <div className="flex items-center space-x-3 p-3 bg-white border border-gray-200 rounded-lg hover:bg-gray-50">
      <input
        type="checkbox"
        checked={todo.completed}
        onChange={() => onToggle(todo.id)}
        className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500"
      />

      <div className="flex-1">
        {isEditing ? (
          <input
            type="text"
            value={editText}
            onChange={(e) => setEditText(e.target.value)}
            onKeyPress={(e) => {
              if (e.key === 'Enter') saveEdit()
              if (e.key === 'Escape') cancelEdit()
            }}
            onBlur={saveEdit}
            className="w-full px-2 py-1 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
            autoFocus
          />
        ) : (
          <span
            className={`
              cursor-text
              ${todo.completed ? 'line-through text-gray-500' : 'text-gray-900'}
            `}
            onClick={() => setIsEditing(true)}
          >
            {todo.text}
          </span>
        )}
      </div>

      <div className="text-sm text-gray-500">
        {todo.completed && todo.completedAt && (
          <span>完成于 {todo.completedAt.toLocaleDateString()}</span>
        )}
      </div>

      <button
        onClick={() => onDelete(todo.id)}
        className="px-2 py-1 text-red-600 hover:bg-red-50 rounded"
      >
        删除
      </button>
    </div>
  )
}

// src/contexts/AuthContext.tsx
'use client'

import React, { createContext, useContext, useReducer, useEffect } from 'react'

// 用户类型
interface User {
  id: string
  name: string
  email: string
  avatar?: string
  role: 'admin' | 'user'
}

// 认证状态
interface AuthState {
  user: User | null
  isAuthenticated: boolean
  loading: boolean
  error: string | null
}

// 认证动作
type AuthAction =
  | { type: 'AUTH_START' }
  | { type: 'AUTH_SUCCESS'; payload: User }
  | { type: 'AUTH_ERROR'; payload: string }
  | { type: 'LOGOUT' }
  | { type: 'CLEAR_ERROR' }

// 初始状态
const initialState: AuthState = {
  user: null,
  isAuthenticated: false,
  loading: false,
  error: null
}

// Reducer
function authReducer(state: AuthState, action: AuthAction): AuthState {
  switch (action.type) {
    case 'AUTH_START':
      return {
        ...state,
        loading: true,
        error: null
      }
    case 'AUTH_SUCCESS':
      return {
        ...state,
        loading: false,
        user: action.payload,
        isAuthenticated: true,
        error: null
      }
    case 'AUTH_ERROR':
      return {
        ...state,
        loading: false,
        user: null,
        isAuthenticated: false,
        error: action.payload
      }
    case 'LOGOUT':
      return {
        ...state,
        user: null,
        isAuthenticated: false,
        loading: false,
        error: null
      }
    case 'CLEAR_ERROR':
      return {
        ...state,
        error: null
      }
    default:
      return state
  }
}

// Context
const AuthContext = createContext<{
  state: AuthState
  login: (email: string, password: string) => Promise<void>
  logout: () => void
  clearError: () => void
} | null>(null)

// Provider组件
export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(authReducer, initialState)

  // 登录函数
  const login = async (email: string, password: string) => {
    dispatch({ type: 'AUTH_START' })

    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.error || '登录失败')
      }

      dispatch({ type: 'AUTH_SUCCESS', payload: data.user })
    } catch (error) {
      dispatch({
        type: 'AUTH_ERROR',
        payload: error instanceof Error ? error.message : '未知错误'
      })
    }
  }

  // 登出函数
  const logout = () => {
    dispatch({ type: 'LOGOUT' })
  }

  // 清除错误
  const clearError = () => {
    dispatch({ type: 'CLEAR_ERROR' })
  }

  // 检查本地存储的认证状态
  useEffect(() => {
    const savedUser = localStorage.getItem('user')
    if (savedUser) {
      try {
        const user = JSON.parse(savedUser)
        dispatch({ type: 'AUTH_SUCCESS', payload: user })
      } catch {
        localStorage.removeItem('user')
      }
    }
  }, [])

  // 保存用户信息到本地存储
  useEffect(() => {
    if (state.user) {
      localStorage.setItem('user', JSON.stringify(state.user))
    } else {
      localStorage.removeItem('user')
    }
  }, [state.user])

  return (
    <AuthContext.Provider value={{ state, login, logout, clearError }}>
      {children}
    </AuthContext.Provider>
  )
}

// Hook
export function useAuth() {
  const context = useContext(AuthContext)
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider')
  }
  return context
}

// src/stores/useUserStore.ts
import { create } from 'zustand'
import { devtools, persist, subscribeWithSelector } from 'zustand/middleware'
import { immer } from 'zustand/middleware/immer'

// 用户类型
interface User {
  id: string
  name: string
  email: string
  avatar?: string
  role: 'admin' | 'user'
  preferences: {
    theme: 'light' | 'dark' | 'system'
    language: string
    notifications: boolean
  }
}

// 用户状态接口
interface UserState {
  // 状态
  user: User | null
  isAuthenticated: boolean
  loading: boolean
  error: string | null

  // 动作
  setUser: (user: User) => void
  updateUser: (updates: Partial<User>) => void
  updatePreferences: (preferences: Partial<User['preferences']>) => void
  setLoading: (loading: boolean) => void
  setError: (error: string | null) => void
  clearError: () => void
  logout: () => void

  // 异步动作
  login: (email: string, password: string) => Promise<void>
  fetchUser: () => Promise<void>
  updateProfile: (updates: Partial<User>) => Promise<void>
}

// 创建store
export const useUserStore = create<UserState>()(
  devtools(
    subscribeWithSelector(
      persist(
        immer((set, get) => ({
          // 初始状态
          user: null,
          isAuthenticated: false,
          loading: false,
          error: null,

          // 设置用户
          setUser: (user) => {
            set((state) => {
              state.user = user
              state.isAuthenticated = true
              state.error = null
            })
          },

          // 更新用户信息
          updateUser: (updates) => {
            set((state) => {
              if (state.user) {
                Object.assign(state.user, updates)
              }
            })
          },

          // 更新用户偏好
          updatePreferences: (preferences) => {
            set((state) => {
              if (state.user) {
                Object.assign(state.user.preferences, preferences)
              }
            })
          },

          // 设置加载状态
          setLoading: (loading) => {
            set((state) => {
              state.loading = loading
            })
          },

          // 设置错误
          setError: (error) => {
            set((state) => {
              state.error = error
              state.loading = false
            })
          },

          // 清除错误
          clearError: () => {
            set((state) => {
              state.error = null
            })
          },

          // 登出
          logout: () => {
            set((state) => {
              state.user = null
              state.isAuthenticated = false
              state.error = null
              state.loading = false
            })
          },

          // 登录
          login: async (email, password) => {
            const { setLoading, setError, setUser } = get()

            setLoading(true)
            setError(null)

            try {
              const response = await fetch('/api/auth/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, password })
              })

              const data = await response.json()

              if (!response.ok) {
                throw new Error(data.error || '登录失败')
              }

              setUser(data.user)
            } catch (error) {
              setError(error instanceof Error ? error.message : '登录失败')
            } finally {
              setLoading(false)
            }
          },

          // 获取用户信息
          fetchUser: async () => {
            const { setLoading, setError, setUser } = get()

            setLoading(true)

            try {
              const response = await fetch('/api/user/profile')

              if (!response.ok) {
                throw new Error('获取用户信息失败')
              }

              const data = await response.json()
              setUser(data.user)
            } catch (error) {
              setError(error instanceof Error ? error.message : '获取用户信息失败')
            } finally {
              setLoading(false)
            }
          },

          // 更新个人资料
          updateProfile: async (updates) => {
            const { setLoading, setError, updateUser } = get()

            setLoading(true)

            try {
              const response = await fetch('/api/user/profile', {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updates)
              })

              const data = await response.json()

              if (!response.ok) {
                throw new Error(data.error || '更新失败')
              }

              updateUser(data.user)
            } catch (error) {
              setError(error instanceof Error ? error.message : '更新失败')
            } finally {
              setLoading(false)
            }
          }
        })),
        {
          name: 'user-store',
          partialize: (state) => ({
            user: state.user,
            isAuthenticated: state.isAuthenticated
          })
        }
      )
    ),
    {
      name: 'user-store'
    }
  )
)

// 选择器hooks
export const useUser = () => useUserStore((state) => state.user)
export const useIsAuthenticated = () => useUserStore((state) => state.isAuthenticated)
export const useUserLoading = () => useUserStore((state) => state.loading)
export const useUserError = () => useUserStore((state) => state.error)
export const useUserPreferences = () => useUserStore((state) => state.user?.preferences)

// src/hooks/useApiQuery.ts
'use client'

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { useUserStore } from '@/stores/useUserStore'

// API查询配置
const defaultQueryConfig = {
  staleTime: 5 * 60 * 1000, // 5分钟
  cacheTime: 10 * 60 * 1000, // 10分钟
  retry: 3,
  retryDelay: (attemptIndex: number) => Math.min(1000 * 2 ** attemptIndex, 30000)
}

// 通用查询Hook
export function useApiQuery<T>(
  queryKey: string[],
  queryFn: () => Promise<T>,
  config = {}
) {
  const user = useUserStore(state => state.user)

  return useQuery({
    queryKey,
    queryFn,
    ...defaultQueryConfig,
    ...config,
    enabled: !!user // 只有用户登录后才执行查询
  })
}

// 文章查询Hook
export function usePosts(params: { page?: number; category?: string } = {}) {
  return useApiQuery(
    ['posts', params],
    () => fetchPosts(params),
    {
      staleTime: 2 * 60 * 1000 // 2分钟
    }
  )
}

async function fetchPosts(params: { page?: number; category?: string }) {
  const searchParams = new URLSearchParams()
  if (params.page) searchParams.set('page', params.page.toString())
  if (params.category) searchParams.set('category', params.category)

  const response = await fetch(`/api/posts?${searchParams}`)
  if (!response.ok) throw new Error('Failed to fetch posts')
  return response.json()
}

// 单篇文章查询Hook
export function usePost(id: string) {
  return useApiQuery(
    ['post', id],
    () => fetchPost(id),
    {
      staleTime: 10 * 60 * 1000 // 10分钟
    }
  )
}

async function fetchPost(id: string) {
  const response = await fetch(`/api/posts/${id}`)
  if (!response.ok) throw new Error('Failed to fetch post')
  return response.json()
}

// 创建文章Mutation Hook
export function useCreatePost() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (postData: {
      title: string
      content: string
      category?: string
    }) => {
      const response = await fetch('/api/posts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(postData)
      })

      if (!response.ok) throw new Error('Failed to create post')
      return response.json()
    },
    onSuccess: (newPost) => {
      // 使文章列表缓存失效
      queryClient.invalidateQueries({ queryKey: ['posts'] })

      // 将新文章添加到缓存
      queryClient.setQueryData(['post', newPost.id], newPost)
    },
    onError: (error) => {
      console.error('Error creating post:', error)
    }
  })
}

// 更新文章Mutation Hook
export function useUpdatePost() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async ({ id, ...updates }: {
      id: string
      title?: string
      content?: string
      category?: string
    }) => {
      const response = await fetch(`/api/posts/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updates)
      })

      if (!response.ok) throw new Error('Failed to update post')
      return response.json()
    },
    onSuccess: (updatedPost) => {
      // 更新缓存中的文章
      queryClient.setQueryData(['post', updatedPost.id], updatedPost)

      // 使文章列表缓存失效
      queryClient.invalidateQueries({ queryKey: ['posts'] })
    },
    onError: (error) => {
      console.error('Error updating post:', error)
    }
  })
}

// src/hooks/useFormState.ts
'use client'

import { useForm, UseFormReturn } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { useState } from 'react'

// 通用表单状态Hook
export function useFormState<T extends z.ZodSchema>(
  schema: T,
  defaultValues?: Partial<z.infer<T>>
) {
  const form = useForm<z.infer<T>>({
    resolver: zodResolver(schema),
    defaultValues,
    mode: 'onChange'
  })

  const [isSubmitting, setIsSubmitting] = useState(false)
  const [submitError, setSubmitError] = useState<string | null>(null)

  const handleSubmit = async (onSubmit: (data: z.infer<T>) => Promise<void>) => {
    const isValid = await form.trigger()

    if (!isValid) {
      return
    }

    setIsSubmitting(true)
    setSubmitError(null)

    try {
      const data = form.getValues()
      await onSubmit(data)
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : '提交失败')
    } finally {
      setIsSubmitting(false)
    }
  }

  return {
    form,
    isSubmitting,
    submitError,
    handleSubmit,
    clearError: () => setSubmitError(null)
  }
}

// 登录表单Hook
const loginSchema = z.object({
  email: z.string().email('请输入有效的邮箱地址'),
  password: z.string().min(6, '密码至少需要6个字符'),
