// hooks/useLocalStorage.ts
import { useState, useEffect } from "react"

export function useLocalStorage<T>(key: string, initialValue: T) {
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === "undefined") {
      return initialValue
    }
    try {
      const item = window.localStorage.getItem(key)
      return item ? JSON.parse(item) : initialValue
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error)
      return initialValue
    }
  })

  const setValue = (value: T | ((val: T) => T)) => {
    try {
      const valueToStore = value instanceof Function ? value(storedValue) : value
      setStoredValue(valueToStore)
      if (typeof window !== "undefined") {
        window.localStorage.setItem(key, JSON.stringify(valueToStore))
      }
    } catch (error) {
      console.error(`Error setting localStorage key "${key}":`, error)
    }
  }

  return [storedValue, setValue] as const
}

// __tests__/hooks/useLocalStorage.test.ts
import { describe, it, expect, beforeEach, afterEach } from "vitest"
import { renderHook, act } from "@testing-library/react"
import { useLocalStorage } from "@/hooks/useLocalStorage"

describe("useLocalStorage Hook", () => {
  beforeEach(() => {
    // 清除localStorage
    localStorage.clear()
  })

  afterEach(() => {
    localStorage.clear()
  })

  it("returns initial value when localStorage is empty", () => {
    const { result } = renderHook(() => useLocalStorage("test-key", "initial-value"))

    const [value] = result.current
    expect(value).toBe("initial-value")
  })

  it("returns stored value from localStorage", () => {
    localStorage.setItem("test-key", JSON.stringify("stored-value"))

    const { result } = renderHook(() => useLocalStorage("test-key", "initial-value"))

    const [value] = result.current
    expect(value).toBe("stored-value")
  })

  it("updates localStorage when value changes", () => {
    const { result } = renderHook(() => useLocalStorage("test-key", "initial-value"))

    const [, setValue] = result.current

    act(() => {
      setValue("new-value")
    })

    expect(result.current[0]).toBe("new-value")
    expect(localStorage.getItem("test-key")).toBe(JSON.stringify("new-value"))
  })

  it("works with function updater", () => {
    const { result } = renderHook(() => useLocalStorage("counter", 0))

    const [, setCounter] = result.current

    act(() => {
      setCounter(prev => prev + 1)
    })

    expect(result.current[0]).toBe(1)
    expect(localStorage.getItem("counter")).toBe("1")
  })

  it("handles complex objects", () => {
    const initialObject = { name: "John", age: 30 }
    const { result } = renderHook(() => useLocalStorage("user", initialObject))

    const [, setUser] = result.current

    act(() => {
      setUser({ ...initialObject, age: 31 })
    })

    expect(result.current[0]).toEqual({ name: "John", age: 31 })
    expect(localStorage.getItem("user")).toBe(JSON.stringify({ name: "John", age: 31 }))
  })
})

// context/AuthContext.tsx
import { createContext, useContext, useState } from 'react'

interface User {
  id: number
  email: string
  name: string
}

interface AuthContextType {
  user: User | null
  login: (email: string, password: string) => Promise<boolean>
  logout: () => void
  isLoading: boolean
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const login = async (email: string, password: string): Promise<boolean> => {
    setIsLoading(true)
    try {
      const response = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      })

      if (response.ok) {
        const userData = await response.json()
        setUser(userData)
        return true
      }
      return false
    } catch (error) {
      console.error("Login error:", error)
      return false
    } finally {
      setIsLoading(false)
    }
  }

  const logout = () => {
    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ user, login, logout, isLoading }}>
      {children}
    </AuthContext.Provider>
  )
}

export const useAuth = () => {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider")
  }
  return context
}

