export async function publishPost(id: string) {
  return prisma.$transaction(async (tx) => {
    const post = await tx.post.findUnique({ where: { id } });
    if (!post) throw new HttpError(404, '文章不存在');
    return tx.post.update({
      where: { id },
      data: { published: true },
    });
  }); // 回调抛错自动回滚
}

