async function manualCopy(src: Readable, dst: Writable) {
  for await (const chunk of src) {
    if (!dst.write(chunk)) {
      // 缓冲已满：等待 drain 再继续写入
      await new Promise<void>((resolve) => dst.once("drain", resolve));
    }
  }
  dst.end();
}

