// src/features/todos/use-todos.ts
import { useQuery } from '@tanstack/react-query'

export interface Todo {
  id: number
  title: string
  done: boolean
}

// API 层与 Hook 层分离：queryFn 只负责"取数据"，方便测试与复用
async function fetchTodos(): Promise<Todo[]> {
  const res = await fetch('/api/todos')
  if (!res.ok) throw new Error(`加载失败: ${res.status}`) // 抛错才会进入 isError 分支
  return res.json()
}

// 键是数组：['资源名', ...参数]，后续失效与筛选都靠它
export function useTodos() {
  return useQuery({
    queryKey: ['todos'],
    queryFn: fetchTodos,
  })
}

function TodoList() {
  const { isPending, isError, error, data } = useTodos()

  if (isPending) return <p>加载中…</p>        // v5：isPending 时 data 类型收窄为 undefined，判空后再渲染
  if (isError) return <p role="alert">出错了：{error.message}</p>

  return (
    <ul>
      {data.map((todo) => (
        <li key={todo.id}>{todo.title}</li>
      ))}
    </ul>
  )
}

import { useMutation, useQueryClient } from '@tanstack/react-query'
import type { Todo } from './use-todos'

async function createTodo(input: { title: string }): Promise<Todo> {
  const res = await fetch('/api/todos', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) throw new Error('创建失败')
  return res.json()
}

export function useCreateTodo() {
  const queryClient = useQueryClient() // 在 Hook 里拿到全局 client

  return useMutation({
    mutationFn: createTodo,
    onSuccess: () => {
      // 让 ['todos'] 缓存失效 → 活跃的 useQuery 自动重新请求
      void queryClient.invalidateQueries({ queryKey: ['todos'] })
    },
    onError: (err) => {
      // 统一错误提示，组件里也可以再单独处理
      console.error('创建 todo 失败', err)
    },
  })
}

function AddTodoForm() {
  const createTodo = useCreateTodo()

  return (
    <button
      onClick={() => createTodo.mutate({ title: '学习 Query v5' })}
      disabled={createTodo.isPending} // mutation 的加载态也叫 isPending
    >
      {createTodo.isPending ? '提交中…' : '添加'}
    </button>
  )
}

// 带参数的查询：对象放在键的最后一段
export function useTodoDetail(id: number) {
  return useQuery({
    queryKey: ['todos', 'detail', id], // id 变化 → 生成新的缓存条目
    queryFn: () => fetchTodo(id),
    enabled: id > 0, // 条件查询：id 无效时不发起请求
  })
}

import { useInfiniteQuery } from '@tanstack/react-query'

interface Page {
  items: { id: number; title: string }[]
  nextCursor: number | null // 后端返回下一页游标；null 表示没有更多
}

async function fetchFeed({ pageParam }: { pageParam: number }): Promise<Page> {
  const res = await fetch(`/api/feed?cursor=${pageParam}&limit=20`)
  if (!res.ok) throw new Error('加载信息流失败')
  return res.json()
}

export function useFeed() {
  return useInfiniteQuery({
    queryKey: ['feed'],
    queryFn: fetchFeed,
    initialPageParam: 0, // v5 起必填：显式提供初始页参
    getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined,
    maxPages: 10, // v5 起支持：最多保留 10 页，防止无限滚动撑爆内存
  })
}

function Feed() {
  const { data, isPending, isError, fetchNextPage, hasNextPage, isFetchingNextPage } = useFeed()

  if (isPending) return <p>加载中…</p>
  if (isError) return <p role="alert">加载失败</p>

  // data.pages 是按请求顺序排列的每页结果
  const items = data.pages.flatMap((page) => page.items)

  return (
    <div>
      {items.map((item) => (
        <article key={item.id}>{item.title}</article>
      ))}
      <button
        onClick={() => fetchNextPage()}
        disabled={!hasNextPage || isFetchingNextPage}
      >
        {isFetchingNextPage ? '加载中…' : hasNextPage ? '加载更多' : '没有更多了'}
      </button>
    </div>
  )
}

import { useMutation, useQueryClient } from '@tanstack/react-query'
import type { Todo } from '../basics/03-query-fundamentals'

export function useToggleTodo() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: (todo: Todo) =>
      fetch(`/api/todos/${todo.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ done: !todo.done }),
      }).then((res) => {
        if (!res.ok) throw new Error('切换失败')
        return res.json() as Promise<Todo>
      }),

    onMutate: async (todo) => {
      // ① 取消该键的所有在途请求，防止旧响应覆盖乐观数据
      await queryClient.cancelQueries({ queryKey: ['todos'] })

      // ② 快照当前缓存，用于回滚
      const previous = queryClient.getQueryData<Todo[]>(['todos'])

      // ③ 立即把乐观结果写入缓存（UI 即时变化）
      queryClient.setQueryData<Todo[]>(['todos'], (old = []) =>
        old.map((t) => (t.id === todo.id ? { ...t, done: !t.done } : t)),
      )

      // 返回的 context 会传给 onError 与 onSettled
      return { previous }
    },

    onError: (_err, _todo, context) => {
      // ④ 出错时用快照回滚
      if (context?.previous) {
        queryClient.setQueryData(['todos'], context.previous)
      }
    },

    onSettled: () => {
      // 无论成败，最终与服务端对齐一次
      void queryClient.invalidateQueries({ queryKey: ['todos'] })
    },
  })
}

await queryClient.invalidateQueries({ queryKey: ['todos'] })              // 前缀匹配：todos 全家
await queryClient.invalidateQueries({ queryKey: ['todos', 'detail', 7] }) // 只失效 id=7 的详情
await queryClient.invalidateQueries({
  predicate: (q) => q.queryKey[0] === 'todos' && (q.state.dataUpdatedAt ?? 0) < Date.now() - 3_600_000,
}) // 自定义谓词：只失效超过 1 小时未更新的 todos 查询

// 默认：失效 + 立即重新请求活跃查询（inactive 只标记为 stale）
await queryClient.invalidateQueries({ queryKey: ['todos'] })

// 失效但不发起请求：等下次挂载/聚焦时再取
await queryClient.invalidateQueries({
  queryKey: ['todos'],
  refetchType: 'none',
})

// 连不活跃的缓存也强制重取
await queryClient.invalidateQueries({ queryKey: ['todos'], refetchType: 'all' })

