  component: () => (<><nav /><Outlet /></>),  // 不渲染 Outlet 子路由不出现
  notFoundComponent: NotFound,           // 匹配不到/抛 notFound() 时
  errorComponent: ErrorCard,             // 组件树抛错时（false 可关闭兜底 UI）
})
createRoute({
  getParentRoute: () => rootRoute,
  path: '/$postId',
  pendingComponent: Pending,             // 本路由 loader/beforeLoad 挂起时
  loader: ({ params }) => fetchPost(params.postId),
  beforeLoad: () => { if (bad) throw notFound() },
})

// 全局兜底
createRouter({
  routeTree,
  defaultPendingComponent: Pending,
  defaultErrorComponent: ErrorCard,
  defaultNotFoundComponent: NotFound,
  defaultPendingMs: 1000,     // 挂起超过该毫秒才显示 pending UI（默认 1000）
  defaultPendingMinMs: 500,   // pending UI 最少停留毫秒（默认 500），防闪烁
})

import {
  createRootRoute, createRoute, createRouter, Outlet, notFound,
} from '@tanstack/react-router'
import type { ErrorComponentProps } from '@tanstack/react-router'

function NotFound() {
  return <p>页面不存在</p>
}

function ErrorCard({ error, reset }: ErrorComponentProps) {
  return (
    <div>
      {/* error 类型是 unknown：先收窄再取 message */}
      <p>{error instanceof Error ? error.message : String(error)}</p>
      <button onClick={reset}>重试</button>
    </div>
  )
}

function Pending() {
  return <p>加载中…</p>
}

// Outlet：布局路由的核心——导航常驻，内容区随 URL 切换
const rootRoute = createRootRoute({
  component: () => (
    <div>
      <nav>站点导航</nav>
      <Outlet />
    </div>
  ),
  notFoundComponent: NotFound,
  errorComponent: ErrorCard,
})

const postsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/posts',
  pendingComponent: Pending,
})

const postRoute = createRoute({
  getParentRoute: () => postsRoute,
  path: '/$postId',
  loader: ({ params }) => fetchPost(params.postId),
  // loader 前置校验：抛 notFound() 交给最近一层的 notFoundComponent
  beforeLoad: ({ params }) => {
    if (params.postId === '0') throw notFound()
  },
})

const routeTree = rootRoute.addChildren([postsRoute.addChildren([postRoute])])

const router = createRouter({
  routeTree,
  defaultPendingComponent: Pending,   // 未显式声明 pendingComponent 的路由走这里
  defaultErrorComponent: ErrorCard,
  defaultNotFoundComponent: NotFound,
  defaultPendingMs: 300,              // 显式调小：更快出现占位
  defaultPendingMinMs: 500,
})

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
}

import { useMatch, useMatches, useRouter } from '@tanstack/react-router'

// useMatch：读取指定路由的匹配（loaderData 按路由类型收窄）
function PostHeader() {
  const match = useMatch({ from: '/posts/$postId' })
  const matchStatus = useMatch({ from: '/posts/$postId', select: (m) => m.status })
  const nearest = useMatch({ strict: false }) // 不关心具体路由时取"最近匹配"
  const currentRouter = useRouter()

  return (
    <div>
      <h1>{match.loaderData?.title}</h1>
      <span>{matchStatus}</span>
      <span>{nearest.routeId}</span>
      {/* 重跑当前 URL 全部匹配路由的 loader/beforeLoad（≠ Query 的 invalidateQueries） */}
      <button onClick={() => void currentRouter.invalidate()}>刷新数据</button>
      {/* filter 只失效部分匹配 */}
      <button
        onClick={() =>
          void currentRouter.invalidate({ filter: (m) => m.routeId === '/posts/$postId' })
        }
      >
        刷新本页
      </button>
    </div>
  )
}

// useMatches：面包屑 / 全局加载条
function Breadcrumbs() {
  const matches = useMatches()
  const routeIds = useMatches({ select: (ms) => ms.map((m) => m.routeId) })
  const anyLoading = useMatches({
    select: (ms) => ms.some((m) => m.isFetching !== false),
  })
  return (
    <div>
      {matches.map((m) => (
        <span key={m.id}>{m.routeId}</span>
      ))}
      {routeIds.join(' / ')}
      {anyLoading ? '加载中' : null}
    </div>
  )
}

