    // 被覆盖属性须当前作用域可见——private 属性只能在类内方法里覆盖
    public function withExtra(OrderLine $extra): static
    {
        return clone($this, ['items' => [...$this->items, $extra]]);
    }
}

$cart = new Cart();
$cart->add($line);

$copy = $cart->withExtra(new OrderLine('NEW', 1, 9.9));   // 新 Cart 实例，$cart 不受影响

// 三元运算符：二选一
$label = $score >= 60 ? '及格' : '不及格';

// 空合并 ??：专治"存在吗"问题，比 isset + 三元简洁
$page = (int) ($_GET['page'] ?? '1');

// 空合并可以链式兜底，无需括号
$name = $input ?? $default ?? 'guest';

// 判断归属：in_array 带严格比较
$allowed = ['GET', 'POST'];
if (in_array($method, $allowed, true)) {
    // ...
}

// PHP 8.0 起字符串内置包含判断，不再需要 strpos !== false
if (str_contains($userAgent, 'Chrome')) {
    echo 'Chrome 浏览器', PHP_EOL;
}

// 1. 值映射：替代查表式 if-else
$lang = match ($locale) {
    'zh'    => '中文',
    'en'    => 'English',
    'ja'    => '日本語',
    default => 'Unknown',
};

// 2. 多条件并列：一个分支匹配多个值
$ext = match (strtolower($file)) {
    'jpg', 'jpeg', 'png', 'gif', 'webp' => 'image',
    'mp4', 'mov', 'avi'                 => 'video',
    'pdf', 'doc', 'docx'                => 'document',
    default                             => 'other',
};

// 3. 条件分支：match (true) 配合布尔表达式
$fee = match (true) {
    $weight <= 1   => 5.0,
    $weight <= 5   => 12.0,
    $weight <= 20  => 30.0,
    default        => $weight * 2.0,
};

// for：已知次数
for ($i = 0; $i < 5; $i++) {
    echo $i, ' ';
}
echo PHP_EOL;

// while：先判断后执行
$retries = 0;
while ($retries < 3) {
    if (random_int(0, 2) === 0) {
        break;              // 模拟成功即退出
    }
    $retries++;
}

// do-while：至少执行一次
do {
    $input = random_int(1, 6);
    echo "掷出: {$input}", PHP_EOL;
} while ($input !== 6);

foreach ($orders as $order) {
    foreach ($order['items'] as $item) {
        if ($item['qty'] <= 0) {
            continue 2;     // 跳过该订单，继续外层下一单
        }
        if ($order['status'] === 'cancelled') {
            break 2;        // 全部终止
        }
    }
}

